UPDATE tasks SET statement = '{"brief":"Внешний сервис проверки контрагентов отвечает то за 200 мс, то по 30 секунд, а иногда падает. Нужны правила вызова.","context":["Ваша система при создании заявки синхронно вызывает внешний сервис проверки контрагента (HTTP REST, JSON). Сервис сторонний, SLA у него нет: обычно отвечает за 200–500 мс, но в часы пик — до 30 секунд, иногда возвращает 500, иногда соединение просто обрывается.","Сейчас в коде один таймаут 60 секунд и ни одной повторной попытки. В результате при деградации внешнего сервиса у нас «висит» весь поток создания заявок: пользователи видят спиннер, пул соединений исчерпывается, падают и те операции, которые внешнего сервиса не касаются."],"goal":"Описать правила вызова внешнего сервиса так, чтобы наша система деградировала предсказуемо, а данные не расходились.","inputs":["Метод \u003ccode\u003ePOST /counterparty/check\u003c/code\u003e — на вход ИНН и ID заявки, на выход вердикт (ok / reject / need_review).","Вызов синхронный из потока обработки заявки: пользователь ждёт ответ на экране.","Пиковая нагрузка — 40 запросов в секунду, средний объём ответа — 2 КБ.","Внешний сервис не идемпотентен по документации: повторный вызов может создать вторую запись проверки у них в системе (но вердикт по тому же ИНН одинаковый)."],"deliverables":["Значения таймаутов (connection / read) и почему именно такие.","Политика повторных попыток: сколько, с какой паузой, на какие коды ответа и ошибки сети.","Поведение при исчерпании попыток: что видит пользователь и что происходит с заявкой.","Как не допустить эффекта «лавины» и исчерпания пула соединений.","Какие метрики и логи нужны, чтобы деградацию было видно до звонка от бизнеса."],"constraints":["Нельзя требовать от внешнего сервиса доработок — он чужой и меняться не будет.","Заявка не должна потеряться: если вердикт не получен, её судьба должна быть определена.","Ответ пользователю — не дольше 5 секунд в худшем случае."],"interview":"«У нас внешний сервис иногда отвечает по 30 секунд. Что вы предложите, чтобы это не роняло нашу систему?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Решение","content":"\u003ch3\u003eПравила вызова внешнего сервиса\u003c/h3\u003e\u003cp\u003eОпишите таймауты, ретраи и поведение при отказе.\u003c/p\u003e\u003cul\u003e\u003cli\u003eТаймаут соединения: \u003c/li\u003e\u003cli\u003eТаймаут чтения: \u003c/li\u003e\u003cli\u003eЧисло попыток: \u003c/li\u003e\u003c/ul\u003e"},{"type":"mermaid","title":"Схема деградации","content":"flowchart TD\n  A[Создание заявки] --\u003e B{Вызов внешнего сервиса}\n  B --\u003e|успех| C[Продолжаем обработку]\n  B --\u003e|таймаут / 5xx| D[Повторная попытка?]\n  D --\u003e|да| B\n  D --\u003e|нет| E[Что делаем с заявкой?]\n  E --\u003e F[?]\n"}]'::jsonb, rubric = '[{"id":"timeout-split","title":"Раздельные таймауты connection и read, бюджет времени на весь вызов","weight":"high","weightValue":null,"focus":"arch","keywords":["connection","connect","read timeout","таймаут соединения","таймаут чтения","бюджет","deadline","5 секунд","5 сек"],"why":"Один общий таймаут не позволяет отличить «не можем достучаться» от «сервис думает». Без бюджета времени на операцию ретраи умножают ожидание пользователя.","critical":false},{"id":"retry-policy","title":"Политика ретраев: экспоненциальная пауза, джиттер, лимит попыток, фильтр по типам ошибок","weight":"high","weightValue":null,"focus":"arch","keywords":["ретра","retry","повторн","экспоненц","backoff","джиттер","jitter","пауз","503","502","429","retry-after"],"why":"Без экспоненциальной паузы и джиттера ретраи превращают деградацию внешнего сервиса в DDoS и синхронно добивают свою же систему.","critical":false},{"id":"idempotency-risk","title":"Учтено, что внешний сервис не идемпотентен: ретраи не создают дублей проверок","weight":"high","weightValue":null,"focus":"sa","keywords":["идемпотент","дубл","повторн","ключ","request id","идентификатор запроса","не создаст вторую"],"why":"Задача прямо говорит, что повторный вызов может создать вторую запись у партнёра. Ретраи без оговорки — это ошибка проектирования, а не деталь.","critical":false},{"id":"fallback","title":"Определено поведение при исчерпании попыток: статус заявки, что видит пользователь","weight":"high","weightValue":null,"focus":"sa","keywords":["need_review","статус","отлож","асинхрон","очередь","вручную","деград","fallback","пользовател","заявка не теряет","черновик"],"why":"Бизнесу важно не «мы получили 504», а что стало с заявкой. Без явного fallback-сценария заявка зависнет в неопределённом состоянии.","critical":false},{"id":"bulkhead","title":"Защита от лавины: отдельный пул соединений / circuit breaker / асинхронизация","weight":"mid","weightValue":null,"focus":"arch","keywords":["circuit breaker","предохранит","пул соединений","bulkhead","полук","изоляция","асинхрон","очередь","rate limit","деград"],"why":"Исчерпание общего пула соединений — причина того, что падают соседние операции. Нужна изоляция отказа.","critical":false},{"id":"observability","title":"Метрики, логи и алерты: доля ошибок, время ответа, число ретраев, срабатывания breaker","weight":"mid","weightValue":null,"focus":"arch","keywords":["метрик","p95","p99","лог","алерт","мониторинг","trace","correlation","dash"],"why":"Деградацию внешнего сервиса должны замечать вы, а не клиент. Без метрик политика ретраев настраивается вслепую.","critical":false},{"id":"nfr-numbers","title":"Численные НФТ и проверка на пиковую нагрузку (40 rps × попытки = ?)","weight":"mid","weightValue":null,"focus":"sa","keywords":["40","rps","нагрузк","секунд в сутки","ёмкост","qps","расчёт","оценк"],"why":"Ретраи умножают нагрузку на внешний сервис. Аналитик обязан посчитать, что получится на пике, иначе «безопасная» политика создаст инцидент.","critical":false}]'::jsonb, hints = '["Начните с бюджета времени: пользователь ждёт максимум 5 секунд. Сколько попыток физически влезает в этот бюджет?","Ретраить имеет смысл только временные ошибки: обрыв соединения, 502/503/504, 429. На 400 повторять бессмысленно.","Подумайте, что делать с заявкой, когда вердикта нет: блокировать пользователя или переводить заявку в асинхронный статус."]'::jsonb, interview_questions = '["Почему вы выбрали именно такой таймаут чтения, а не 10 секунд?","Что произойдёт при 429 с заголовком Retry-After?","Как вы поймёте, что внешний сервис деградировал, до жалоб пользователей?","Внешний сервис не идемпотентен — как ретраить безопасно?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Бюджет времени\u003c/h3\u003e\u003cp\u003eПользователь ждёт не более \u003cstrong\u003e5 секунд\u003c/strong\u003e. Значит весь вызов вместе с ретраями должен укладываться в этот бюджет: connection timeout \u003cstrong\u003e1 сек\u003c/strong\u003e, read timeout \u003cstrong\u003e1.5 сек\u003c/strong\u003e, максимум \u003cstrong\u003e2 повторные попытки\u003c/strong\u003e с паузами 300 мс и 900 мс (+ джиттер ±20%). Худший случай: 1.5 + 0.3 + 1.5 + 0.9 + 1.5 ≈ 5.7 сек — урезаем read timeout до 1.2 сек, чтобы гарантированно уложиться.\u003c/p\u003e\u003ch3\u003e2. Что ретраим\u003c/h3\u003e\u003cul\u003e\u003cli\u003eСетевые ошибки (connection refused, reset, обрыв) — да.\u003c/li\u003e\u003cli\u003e502 / 503 / 504 — да.\u003c/li\u003e\u003cli\u003e429 — да, по заголовку \u003ccode\u003eRetry-After\u003c/code\u003e, если он есть.\u003c/li\u003e\u003cli\u003e400 / 401 / 403 / 404 / 422 — нет, это наша ошибка, повтор не поможет.\u003c/li\u003e\u003cli\u003eRead timeout — осторожно: запрос мог быть обработан. Так как сервис не идемпотентен, передаём \u003ccode\u003eX-Request-Id\u003c/code\u003e (UUID заявки + номер попытки) и просим партнёра считать дубликаты по нему; если партнёр это не поддерживает — на таймаут не ретраим синхронно, а уходим в асинхронный сценарий.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e3. Поведение при отказе\u003c/h3\u003e\u003cp\u003eПосле исчерпания попыток заявка не блокируется: создаётся с признаком \u003cstrong\u003e«проверка не пройдена / требует ручной проверки»\u003c/strong\u003e (статус \u003ccode\u003eNEED_REVIEW\u003c/code\u003e), задача уходит в очередь на повторную проверку через 5 минут, пользователь видит «заявка принята, проверка контрагента выполняется, вернёмся в течение N минут». Вердикт приходит уведомлением и обновляет статус.\u003c/p\u003e\u003ch3\u003e4. Защита от лавины\u003c/h3\u003e\u003cul\u003e\u003cli\u003eОтдельный пул соединений на внешний сервис (bulkhead): 10 соединений, остальной трафик не страдает.\u003c/li\u003e\u003cli\u003eCircuit breaker: 50% ошибок за 30 секунд при минимум 20 запросах → open на 30 секунд, дальше half-open с 3 пробными запросами.\u003c/li\u003e\u003cli\u003eПри открытом breaker сразу идём в \u003ccode\u003eNEED_REVIEW\u003c/code\u003e, не тратя бюджет пользователя.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e5. Метрики и логи\u003c/h3\u003e\u003cul\u003e\u003cli\u003eМетрики: количество вызовов, доля 2xx/4xx/5xx, p50/p95/p99 времени, число ретраев, срабатывания breaker, размер очереди повторных проверок, доля заявок в \u003ccode\u003eNEED_REVIEW\u003c/code\u003e.\u003c/li\u003e\u003cli\u003eЛоги: каждый вызов с \u003ccode\u003eX-Request-Id\u003c/code\u003e, ИНН (маскирован), код ответа, длительность, номер попытки. Корреляционный ID заявки пробрасывается во все записи.\u003c/li\u003e\u003cli\u003eАлерты: доля ошибок \u003e 5% за 5 минут; p95 \u003e 2 сек за 10 минут; доля \u003ccode\u003eNEED_REVIEW\u003c/code\u003e \u003e 10% за час.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e6. Расчёт нагрузки\u003c/h3\u003e\u003cp\u003e40 rps × до 3 попыток = до 120 rps на внешний сервис в худшем случае. Согласуем с партнёром лимит и ставим client-side rate limit 60 rps: всё, что выше, сразу уходит в \u003ccode\u003eNEED_REVIEW\u003c/code\u003e, а не добивает чужой сервис.\u003c/p\u003e","mermaid":"flowchart TD\n  A[Пользователь создаёт заявку] --\u003e B[POST /counterparty/check\u003cbr/\u003eX-Request-Id]\n  B --\u003e C{Ответ}\n  C --\u003e|2xx| D[Вердикт принят\u003cbr/\u003eзаявка ACTIVE]\n  C --\u003e|4xx бизнес-ошибка| E[Не ретраим\u003cbr/\u003eзаявка REJECTED / ошибка валидации]\n  C --\u003e|429| F[Пауза по Retry-After\u003cbr/\u003e1 попытка]\n  C --\u003e|5xx / таймаут| G{Попыток осталось?}\n  G --\u003e|да| H[Backoff 300/900 мс + джиттер]\n  H --\u003e B\n  G --\u003e|нет| I[Circuit breaker учитывает ошибку]\n  I --\u003e J[Заявка NEED_REVIEW\u003cbr/\u003eпользователь: принята, проверим асинхронно]\n  J --\u003e K[Очередь: повтор через 5 мин]\n  K --\u003e B\n  K --\u003e L[Уведомление о вердикте]\n  F --\u003e B\n  D --\u003e M[Метрики: p95, доля ошибок, ретраи]\n  J --\u003e M\n"}'::jsonb, updated_at = now() WHERE id = 'int-timeouts';
UPDATE tasks SET statement = '{"brief":"Спроектировать операцию списания денег так, чтобы повторная отправка запроса не списала деньги дважды.","context":["Мобильное приложение отправляет в платёжный сервис запрос \u003ccode\u003ePOST /v1/payments\u003c/code\u003e — списание с карты клиента в пользу магазина. Сеть мобильная: запросы теряются, приложение повторяет отправку, пользователь может нажать кнопку дважды.","Со стороны платёжного сервиса есть банк-эквайер, который тоже отвечает с задержкой и иногда «зависает»: деньги уже списаны, а ответа мы не получили.","Инциденты двойных списаний — это деньги клиентов, жалобы, чарджбэки и штрафы регулятора. Задача: сделать операцию идемпотентной на всех участках цепочки."],"goal":"Описать контракт и поведение операции списания, при котором любой повтор запроса безопасен, а состояние платежа всегда объяснимо.","inputs":["Сумма, валюта, идентификатор карты (токен), идентификатор заказа, идентификатор клиента.","Клиентское мобильное приложение, сервер платёжного сервиса, внешний эквайринг.","Текущий контракт: \u003ccode\u003ePOST /v1/payments\u003c/code\u003e без каких-либо ключей идемпотентности.","Требование бизнеса: пользователь всегда видит однозначный результат — «оплачено», «не оплачено» или «платёж обрабатывается»."],"deliverables":["Контракт запроса и ответа: поля, коды HTTP, ключ идемпотентности, кто его генерирует и как долго он живёт.","Модель состояний платежа и переходы между ними.","Поведение при дублях запроса: что возвращаем, если платёж уже создан, уже успешен, уже отклонён или ещё в работе.","Обработка «зависшего» эквайринга: как узнаём истинный результат и что показываем пользователю.","Граничные случаи: сумма изменилась при том же ключе, ключ переиспользован для другого заказа, истёк срок хранения ключа.","Что нужно для эксплуатации: логи, метрики, поддержка разборов «клиент говорит, что списали дважды»."],"constraints":["Эквайринг менять нельзя, он не идемпотентен по своим внутренним причинам.","Срок жизни ключа идемпотентности ограничен: хранить вечно нельзя.","Ответ клиенту — в пределах 3 секунд, дальше только асинхронные уведомления."],"interview":"«Расскажите, как вы спроектируете идемпотентный платёжный запрос. Что будет, если клиент отправит его дважды, а эквайринг на первый запрос не ответил?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Контракт и поведение","content":"\u003ch3\u003eКонтракт POST /v1/payments\u003c/h3\u003e\u003cp\u003eКлюч идемпотентности: кто генерирует, где передаётся, сколько живёт.\u003c/p\u003e\u003ch3\u003eКоды ответов\u003c/h3\u003e\u003ch3\u003eГраничные случаи\u003c/h3\u003e"},{"type":"plantuml","title":"Sequence: списание","content":"@startuml\nautonumber\nactor \"Клиент\" as C\nparticipant \"Мобильное приложение\" as App\nparticipant \"Платёжный API\" as API\ndatabase \"БД платежей\" as DB\nparticipant \"Эквайринг\" as ACQ\n\nC -\u003e App: Нажал \"Оплатить\"\nApp -\u003e API: POST /v1/payments\\nIdempotency-Key: ?\nAPI -\u003e DB: проверить ключ\nDB --\u003e API: ?\nAPI -\u003e ACQ: списание\nACQ --\u003e API: ?\nAPI --\u003e App: ?\nApp --\u003e C: ?\n@enduml\n"},{"type":"mermaid","title":"Состояния платежа","content":"stateDiagram-v2\n  [*] --\u003e CREATED\n  CREATED --\u003e PROCESSING\n  PROCESSING --\u003e SUCCEEDED\n  PROCESSING --\u003e FAILED\n  PROCESSING --\u003e UNKNOWN\n  UNKNOWN --\u003e SUCCEEDED\n  UNKNOWN --\u003e FAILED\n  SUCCEEDED --\u003e REFUNDED\n  FAILED --\u003e [*]\n"}]'::jsonb, rubric = '[{"id":"key-ownership","title":"Ключ идемпотентности: генерируется клиентом, передаётся в заголовке, уникален на одну бизнес-операцию","weight":"high","weightValue":null,"focus":"arch","keywords":["idempotency-key","ключ идемпотентности","заголов","uuid","генерирует клиент","x-request-id"],"why":"Если ключ генерирует сервер, он не защитит от повторной отправки одного и того же запроса. Это фундамент всей схемы.","critical":false},{"id":"key-storage","title":"Сервер хранит ключ вместе с результатом: повтор по тому же ключу возвращает сохранённый ответ, а не создаёт новый платёж","weight":"high","weightValue":null,"focus":"arch","keywords":["хран","таблиц","сохран","кэш","redis","unique","уникальн","повтор","тот же ответ","200","срок жизни","ttl"],"why":"Идемпотентность — это не «проверить дубль», а «вернуть тот же результат». Без хранения результата схема не работает.","critical":false},{"id":"concurrency","title":"Параллельные дубли: уникальное ограничение / блокировка, состояние IN_PROGRESS, защита от гонки","weight":"high","weightValue":null,"focus":"arch","keywords":["unique","уникальн","блокиров","гонк","параллель","одновремен","in_progress","409","mutex","транзакц"],"why":"Два одинаковых запроса приходят почти одновременно: без unique-индекса или блокировки оба пройдут проверку «ключа нет» и создадут два платежа.","critical":false},{"id":"states","title":"Модель состояний платежа с явным состоянием неопределённости (UNKNOWN / PENDING)","weight":"high","weightValue":null,"focus":"sa","keywords":["состояни","статус","pending","unknown","processing","переход","state machine","неопредел"],"why":"Деньги списаны, ответа нет — это отдельное состояние. Если его нет в модели, поддержка и бухгалтерия получат неразобранное расхождение.","critical":false},{"id":"acq-reconciliation","title":"Разбор «зависшего» эквайринга: опрос статуса, reconcilliation, компенсация (возврат)","weight":"high","weightValue":null,"focus":"sa","keywords":["опрос","polling","сверк","reconcil","статус у эквайер","webhook","компенсац","возврат","refund","отмен","тайм-аут на эквай","расхожден"],"why":"Идемпотентность на нашей стороне не отменяет неопределённости у эквайера. Нужен процесс выяснения истины и компенсации, если деньги ушли, а заказ закрыт.","critical":false},{"id":"edge-cases","title":"Граничные случаи: тот же ключ с другой суммой, ключ на другой заказ, истечение TTL ключа, повтор после FAILED","weight":"high","weightValue":null,"focus":"sa","keywords":["другой сумм","изменил","422","несоответ","истеч","ttl","другой заказ","409","conflict","повтор после","граничн"],"why":"Именно эти кейсы ломают реализацию. Аналитик, который их не описал, передаст разработчику мину замедленного действия.","critical":false},{"id":"http-semantics","title":"Корректная HTTP-семантика: 201 при создании, 200 при повторе, 409/422 при конфликте ключа, 5xx отдельно","weight":"mid","weightValue":null,"focus":"arch","keywords":["201","200","409","422","500","503","location","http-код","код ответ"],"why":"Клиент должен различать «создали сейчас» и «это повтор прошлого запроса» без разбора тела ответа.","critical":false},{"id":"ux-state","title":"Что видит пользователь в каждом состоянии, включая «платёж обрабатывается»","weight":"mid","weightValue":null,"focus":"sa","keywords":["пользовател","экран","уведомлен","push","спиннер","интерфей","клиент видит","сообщен"],"why":"Требование бизнеса — однозначный результат. Без описания UX для PENDING задача решена наполовину.","critical":false},{"id":"ops-support","title":"Эксплуатация: логи с ключом, метрики дублей, инструмент разбора для поддержки","weight":"mid","weightValue":null,"focus":"sa","keywords":["лог","метрик","поддержк","разбор","аудит","tracing","дашборд","dashboard","журнал"],"why":"Инциденты «списали дважды» разбирает поддержка. Если ключ не попадает в логи и нет экрана разбора, каждый инцидент — это запрос к разработчикам.","critical":false}]'::jsonb, hints = '["Разделите два разных случая: клиент повторил запрос (мы можем защититься ключом) и эквайринг не ответил (мы не знаем результат). Это разные механизмы.","Подумайте про уникальность на уровне БД, а не только про проверку в коде: две параллельные нити обе увидят «ключа нет».","Что должно произойти, если клиент прислал тот же ключ, но сумму на рубль больше? Это ошибка клиента или наша проблема?"]'::jsonb, interview_questions = '["Где вы храните ключ идемпотентности и каков его TTL? Почему не вечно?","Два одинаковых запроса пришли одновременно — что спасёт от двойного списания?","Клиент прислал тот же Idempotency-Key, но другую сумму. Ваш ответ?","Эквайринг не ответил, прошло 30 секунд. Что показывает пользователь и что делает система?","Как поддержка за 5 минут разберёт жалобу «списали два раза»?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Контракт\u003c/h3\u003e\u003cp\u003e\u003ccode\u003ePOST /v1/payments\u003c/code\u003e с обязательным заголовком \u003ccode\u003eIdempotency-Key\u003c/code\u003e (UUID v4). Ключ генерирует \u003cstrong\u003eмобильное приложение в момент формирования платёжного намерения\u003c/strong\u003e (когда пользователь открыл экран подтверждения), а не в момент отправки. Одна попытка оплаты = один ключ; нажатие «Повторить» после ошибки создаёт новый ключ только если предыдущий платёж завершился отказом.\u003c/p\u003e\u003cp\u003eТело: \u003ccode\u003e{ \"orderId\", \"amount\", \"currency\", \"cardToken\", \"customerId\", \"description\" }\u003c/code\u003e. Ответ \u003ccode\u003e201\u003c/code\u003e + \u003ccode\u003eLocation: /v1/payments/{id}\u003c/code\u003e и тело \u003ccode\u003e{ \"paymentId\", \"status\", \"amount\", \"createdAt\" }\u003c/code\u003e.\u003c/p\u003e\u003ch3\u003e2. Хранение ключа\u003c/h3\u003e\u003cp\u003eТаблица \u003ccode\u003eidempotency_keys\u003c/code\u003e: \u003ccode\u003ekey\u003c/code\u003e (unique index), \u003ccode\u003ecustomer_id\u003c/code\u003e, \u003ccode\u003erequest_fingerprint\u003c/code\u003e (хэш тела запроса), \u003ccode\u003epayment_id\u003c/code\u003e, \u003ccode\u003estate\u003c/code\u003e (IN_PROGRESS / COMPLETED), \u003ccode\u003eresponse_snapshot\u003c/code\u003e (JSON), \u003ccode\u003eexpires_at\u003c/code\u003e. TTL — 24 часа: достаточно для ретраев клиента и разборов, не раздувает таблицу. После истечения ключ может быть переиспользован — это безопасно, потому что платёж к тому моменту либо завершён, либо отменён.\u003c/p\u003e\u003ch3\u003e3. Повторный запрос по тому же ключу\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eCOMPLETED\u003c/strong\u003e → \u003ccode\u003e200\u003c/code\u003e и сохранённый \u003ccode\u003eresponse_snapshot\u003c/code\u003e. Новый платёж не создаём, эквайринг не дёргаем.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eIN_PROGRESS\u003c/strong\u003e → \u003ccode\u003e409 Conflict\u003c/code\u003e с телом \u003ccode\u003e{ \"error\": \"payment_in_progress\", \"paymentId\", \"retryAfterMs\": 3000 }\u003c/code\u003e. Клиент показывает «платёж обрабатывается» и опрашивает статус.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eКлюч не найден\u003c/strong\u003e → создаём запись с unique-индексом; при конфликте вставки (гонка) уходим в ветку IN_PROGRESS.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eТот же ключ, другой fingerprint тела\u003c/strong\u003e → \u003ccode\u003e422 Unprocessable Entity\u003c/code\u003e, \u003ccode\u003eerror: idempotency_key_reused\u003c/code\u003e. Это ошибка клиента: переиспользовать ключ для другой операции нельзя.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e4. Модель состояний\u003c/h3\u003e\u003cp\u003e\u003ccode\u003eCREATED → PROCESSING → SUCCEEDED | FAILED\u003c/code\u003e, плюс \u003ccode\u003eUNKNOWN\u003c/code\u003e (эквайринг не ответил) и терминальные \u003ccode\u003eREFUNDED\u003c/code\u003e, \u003ccode\u003eCANCELLED\u003c/code\u003e. Переход в \u003ccode\u003eUNKNOWN\u003c/code\u003e — по таймауту 10 секунд на вызов эквайера. Выход из \u003ccode\u003eUNKNOWN\u003c/code\u003e: опрос \u003ccode\u003eGET /status\u003c/code\u003e у эквайера по нашему \u003ccode\u003epaymentId\u003c/code\u003e с экспоненциальной паузой (10 сек, 30 сек, 1, 5, 15 мин) и суточная сверка (reconciliation) по выгрузке эквайера.\u003c/p\u003e\u003ch3\u003e5. Зависший эквайринг\u003c/h3\u003e\u003cul\u003e\u003cli\u003eПользователю: «Платёж обрабатывается, мы сообщим результат» — экран с статусом, push/SMS при финале. Кнопка «Оплатить снова» заблокирована до разрешения состояния.\u003c/li\u003e\u003cli\u003eСистеме: задача в очереди разбора. Если выяснилось, что списание прошло → \u003ccode\u003eSUCCEEDED\u003c/code\u003e, закрываем заказ. Если прошло, а заказ уже отменён или сумма не совпала → автоматический \u003ccode\u003eREFUND\u003c/code\u003e и запись в журнал расхождений.\u003c/li\u003e\u003cli\u003eЕсли списания не было → \u003ccode\u003eFAILED\u003c/code\u003e, пользователь может повторить с новым ключом.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e6. Граничные случаи\u003c/h3\u003e\u003cul\u003e\u003cli\u003eТот же ключ + другая сумма → 422, платёж не создаём.\u003c/li\u003e\u003cli\u003eКлюч от другого \u003ccode\u003eorderId\u003c/code\u003e → 422 (проверяем принадлежность ключа клиенту и заказу).\u003c/li\u003e\u003cli\u003eПовтор после \u003ccode\u003eFAILED\u003c/code\u003e → разрешён только с новым ключом; старый ключ возвращает сохранённый FAILED, чтобы клиент не зациклился.\u003c/li\u003e\u003cli\u003eРетрай клиента после 500 с нашей стороны → ключ тот же, возвращаем сохранённый результат, двойного списания нет.\u003c/li\u003e\u003cli\u003eИстёк TTL → новый запрос с тем же ключом создаст новый платёж; поэтому клиент обязан получать финальный статус до истечения TTL (опрос + уведомления).\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e7. Эксплуатация\u003c/h3\u003e\u003cul\u003e\u003cli\u003eЛоги: каждый запрос с \u003ccode\u003eIdempotency-Key\u003c/code\u003e, \u003ccode\u003epaymentId\u003c/code\u003e, \u003ccode\u003eorderId\u003c/code\u003e, код ответа эквайера, длительность. Ключ не маскируем — он не секрет.\u003c/li\u003e\u003cli\u003eМетрики: доля повторных запросов по ключу, доля 409, доля 422 (переиспользование), число и возраст платежей в \u003ccode\u003eUNKNOWN\u003c/code\u003e, число авто-возвратов после сверки.\u003c/li\u003e\u003cli\u003eАлерты: \u003ccode\u003eUNKNOWN\u003c/code\u003e старше 30 минут \u003e 5 шт.; рост доли 422 выше 1% (клиент сломал генерацию ключей).\u003c/li\u003e\u003cli\u003eДля поддержки: экран разбора по \u003ccode\u003eorderId\u003c/code\u003e / ключу / карте — видно все попытки, состояние каждой и историю взаимодействий с эквайером.\u003c/li\u003e\u003c/ul\u003e","plantuml":"@startuml\nautonumber\nskinparam responseMessageBelowArrow true\nactor \"Клиент\" as C\nparticipant \"Мобильное приложение\" as App\nparticipant \"Платёжный API\" as API\ndatabase \"idempotency_keys\" as KEY\ndatabase \"payments\" as DB\nparticipant \"Эквайринг\" as ACQ\nqueue \"Очередь разбора\" as Q\n\nC -\u003e App: Открыл экран оплаты\nnote right of App: генерируем Idempotency-Key (UUID)\nC -\u003e App: Нажал \"Оплатить\"\nApp -\u003e API: POST /v1/payments\\nIdempotency-Key: K1\nAPI -\u003e KEY: INSERT (K1, IN_PROGRESS, fingerprint)\nalt ключ уже есть\n  KEY --\u003e API: unique violation\n  API -\u003e KEY: прочитать state\n  alt state = COMPLETED\n    API --\u003e App: 200 + сохранённый ответ\n    App --\u003e C: \"Оплачено\"\n  else state = IN_PROGRESS\n    API --\u003e App: 409 payment_in_progress\n    App --\u003e C: \"Платёж обрабатывается\"\n  else fingerprint не совпал\n    API --\u003e App: 422 idempotency_key_reused\n    App --\u003e C: \"Обновите приложение / ошибка\"\n  end\nelse ключ новый\n  KEY --\u003e API: ok\n  API -\u003e DB: INSERT payment (PROCESSING)\n  API -\u003e ACQ: списание (paymentId)\n  alt эквайринг ответил\n    ACQ --\u003e API: success / decline\n    API -\u003e DB: SUCCEEDED / FAILED\n    API -\u003e KEY: COMPLETED + response_snapshot\n    API --\u003e App: 201 + статус\n    App --\u003e C: \"Оплачено\" / \"Отклонено\"\n  else таймаут 10 сек\n    API -\u003e DB: UNKNOWN\n    API -\u003e Q: задача разбора (опрос статуса + сверка)\n    API --\u003e App: 202 payment_pending\n    App --\u003e C: \"Обрабатывается, сообщим результат\"\n    Q -\u003e ACQ: GET status (ретраи 10с/30с/1м/5м/15м)\n    ACQ --\u003e Q: итог\n    Q -\u003e DB: SUCCEEDED / FAILED / REFUND\n    Q -\u003e App: push-уведомление\n  end\nend\n@enduml\n","mermaid":"stateDiagram-v2\n  [*] --\u003e CREATED: POST /v1/payments\\n(ключ новый)\n  CREATED --\u003e PROCESSING: отправляем в эквайринг\n  PROCESSING --\u003e SUCCEEDED: эквайринг: success\n  PROCESSING --\u003e FAILED: эквайринг: decline\n  PROCESSING --\u003e UNKNOWN: таймаут / нет ответа\n  UNKNOWN --\u003e SUCCEEDED: опрос статуса / сверка\n  UNKNOWN --\u003e FAILED: опрос статуса / сверка\n  UNKNOWN --\u003e REFUNDED: списание есть, заказ отменён\n  SUCCEEDED --\u003e REFUNDED: возврат\n  FAILED --\u003e [*]\n  REFUNDED --\u003e [*]\n  SUCCEEDED --\u003e [*]\n"}'::jsonb, updated_at = now() WHERE id = 'int-idempotency';
UPDATE tasks SET statement = '{"brief":"Старая интеграция на SOAP/WSDL живёт 9 лет. Нужен план перехода на REST с работающим продакшеном всё это время.","context":["Наша система обменивается заявками с системой партнёра через SOAP 1.1: один WSDL, 14 операций, XML с вложенными структурами, пространства имён, обязательная подпись части сообщений. Обмен двусторонний: мы отправляем заявки и статусы, партнёр присылает подтверждения и результаты рассмотрения.","Партнёр разработал новый REST API (JSON, OpenAPI 3) и объявил, что SOAP будет отключён через 6 месяцев. Нагрузка — около 300 тысяч сообщений в сутки, пик в первые два часа рабочего дня.","Остановить обмен нельзя ни на день: это заявки клиентов. Часть операций SOAP не имеет прямого аналога в REST — партнёр «упростил» контракт, и двух полей просто нет."],"goal":"Составить план миграции: маппинг операций, управление расхождениями контрактов, этапы переключения, проверка корректности и план отката.","inputs":["WSDL текущего SOAP-интерфейса (14 операций) и OpenAPI-спецификация нового REST-интерфейса (11 ресурсов).","Статистика использования: 3 операции дают 92% трафика, 5 операций вызываются реже раза в месяц, 2 операции не используются вовсе.","Расхождение: в REST нет полей «основание документа» и «код подразделения-инициатора», которые использует наш учёт.","В REST партнёр перешёл с синхронного ответа на асинхронный: на создание заявки возвращается 202 и идентификатор, результат приходит webhook-ом."],"deliverables":["Таблица маппинга операций SOAP → REST с типом расхождения (1:1, с потерей полей, нет аналога, изменилась семантика).","Решение по каждому расхождению: как компенсируем, кто согласовывает, что делаем с данными, которых в REST нет.","Этапы миграции с критериями готовности каждого этапа и точкой невозврата.","Механизм параллельной работы и сверки: как доказать, что новый канал даёт тот же результат.","План отката и условия его запуска.","Риски и как их закрываем (в том числе риск «SOAP отключат раньше, чем мы готовы»)."],"constraints":["Партнёр не будет поддерживать оба канала дольше 6 месяцев и не вернёт удалённые поля.","Наша внутренняя учётная система требует «основание документа»: убрать поле нельзя.","Команда разработки — 4 человека, одновременно идёт продуктовая разработка."],"interview":"«Нам через полгода отключают SOAP, надо перейти на REST. Расскажите ваш план. Что вы будете делать с полями, которых в новом контракте нет?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"План миграции","content":"\u003ch3\u003e1. Маппинг операций\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eSOAP\u003c/th\u003e\u003cth\u003eREST\u003c/th\u003e\u003cth\u003eРасхождение\u003c/th\u003e\u003cth\u003eРешение\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003c/td\u003e\u003ctd\u003e\u003c/td\u003e\u003ctd\u003e\u003c/td\u003e\u003ctd\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003ch3\u003e2. Этапы\u003c/h3\u003e\u003ch3\u003e3. Сверка и откат\u003c/h3\u003e"},{"type":"mermaid","title":"Этапы переключения","content":"flowchart LR\n  A[Аудит и маппинг] --\u003e B[Адаптер]\n  B --\u003e C[Параллельный прогон]\n  C --\u003e D[Переключение трафика]\n  D --\u003e E[Отключение SOAP]\n"}]'::jsonb, rubric = '[{"id":"mapping-table","title":"Полный маппинг операций с классификацией расхождений, а не «перепишем на REST»","weight":"high","weightValue":null,"focus":"sa","keywords":["маппинг","mapping","таблиц","соответств","1:1","расхожден","операци","wSDL","эндпоинт"],"why":"Без построчного маппинга потеря полей обнаруживается в проде. Это главный артефакт аналитика в такой миграции.","critical":false},{"id":"lost-fields","title":"Решение по пропавшим полям: где храним, как передаём, согласование с партнёром и внутренней учёткой","weight":"high","weightValue":null,"focus":"sa","keywords":["основан","подразделен","пропал","нет в rest","расширен","extension","метаданные","на стороне","хранить у себя","согласов","обогат"],"why":"Задача прямо говорит, что поля нужны учёту, а в REST их нет. Игнорирование этого пункта ломает бухгалтерию.","critical":false},{"id":"sync-to-async","title":"Обработка смены семантики: синхронный ответ → 202 + webhook (состояния, повторные уведомления, потеря webhook)","weight":"high","weightValue":null,"focus":"arch","keywords":["202","webhook","асинхрон","polling","опрос","callback","ожидан","pending","идемпотент","повтор уведомлен"],"why":"Смена модели взаимодействия — самое дорогое место миграции. Нужны состояние ожидания, защита от потери и дублей уведомлений.","critical":false},{"id":"adapter","title":"Антикоррупционный слой / адаптер: внутренняя модель не зависит от транспорта","weight":"high","weightValue":null,"focus":"arch","keywords":["адаптер","adapter","антикоррупц","acl","шлюз","gateway","внутренняя модель","прослойк","фасад","абстракц"],"why":"Если переписать вызовы «в лоб», следующая смена контракта партнёра снова будет стоить полгода. Адаптер даёт обратимость.","critical":false},{"id":"parallel-run","title":"Параллельный прогон и сверка результатов (shadow traffic, сравнение ответов, метрики расхождений)","weight":"high","weightValue":null,"focus":"sa","keywords":["параллель","shadow","сверк","двойн","сравнен","расхожден","canary","процент трафик","reconcil","контроль"],"why":"«Переехали и работает» — не доказательство. Только сверка на реальном трафике показывает потерю данных и расхождение статусов.","critical":false},{"id":"staged-rollout","title":"Поэтапное переключение по операциям/трафику с критериями готовности и точкой невозврата","weight":"mid","weightValue":null,"focus":"sa","keywords":["этап","поэтап","5%","10%","canary","критер","готовност","точка невозврата","приоритет","трафик"],"why":"Перевод всех 14 операций разом — гарантированный инцидент. Этапы с измеримыми критериями снижают риск.","critical":false},{"id":"rollback","title":"План отката: условия, время, сохранение данных в обеих моделях","weight":"mid","weightValue":null,"focus":"arch","keywords":["откат","rollback","вернуть","feature flag","переключат","деградац","обратно на soap"],"why":"Миграция без отката — это ставка на удачу. Флаги и двусторонняя запись данных дают возможность вернуться за минуты.","critical":false},{"id":"unused-ops","title":"Работа с «мёртвыми» операциями: не мигрируем то, чем не пользуются (экономия ресурса команды)","weight":"mid","weightValue":null,"focus":"sa","keywords":["не использ","мёртв","депрек","отказ","не мигрируем","архив","статистик","приоритизац","92%"],"why":"4 разработчика и 6 месяцев: приоритизация по реальному трафику — то, что отличает опытного аналитика.","critical":false},{"id":"org-risks","title":"Организационные риски и коммуникация: регламент с партнёром, тестовый стенд, SLA на исправление, ответственные","weight":"mid","weightValue":null,"focus":"sa","keywords":["партнёр","согласов","стенд","регламент","ответств","коммуникац","встреч","sLA","план-график","контакт"],"why":"Миграция упирается не в код, а в доступность стенда партнёра и скорость его ответов. Это надо планировать явно.","critical":false}]'::jsonb, hints = '["Начните со статистики: 3 операции = 92% трафика. Что это меняет в порядке работ?","Асинхронная модель означает, что у заявки появляется состояние ожидания. Кто и как узнает результат, если webhook не пришёл?","Откат возможен, только пока данные пишутся в обе модели или есть обратимый адаптер. Подумайте, когда наступает точка невозврата."]'::jsonb, interview_questions = '["Как вы докажете, что REST-канал даёт тот же результат, что и SOAP?","Поле «основание документа» в REST отсутствует. Ваши действия?","Webhook не пришёл. Что произойдёт с заявкой?","Партнёр переносит дату отключения SOAP на месяц раньше. Что делаете?","Какие операции вы не станете мигрировать и почему?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Инвентаризация и маппинг\u003c/h3\u003e\u003cp\u003eСнимаем фактический трафик за 3 месяца (не документацию, а логи) и строим таблицу: SOAP-операция → REST-ресурс и метод → тип расхождения → владелец решения. Классификация расхождений: \u003cstrong\u003eA\u003c/strong\u003e — 1:1 (прямой перенос), \u003cstrong\u003eB\u003c/strong\u003e — потеря полей, \u003cstrong\u003eC\u003c/strong\u003e — смена семантики (sync → async), \u003cstrong\u003eD\u003c/strong\u003e — аналога нет, \u003cstrong\u003eE\u003c/strong\u003e — операция не используется.\u003c/p\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eSOAP\u003c/th\u003e\u003cth\u003eREST\u003c/th\u003e\u003cth\u003eТрафик\u003c/th\u003e\u003cth\u003eТип\u003c/th\u003e\u003cth\u003eРешение\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eCreateApplication\u003c/td\u003e\u003ctd\u003ePOST /applications (202)\u003c/td\u003e\u003ctd\u003e71%\u003c/td\u003e\u003ctd\u003eB + C\u003c/td\u003e\u003ctd\u003eЭтап 1, адаптер + polling/webhook\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eGetApplicationStatus\u003c/td\u003e\u003ctd\u003eGET /applications/{id}\u003c/td\u003e\u003ctd\u003e14%\u003c/td\u003e\u003ctd\u003eA\u003c/td\u003e\u003ctd\u003eЭтап 1\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eSendDecision\u003c/td\u003e\u003ctd\u003ePOST /applications/{id}/decisions\u003c/td\u003e\u003ctd\u003e7%\u003c/td\u003e\u003ctd\u003eB\u003c/td\u003e\u003ctd\u003eЭтап 1, поле в extension\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eCancelApplication\u003c/td\u003e\u003ctd\u003eDELETE /applications/{id}\u003c/td\u003e\u003ctd\u003e0,4%\u003c/td\u003e\u003ctd\u003eC\u003c/td\u003e\u003ctd\u003eЭтап 2\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eGetDictBranches\u003c/td\u003e\u003ctd\u003e—\u003c/td\u003e\u003ctd\u003e0\u003c/td\u003e\u003ctd\u003eD\u003c/td\u003e\u003ctd\u003eНе мигрируем: справочник ведём у себя, источник — выгрузка раз в сутки\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003ePing / 5 редких операций\u003c/td\u003e\u003ctd\u003e—\u003c/td\u003e\u003ctd\u003e\u0026lt;0,1%\u003c/td\u003e\u003ctd\u003eE\u003c/td\u003e\u003ctd\u003eВыводим из эксплуатации, уведомляем партнёра письменно\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003ch3\u003e2. Пропавшие поля\u003c/h3\u003e\u003cp\u003e«Основание документа» и «код подразделения-инициатора» остаются в нашей модели как обязательные. Варианты, выбираем гибридный:\u003c/p\u003e\u003cul\u003e\u003cli\u003eЕсли в REST есть расширяемое поле (\u003ccode\u003emetadata\u003c/code\u003e, \u003ccode\u003eattributes\u003c/code\u003e) — кладём туда по согласованию с партнёром, фиксируем в приложении к регламенту обмена.\u003c/li\u003e\u003cli\u003eЕсли нет — храним у себя: связка \u003ccode\u003eourApplicationId ↔ partnerApplicationId\u003c/code\u003e в таблице миграции, поля живут в нашей БД и подставляются в учёт при получении результата.\u003c/li\u003e\u003cli\u003eОбязательное условие: в REST-ответе партнёра есть \u003cstrong\u003eнаш\u003c/strong\u003e идентификатор (\u003ccode\u003eexternalId\u003c/code\u003e), иначе сопоставление невозможно. Проверяем это до начала работ — это блокер.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e3. Архитектура: антикоррупционный слой\u003c/h3\u003e\u003cp\u003eВнутренняя модель заявки и внутренний порт \u003ccode\u003eApplicationGateway\u003c/code\u003e не знают о транспорте. Реализации: \u003ccode\u003eSoapApplicationGateway\u003c/code\u003e и \u003ccode\u003eRestApplicationGateway\u003c/code\u003e. Выбор реализации — feature flag на уровне операции и процента трафика. Это даёт: обратимость, возможность параллельного прогона, изоляцию внутренних доработок от смены контракта.\u003c/p\u003e\u003ch3\u003e4. Асинхронная семантика\u003c/h3\u003e\u003cul\u003e\u003cli\u003eПосле \u003ccode\u003e202\u003c/code\u003e заявка в состоянии \u003ccode\u003eSUBMITTED_PENDING_ACK\u003c/code\u003e.\u003c/li\u003e\u003cli\u003eWebhook принимаем идемпотентно (по \u003ccode\u003epartnerApplicationId\u003c/code\u003e + \u003ccode\u003eeventVersion\u003c/code\u003e), подписываем и валидируем источник, отвечаем 200 быстро, обработку — в очередь.\u003c/li\u003e\u003cli\u003eСтраховка от потери webhook: опрос статуса с паузами 1 мин / 5 мин / 30 мин / 2 часа, алерт на заявки в \u003ccode\u003ePENDING\u003c/code\u003e старше 4 часов.\u003c/li\u003e\u003cli\u003eПовторные уведомления партнёра не создают дубли решений: у решения есть \u003ccode\u003edecisionId\u003c/code\u003e, повтор игнорируется с записью в журнал.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e5. Этапы и критерии готовности\u003c/h3\u003e\u003col\u003e\u003cli\u003e\u003cstrong\u003eЭтап 0 (3 недели):\u003c/strong\u003e аудит трафика, маппинг, подтверждение \u003ccode\u003eexternalId\u003c/code\u003e у партнёра, доступ к тестовому стенду, регламент взаимодействия и SLA на исправление дефектов партнёра. Критерий: подписанный маппинг, стенд доступен.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЭтап 1 (6 недель):\u003c/strong\u003e адаптер + 3 операции на 92% трафика. Parallel run в тестовом контуре, затем shadow-режим в проде (отправляем в оба канала, учитываем только SOAP). Критерий: 100 000 сообщений без расхождений; расхождения по статусам = 0; p95 REST не хуже SOAP.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЭтап 2 (4 недели):\u003c/strong\u003e переключение 5% → 25% → 50% → 100% трафика по флагам, каждый шаг не менее 3 рабочих дней. Критерий: нет роста инцидентов и расхождений сверки. \u003cstrong\u003eТочка невозврата:\u003c/strong\u003e после 100% в течение 10 рабочих дней — прекращаем запись в SOAP-модель.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЭтап 3 (3 недели):\u003c/strong\u003e редкие операции, вывод SOAP-кода, архивация, нагрузочное тестирование нового канала, обновление документации и инструкций поддержки.\u003c/li\u003e\u003c/ol\u003e\u003ch3\u003e6. Сверка\u003c/h3\u003e\u003cp\u003eЕжесуточный reconciliation-отчёт: количество заявок по каналам, распределение статусов, время обработки, число расхождений с детализацией до конкретной заявки. Плюс недельная ручная выборка 50 заявок «глазами» — автоматика не ловит смысловые расхождения (например, другой код причины отказа).\u003c/p\u003e\u003ch3\u003e7. Откат\u003c/h3\u003e\u003cul\u003e\u003cli\u003eУсловия: расхождение статусов \u0026gt; 0,5% за сутки; потеря сообщений; инцидент SEV-1 на новом канале; недоступность REST \u0026gt; 30 минут.\u003c/li\u003e\u003cli\u003eМеханика: переключить флаг на SOAP (секунды), пока SOAP-канал жив; до точки невозврата данные пишутся в обе модели.\u003c/li\u003e\u003cli\u003eПосле точки невозврата откат = восстановительная процедура с ручным переносом, поэтому до неё не доходим без 10 чистых дней.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e8. Риски\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eПартнёр отключит SOAP раньше.\u003c/strong\u003e Митигируем: ежемесячный статус-отчёт партнёру, этап 1 закрываем к 3-му месяцу, держим буфер 2 месяца.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eСтенд партнёра нестабилен.\u003c/strong\u003e Митигируем: SLA в регламенте, свой мокирующий стенд по OpenAPI-спецификации.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eПоля не вернут, учёт сломается.\u003c/strong\u003e Митигируем: храним у себя, договорились о \u003ccode\u003eexternalId\u003c/code\u003e до старта.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eРесурс команды (4 человека + продуктовая разработка).\u003c/strong\u003e Митигируем: не мигрируем 7 операций из 14, этапы с независимой ценностью.\u003c/li\u003e\u003c/ul\u003e","mermaid":"flowchart LR\n  subgraph S0[\"Этап 0 · аудит\"]\n    A1[Снять реальный трафик за 3 мес]\n    A2[Маппинг SOAP to REST]\n    A3[Решение по пропавшим полям]\n    A4[Регламент и стенд партнёра]\n    A1 --\u003e A2 --\u003e A3 --\u003e A4\n  end\n  subgraph S1[\"Этап 1 · ядро 92%\"]\n    B1[Антикоррупционный адаптер]\n    B2[Shadow: пишем в оба канала]\n    B3[Сверка 100k сообщений]\n    B1 --\u003e B2 --\u003e B3\n  end\n  subgraph S2[\"Этап 2 · переключение\"]\n    C1[5% трафика]\n    C2[25%]\n    C3[50%]\n    C4[100%]\n    C5[Точка невозврата\\n10 чистых дней]\n    C1 --\u003e C2 --\u003e C3 --\u003e C4 --\u003e C5\n  end\n  subgraph S3[\"Этап 3 · зачистка\"]\n    D1[Редкие операции]\n    D2[Демонтаж SOAP-кода]\n    D3[Документация и обучение поддержки]\n    D1 --\u003e D2 --\u003e D3\n  end\n  S0 --\u003e S1 --\u003e S2 --\u003e S3\n  C4 -.откат по флагу.-\u003e B2\n"}'::jsonb, updated_at = now() WHERE id = 'int-soap-migration';
UPDATE tasks SET statement = '{"brief":"Синхронную цепочку «заказ → оплата → склад → доставка» надо перевести на событийную модель. Нужна схема, гарантии и план разбора сбоев.","context":["Онлайн-ритейлер. Сейчас создание заказа — один большой синхронный вызов: сервис заказов по очереди вызывает оплату, склад (резервирование товара) и доставку (слот и стоимость). Любая из систем отвечает медленно — заказ не создаётся, пользователь видит ошибку, склад при этом может остаться с зарезервированным товаром.","Компания переходит на событийную архитектуру: сервис заказов публикует события в Kafka, остальные системы подписываются. Есть требование бизнеса: пользователь должен видеть статус заказа в реальном времени, а отмена заказа — работать даже если товар уже резервируется.","Исторические данные: 2,5 млн заказов в сутки в пик распродаж. Команда эксплуатации требует, чтобы любой сбой разбирался по логам без участия разработчиков."],"goal":"Спроектировать событийную схему потока заказа: состав событий, гарантии доставки и порядка, обработка отказов и согласованность между сервисами, наблюдаемость.","inputs":["Участники: Сервис заказов, Оплата, Склад, Доставка, Уведомления, Аналитика.","Бизнес-правила: товар резервируется только после успешной оплаты; доставка считается только при наличии резерва; отмена возможна до передачи в доставку.","Требование: не более 0,01% «потерянных» заказов, расхождения между сервисами должны выявляться автоматически.","Технология обмена — Kafka (топики, партиции, consumer groups). Другие брокеры не рассматриваем."],"deliverables":["Перечень событий и топиков: имя, состав полезной нагрузки, кто публикует, кто потребляет.","Схема потока (диаграмма) с основным и альтернативными сценариями: оплата не прошла, товара нет на складе, доставка не смогла рассчитать слот, пользователь отменил заказ.","Механизм согласованности: сага (оркестрация или хореография), компенсирующие действия, кто за что отвечает.","Гарантии: at-least-once / exactly-once, дубли сообщений, порядок событий, идемпотентность потребителей.","Партиционирование и ключи: как обеспечить порядок для одного заказа и параллельность между заказами.","Наблюдаемость и разбор сбоев: correlation id, состояние саги, дедлайн-очереди, метрики, алерты, экран разбора для поддержки.","Что меняется для пользователя: статусы заказа, уведомления, поведение при зависшем сценарии."],"constraints":["Полностью синхронный UX при оформлении сохранить нельзя — но пользователь не должен видеть «подвисший» заказ дольше 10 секунд без объяснения.","Оплата — внешний платёжный провайдер, его поведение не детерминировано.","Команда склада не готова менять свою схему БД в ближайшие полгода."],"interview":"«Спроектируйте событийный поток оформления заказа в Kafka. Как вы обеспечите согласованность, если склад зарезервировал товар, а оплата не прошла? И как вы будете разбирать инциденты?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Проектное решение","content":"\u003ch3\u003eСобытия и топики\u003c/h3\u003e\u003ch3\u003eСага и компенсации\u003c/h3\u003e\u003ch3\u003eГарантии доставки и порядок\u003c/h3\u003e\u003ch3\u003eНаблюдаемость\u003c/h3\u003e"},{"type":"plantuml","title":"Sequence: основной поток","content":"@startuml\nautonumber\nparticipant \"Сервис заказов\" as ORD\nqueue \"Kafka\" as K\nparticipant \"Оплата\" as PAY\nparticipant \"Склад\" as WH\nparticipant \"Доставка\" as DLV\nparticipant \"Уведомления\" as NOTIF\n\nORD -\u003e K: OrderCreated\nK -\u003e PAY: OrderCreated\nPAY -\u003e K: PaymentSucceeded\nK -\u003e WH: PaymentSucceeded\nWH -\u003e K: StockReserved\nK -\u003e DLV: StockReserved\nDLV -\u003e K: DeliveryScheduled\nK -\u003e NOTIF: DeliveryScheduled\nNOTIF -\u003e ORD: ?\n@enduml\n"},{"type":"mermaid","title":"Сага: состояния заказа","content":"flowchart TD\n  A[OrderCreated] --\u003e B{Оплата}\n  B --\u003e|успех| C[Резерв склада]\n  B --\u003e|отказ| Z[Заказ отклонён]\n  C --\u003e|успех| D[Расчёт доставки]\n  C --\u003e|нет товара| Y[Компенсация: возврат денег]\n  D --\u003e|успех| E[Заказ подтверждён]\n  D --\u003e|нет слота| X[Компенсация: снять резерв + возврат]\n"}]'::jsonb, rubric = '[{"id":"event-catalog","title":"Каталог событий: имена в прошедшем времени, полезная нагрузка, владелец, потребители, схема и версионирование","weight":"high","weightValue":null,"focus":"sa","keywords":["ordercreated","paymentsucceeded","stockreserved","топик","topic","состав","payload","схема","schema registry","версионирован","contract"],"why":"Событийная архитектура начинается с контрактов. Без каталога событий каждый сервис придумает свою версию правды.","critical":false},{"id":"saga-type","title":"Явный выбор типа саги (оркестрация vs хореография) с обоснованием и компенсирующими действиями","weight":"high","weightValue":null,"focus":"arch","keywords":["саг","saga","оркестрац","хореограф","компенсац","compensat","откат","возврат денег","снять резерв","координатор"],"why":"Без компенсирующих действий распределённый поток оставляет систему в несогласованном состоянии — деньги списаны, товара нет.","critical":false},{"id":"saga-state","title":"Состояние саги хранится явно: статус каждого шага, дедлайн, история переходов","weight":"high","weightValue":null,"focus":"arch","keywords":["состояние саги","saga state","статус шаг","таблица саг","outbox","журнал","история переходов","дедлайн","timeout саги"],"why":"Если состояние саги нигде не зафиксировано, инцидент разбирается чтением логов вручную, а бизнес не видит, где завис заказ.","critical":false},{"id":"delivery-guarantee","title":"Гарантии доставки: at-least-once + идемпотентный потребитель, обработка дублей, offsets, ретраи","weight":"high","weightValue":null,"focus":"arch","keywords":["at-least-once","exactly-once","идемпотент","дубл","offset","commit","ретра","retry","consumer group","повтор"],"why":"В Kafka по умолчанию at-least-once: дубли будут. Потребитель обязан их гасить, иначе двойные резервы и двойные возвраты.","critical":false},{"id":"outbox","title":"Согласованность «БД + событие»: outbox / transactional publishing, а не публикация после коммита вслепую","weight":"high","weightValue":null,"focus":"arch","keywords":["outbox","transactional","cdc","debezium","локальная транзакц","публикация после коммита","двойная запись"],"why":"Классическая ошибка: запись в БД прошла, публикация в Kafka — нет (или наоборот). Без outbox заказ существует в одном сервисе и не существует в другом.","critical":false},{"id":"partitioning","title":"Партиционирование по orderId: порядок внутри заказа, параллельность между заказами","weight":"high","weightValue":null,"focus":"arch","keywords":["партиц","partition","ключ","orderid","порядок","ordering","hash","перебаланс"],"why":"Без ключа партиционирования события одного заказа разлетятся по партициям и придут в произвольном порядке: «доставка назначена» раньше «оплачено».","critical":false},{"id":"alt-scenarios","title":"Альтернативные сценарии проработаны: отказ оплаты, нет товара, нет слота доставки, отмена пользователем, повторная оплата","weight":"high","weightValue":null,"focus":"sa","keywords":["нет товара","отказ оплат","нет слот","отмен","альтернативн","out of stock","неудач","повтор","частичн"],"why":"Основной сценарий рисуют все. Уровень аналитика виден по тому, что происходит, когда товар закончился на середине саги.","critical":false},{"id":"dlq","title":"Обработка ошибок потребителя: ретраи с backoff, dead-letter queue, повторный ввод сообщений, ручная разборка","weight":"mid","weightValue":null,"focus":"arch","keywords":["dlq","dead letter","мертв","отравлен","poison","backoff","ручной разбор","replay","повторная обработка"],"why":"Одно «битое» сообщение может остановить партицию навсегда. DLQ и replay — обязательная часть эксплуатации.","critical":false},{"id":"observability","title":"Наблюдаемость: сквозной correlation id, трассировка, метрики лагов, алерты, экран состояния заказа для поддержки","weight":"mid","weightValue":null,"focus":"sa","keywords":["correlation","trace","tracing","lag","отставан","метрик","алерт","dash","поддержк","экран разбора","сквозн"],"why":"Требование эксплуатации — разбирать сбой без разработчиков. Без сквозного ID и лагов консьюмеров это невозможно.","critical":false},{"id":"ux-status","title":"Пользовательский опыт: статусы заказа в реальном времени, поведение при зависании, обещания по времени","weight":"mid","weightValue":null,"focus":"sa","keywords":["статус заказ","пользовател","экран","уведомлен","реальн","websocket","polling","10 секунд","ожидан"],"why":"Асинхронность не должна означать, что пользователь не понимает, что с его заказом. Это требование бизнеса из условия.","critical":false},{"id":"reconciliation","title":"Автоматическая сверка между сервисами и выявление расхождений (0,01% потерянных заказов)","weight":"mid","weightValue":null,"focus":"sa","keywords":["сверк","reconcil","расхожден","аудит","контроль","потерян","0,01","ночн","отчёт"],"why":"В распределённой системе расхождения неизбежны. Вопрос не «будут ли», а «как быстро мы о них узнаем».","critical":false}]'::jsonb, hints = '["Нарисуйте не только «счастливый путь». Начните со сценария: оплата прошла, а на складе товара уже нет — кто и как откатывает оплату?","Подумайте, где живёт правда о состоянии заказа. Если её нет ни в одном сервисе — инцидент будет разбираться вручную часами.","Порядок событий: какой ключ партиционирования вы выберете и что будет при перебалансировке консьюмеров?"]'::jsonb, interview_questions = '["Хореография или оркестрация — что выбрали и почему? Чем заплатите за выбор?","Как вы публикуете событие и записываете данные в БД атомарно?","Сообщение обработалось, но offset не закоммитился. Что произойдёт?","Склад зарезервировал товар, оплата не прошла. Опишите шаги компенсации и кто их инициирует.","Как поддержка без разработчика поймёт, где завис заказ №123?","Отмена заказа пришла, когда товар уже передан в доставку. Что делает система?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Каталог событий и топиков\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eТопик\u003c/th\u003e\u003cth\u003eСобытие\u003c/th\u003e\u003cth\u003eКлюч\u003c/th\u003e\u003cth\u003eПродюсер\u003c/th\u003e\u003cth\u003eПотребители\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eorders.events\u003c/code\u003e\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eOrderCreated\u003c/code\u003e, \u003ccode\u003eOrderCancelled\u003c/code\u003e, \u003ccode\u003eOrderCompleted\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eorderId\u003c/td\u003e\u003ctd\u003eЗаказы\u003c/td\u003e\u003ctd\u003eОплата, Склад, Доставка, Уведомления, Аналитика\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003epayments.events\u003c/code\u003e\u003c/td\u003e\u003ctd\u003e\u003ccode\u003ePaymentSucceeded\u003c/code\u003e, \u003ccode\u003ePaymentFailed\u003c/code\u003e, \u003ccode\u003eRefundIssued\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eorderId\u003c/td\u003e\u003ctd\u003eОплата\u003c/td\u003e\u003ctd\u003eЗаказы (сага), Склад, Уведомления\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ewarehouse.events\u003c/code\u003e\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eStockReserved\u003c/code\u003e, \u003ccode\u003eStockUnavailable\u003c/code\u003e, \u003ccode\u003eReservationReleased\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eorderId\u003c/td\u003e\u003ctd\u003eСклад\u003c/td\u003e\u003ctd\u003eЗаказы (сага), Доставка, Уведомления\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003edelivery.events\u003c/code\u003e\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eDeliveryScheduled\u003c/code\u003e, \u003ccode\u003eDeliveryUnavailable\u003c/code\u003e, \u003ccode\u003eDeliveryHandedOver\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eorderId\u003c/td\u003e\u003ctd\u003eДоставка\u003c/td\u003e\u003ctd\u003eЗаказы (сага), Уведомления\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eorders.saga.commands\u003c/code\u003e\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eReserveStock\u003c/code\u003e, \u003ccode\u003eReleaseStock\u003c/code\u003e, \u003ccode\u003eRefundPayment\u003c/code\u003e, \u003ccode\u003eCancelDelivery\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eorderId\u003c/td\u003e\u003ctd\u003eОркестратор саги\u003c/td\u003e\u003ctd\u003eОплата, Склад, Доставка\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003cp\u003eФормат: JSON + Schema Registry, обязательные поля каждого события — \u003ccode\u003eeventId\u003c/code\u003e (UUID), \u003ccode\u003eeventType\u003c/code\u003e, \u003ccode\u003eeventVersion\u003c/code\u003e, \u003ccode\u003eoccurredAt\u003c/code\u003e, \u003ccode\u003ecorrelationId\u003c/code\u003e, \u003ccode\u003ecausationId\u003c/code\u003e, \u003ccode\u003eorderId\u003c/code\u003e, полезная нагрузка. Версионирование — обратно совместимое (добавление полей), ломающие изменения — через \u003ccode\u003eeventVersion\u003c/code\u003e и параллельную поддержку двух версий.\u003c/p\u003e\u003ch3\u003e2. Тип саги: оркестрация\u003c/h3\u003e\u003cp\u003eВыбираем \u003cstrong\u003eоркестрацию\u003c/strong\u003e (отдельный компонент Saga Orchestrator внутри сервиса заказов). Обоснование:\u003c/p\u003e\u003cul\u003e\u003cli\u003eПоток ветвистый (4 участника, 5 альтернативных сценариев) — в хореографии логика расползётся по сервисам и станет нечитаемой.\u003c/li\u003e\u003cli\u003eБизнес требует явные сроки и отмену: оркестратор владеет дедлайном саги и инициирует компенсации.\u003c/li\u003e\u003cli\u003eЭксплуатация требует разбирать инциденты по одному месту: состояние саги — единая таблица и единый экран.\u003c/li\u003e\u003cli\u003eЦена: оркестратор — точка концентрации логики и потенциальная точка отказа → делаем его stateless-над-БД (состояние в таблице, инстансов несколько, лидер-выбор по блокировке на sagaId).\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e3. Состояние саги\u003c/h3\u003e\u003cp\u003eТаблица \u003ccode\u003eorder_sagas\u003c/code\u003e: \u003ccode\u003esagaId\u003c/code\u003e, \u003ccode\u003eorderId\u003c/code\u003e, \u003ccode\u003estate\u003c/code\u003e (AWAITING_PAYMENT / AWAITING_RESERVATION / AWAITING_DELIVERY / COMPENSATING / COMPLETED / FAILED / CANCELLED), \u003ccode\u003ecurrentStep\u003c/code\u003e, \u003ccode\u003estepResults\u003c/code\u003e (JSON: статус каждого шага, время, ошибка), \u003ccode\u003edeadlineAt\u003c/code\u003e, \u003ccode\u003eretryCount\u003c/code\u003e, \u003ccode\u003eupdatedAt\u003c/code\u003e. Каждый переход пишется в \u003ccode\u003eorder_saga_history\u003c/code\u003e — это журнал для разбора и источник для экрана поддержки.\u003c/p\u003e\u003ch3\u003e4. Атомарность «БД + событие»: outbox\u003c/h3\u003e\u003cp\u003eКаждый сервис в одной локальной транзакции пишет бизнес-данные и строку в таблицу \u003ccode\u003eoutbox\u003c/code\u003e. Отдельный relay-процесс (или Debezium CDC) читает outbox и публикует в Kafka, помечая строку отправленной. Это исключает ситуацию «заказ записан, событие потеряно» и «событие опубликовано, заказ откатился». Ретраи relay приводят к дублям сообщений → см. пункт 5.\u003c/p\u003e\u003ch3\u003e5. Гарантии доставки и идемпотентность\u003c/h3\u003e\u003cul\u003e\u003cli\u003eПродюсер: \u003ccode\u003eacks=all\u003c/code\u003e, \u003ccode\u003eenable.idempotence=true\u003c/code\u003e, ретраи с backoff. Гарантия — at-least-once.\u003c/li\u003e\u003cli\u003eПотребитель: обработка сообщения и фиксация \u003ccode\u003eeventId\u003c/code\u003e в таблице \u003ccode\u003eprocessed_events\u003c/code\u003e (unique по \u003ccode\u003econsumerName + eventId\u003c/code\u003e) в одной транзакции. Дубль → пропускаем, пишем в метрику.\u003c/li\u003e\u003cli\u003eОффсеты коммитим только после успешной обработки (не auto-commit), иначе потеря сообщения.\u003c/li\u003e\u003cli\u003eExactly-once в Kafka (транзакционный продюсер) используем только для внутренних перекладываний между топиками; для бизнес-эффектов всё равно нужна идемпотентность на уровне БД, поэтому не полагаемся на EOS как на единственный механизм.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e6. Партиционирование и порядок\u003c/h3\u003e\u003cp\u003eКлюч партиционирования — \u003ccode\u003eorderId\u003c/code\u003e во всех топиках потока. Все события одного заказа попадают в одну партицию и читаются одним консьюмером группы → порядок внутри заказа гарантирован. Между заказами — параллельность по числу партиций (стартуем с 24, масштабируем по лагу). Перебалансировка группы на короткое время останавливает потребление: учитываем в дедлайне саги (не ставим таймаут меньше 30 секунд). Для сообщений, где важен глобальный порядок (их нет в этом потоке), партиционирование не применяем.\u003c/p\u003e\u003ch3\u003e7. Альтернативные сценарии\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eОплата не прошла\u003c/strong\u003e → сага в FAILED, заказ в \u003ccode\u003ePAYMENT_FAILED\u003c/code\u003e, резерва нет (он ещё не создавался), уведомление пользователю с причиной и кнопкой «повторить оплату» (новая сага, новый \u003ccode\u003esagaId\u003c/code\u003e, тот же \u003ccode\u003eorderId\u003c/code\u003e).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eТовара нет на складе\u003c/strong\u003e (\u003ccode\u003eStockUnavailable\u003c/code\u003e) → оркестратор шлёт \u003ccode\u003eRefundPayment\u003c/code\u003e, заказ в \u003ccode\u003eCANCELLED_NO_STOCK\u003c/code\u003e, уведомление + предложение похожего товара. Возврат идемпотентен по \u003ccode\u003esagaId\u003c/code\u003e.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eНет слота доставки\u003c/strong\u003e → \u003ccode\u003eReleaseStock\u003c/code\u003e + \u003ccode\u003eRefundPayment\u003c/code\u003e, заказ в \u003ccode\u003eCANCELLED_NO_DELIVERY\u003c/code\u003e. Альтернатива по согласованию с бизнесом: предложить самовывоз вместо полного отката.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eОтмена пользователем до передачи в доставку\u003c/strong\u003e → \u003ccode\u003eOrderCancelled\u003c/code\u003e: если резерв есть — освобождаем, если оплата прошла — возврат; если уже \u003ccode\u003eDeliveryHandedOver\u003c/code\u003e — отмена невозможна, пользователь видит «отмена недоступна, оформите возврат после получения».\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЗависший шаг\u003c/strong\u003e → дедлайн шага (оплата 5 мин, резерв 2 мин, доставка 5 мин). По дедлайну оркестратор опрашивает состояние участника (read-model запрос) и либо продолжает, либо запускает компенсацию. Сага старше 30 минут → алерт и ручная очередь разбора.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e8. Ошибки потребителей и DLQ\u003c/h3\u003e\u003cp\u003eЛокальные ретраи: 3 попытки с backoff 1/5/25 секунд (для временных ошибок: недоступность БД, таймаут внешнего сервиса). После исчерпания — сообщение в \u003ccode\u003e*.dlq\u003c/code\u003e с заголовками: исходный топик, партиция, offset, ошибка, число попыток, \u003ccode\u003ecorrelationId\u003c/code\u003e. Сага при этом не «молча умирает»: шаг помечается \u003ccode\u003eFAILED_NEEDS_ATTENTION\u003c/code\u003e, создаётся задача в очереди разбора. Инструмент replay: повторная публикация сообщения из DLQ после исправления (с тем же \u003ccode\u003eeventId\u003c/code\u003e → идемпотентно).\u003c/p\u003e\u003ch3\u003e9. Наблюдаемость\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eСквозной ID:\u003c/strong\u003e \u003ccode\u003ecorrelationId\u003c/code\u003e = orderId (читаемый) + технический \u003ccode\u003etraceId\u003c/code\u003e (W3C traceparent) пробрасывается во все события, HTTP-заголовки и логи.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eМетрики:\u003c/strong\u003e consumer lag по группам, темп публикации/потребления по топикам, доля дублей, размер DLQ, длительность саги (p50/p95), число саг по состояниям, число компенсаций, число саг с истёкшим дедлайном.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eАлерты:\u003c/strong\u003e lag \u0026gt; 10 000 сообщений 5 минут; DLQ \u0026gt; 0 за 15 минут; саги в COMPENSATING \u0026gt; 30 минут; доля FAILED \u0026gt; 1% за час.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЭкран разбора:\u003c/strong\u003e по номеру заказа — таймлайн саги (шаги, время, ошибки), все связанные события, текущие состояния в каждом сервисе, доступные действия (повторить шаг, запустить компенсацию, отправить в ручной разбор). Доступ поддержке без разработчика — это прямое требование эксплуатации.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e10. Сверка\u003c/h3\u003e\u003cp\u003eЕжечасная сверка read-моделей: заказы в \u003ccode\u003eCOMPLETED\u003c/code\u003e должны иметь успешную оплату, резерв (или факт отгрузки) и назначенную доставку. Расхождения — в очередь разбора с автоматической классификацией. Целевой KPI: не более 0,01% заказов в нераскрытом расхождении старше 1 часа.\u003c/p\u003e\u003ch3\u003e11. Что видит пользователь\u003c/h3\u003e\u003cp\u003eСтатусы заказа: \u003ccode\u003eОформляется\u003c/code\u003e (сага в работе, не дольше 10 секунд — за это время обычно проходят оплата и резерв), \u003ccode\u003eОплачен, собираем\u003c/code\u003e, \u003ccode\u003eПередан в доставку\u003c/code\u003e, \u003ccode\u003eОтменён (причина)\u003c/code\u003e. Обновление — push + опрос статуса раз в 3 секунды на экране заказа (WebSocket как улучшение). Если сага идёт дольше 30 секунд, пользователь видит «Проверяем оплату, обычно это занимает меньше минуты» и получает уведомление о результате. Никаких «ошибка 500» на экране оформления: любая техническая ошибка маппится в понятный статус и действие.\u003c/p\u003e","plantuml":"@startuml\nautonumber\nskinparam maxMessageSize 240\nparticipant \"Пользователь\" as U\nparticipant \"Сервис заказов\\n(+ Saga Orchestrator)\" as ORD\ndatabase \"outbox / saga state\" as DB\nqueue \"Kafka\" as K\nparticipant \"Оплата\" as PAY\nparticipant \"Склад\" as WH\nparticipant \"Доставка\" as DLV\nparticipant \"Уведомления\" as NOTIF\n\nU -\u003e ORD: Оформить заказ\nORD -\u003e DB: INSERT order + saga(AWAITING_PAYMENT) + outbox\nDB --\u003e ORD: ok\nORD -\u003e K: OrderCreated (key=orderId)\nORD --\u003e U: 202 \"Оформляется\"\n\nK -\u003e PAY: OrderCreated\nPAY -\u003e PAY: списание (внешний провайдер)\nalt оплата успешна\n  PAY -\u003e K: PaymentSucceeded\n  K -\u003e ORD: PaymentSucceeded\n  ORD -\u003e DB: saga -\u003e AWAITING_RESERVATION\n  ORD -\u003e K: ReserveStock (command)\n  K -\u003e WH: ReserveStock\n  alt товар есть\n    WH -\u003e K: StockReserved\n    K -\u003e ORD: StockReserved\n    ORD -\u003e DB: saga -\u003e AWAITING_DELIVERY\n    ORD -\u003e K: ScheduleDelivery\n    K -\u003e DLV: ScheduleDelivery\n    DLV -\u003e K: DeliveryScheduled\n    K -\u003e ORD: DeliveryScheduled\n    ORD -\u003e DB: saga -\u003e COMPLETED\n    ORD -\u003e K: OrderCompleted\n    K -\u003e NOTIF: OrderCompleted\n    NOTIF -\u003e U: push \"Заказ подтверждён\"\n  else товара нет\n    WH -\u003e K: StockUnavailable\n    K -\u003e ORD: StockUnavailable\n    ORD -\u003e DB: saga -\u003e COMPENSATING\n    ORD -\u003e K: RefundPayment\n    K -\u003e PAY: RefundPayment\n    PAY -\u003e K: RefundIssued\n    K -\u003e ORD: RefundIssued\n    ORD -\u003e DB: saga -\u003e CANCELLED_NO_STOCK\n    ORD -\u003e K: OrderCancelled\n    K -\u003e NOTIF: OrderCancelled\n    NOTIF -\u003e U: push \"Товара нет, деньги вернули\"\n  end\nelse оплата не прошла\n  PAY -\u003e K: PaymentFailed\n  K -\u003e ORD: PaymentFailed\n  ORD -\u003e DB: saga -\u003e FAILED\n  ORD -\u003e K: OrderCancelled\n  K -\u003e NOTIF: OrderCancelled\n  NOTIF -\u003e U: push \"Оплата не прошла, повторить?\"\nend\n@enduml\n","mermaid":"flowchart TD\n  A([OrderCreated]) --\u003e B{Оплата}\n  B --\u003e|PaymentSucceeded| C[ReserveStock]\n  B --\u003e|PaymentFailed| F1[FAILED\\nуведомление: повторить оплату]\n  B --\u003e|дедлайн 5 мин| T1[Опрос статуса оплаты]\n  T1 --\u003e|успех| C\n  T1 --\u003e|неизвестно| T2[Ручной разбор]\n  C --\u003e D{Склад}\n  D --\u003e|StockReserved| E[ScheduleDelivery]\n  D --\u003e|StockUnavailable| G[COMPENSATING]\n  D --\u003e|дедлайн 2 мин| T3[Опрос склада]\n  T3 --\u003e D\n  E --\u003e H{Доставка}\n  H --\u003e|DeliveryScheduled| I([COMPLETED\\nOrderCompleted])\n  H --\u003e|DeliveryUnavailable| G\n  H --\u003e|дедлайн 5 мин| T4[Опрос доставки]\n  T4 --\u003e H\n  G --\u003e G1[RefundPayment]\n  G --\u003e G2[ReleaseStock]\n  G1 --\u003e J([CANCELLED\\nOrderCancelled])\n  G2 --\u003e J\n  K([OrderCancelled by user]) --\u003e L{Этап}\n  L --\u003e|до резерва| M[Отмена без компенсаций]\n  L --\u003e|после резерва| G\n  L --\u003e|передано в доставку| N[Отмена невозможна\\nвозврат после получения]\n"}'::jsonb, updated_at = now() WHERE id = 'int-kafka-events';
UPDATE tasks SET statement = '{"brief":"Три внешних партнёра получают доступ к нашему REST API. Нужна схема авторизации, права, лимиты и аудит.","context":["Вы аналитик платформы. Продукт — B2B-сервис, у нас есть публичный REST API. Три партнёра хотят интеграцию: агрегатор (читает данные о заказах своих клиентов), бухгалтерский сервис (читает и создаёт документы), крупный корпоративный клиент (управляет своими сотрудниками и настройками).","Сейчас партнёрам выдают «общий токен в конфиге», который не истекает. Безопасность требует закрыть эту практику: нужны отдельные учётные данные на партнёра, ограниченные права, возможность отозвать доступ за минуты и полный аудит обращений.","Есть требования регулятора по защите персональных данных: партнёры не должны получать больше данных, чем нужно для их сценария."],"goal":"Спроектировать модель доступа партнёров к API: грант-тип OAuth 2.0, скоупы и права, жизненный цикл учётных данных, лимиты, аудит и процесс подключения/отключения партнёра.","inputs":["Три разных профиля доступа (чтение, чтение+запись, управление настройками).","У каждого партнёра несколько окружений (тест и прод) и возможность ротации секретов.","Ожидаемая нагрузка: агрегатор — 50 rps, бухгалтерия — 5 rps, корпоративный клиент — 1 rps с пиками в отчётные периоды.","Данные в API включают персональные данные клиентов и сотрудников."],"deliverables":["Выбор грант-типа OAuth 2.0 с обоснованием (почему не другой), описание потока получения и обновления токена.","Модель скоупов и прав: гранулярность по ресурсам и операциям, как скоупы связываются с учёткой партнёра.","Жизненный цикл секретов: выдача, хранение, ротация, отзыв, срок жизни токенов.","Лимиты (rate limiting): по какому признаку, какие значения, что возвращаем при превышении, деградация.","Аудит и безопасность: что логируем, как расследуем инцидент, защита от утечки токена, передача ПДн.","Операционный процесс: подключение партнёра, смена прав, отзыв доступа, что делает поддержка.","Ошибки и отказы: какие коды и сообщения видит партнёр, как он понимает, что превысил лимит или потерял права."],"constraints":["Нельзя требовать от партнёров хранить секреты в браузере или мобильном клиенте — интеграции сервер-сервер.","Отзыв доступа должен занимать минуты, не дни.","Мы не можем хранить пароли партнёров в открытом виде и не должны видеть их секреты после выдачи."],"interview":"«Партнёрам нужен доступ к нашему API. Как организуете авторизацию, права и лимиты? Что произойдёт, если токен партнёра утечёт?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Модель доступа","content":"\u003ch3\u003eГрант-тип и поток\u003c/h3\u003e\u003ch3\u003eСкоупы и права\u003c/h3\u003e\u003ch3\u003eЛимиты\u003c/h3\u003e\u003ch3\u003eЖизненный цикл секретов\u003c/h3\u003e\u003ch3\u003eАудит\u003c/h3\u003e"},{"type":"plantuml","title":"Sequence: получение токена","content":"@startuml\nautonumber\nparticipant \"Сервис партнёра\" as P\nparticipant \"Auth Server\" as AUTH\nparticipant \"API Gateway\" as GW\nparticipant \"Ресурс-сервис\" as API\ndatabase \"Учётные данные\" as DB\n\nP -\u003e AUTH: POST /oauth/token\\ngrant_type=?\nAUTH -\u003e DB: проверить client_id / secret\nDB --\u003e AUTH: ?\nAUTH --\u003e P: access_token + ?\nP -\u003e GW: GET /v1/orders\\nAuthorization: Bearer ?\nGW -\u003e GW: проверить токен и скоупы\nGW -\u003e API: запрос\nAPI --\u003e GW: данные\nGW --\u003e P: 200 / 403 / 429 ?\n@enduml\n"}]'::jsonb, rubric = '[{"id":"grant-choice","title":"Обоснованный выбор грант-типа (client_credentials для server-to-server) и почему не password/implicit/auth code","weight":"high","weightValue":null,"focus":"arch","keywords":["client_credentials","грант","grant_type","server-to-server","не implicit","authorization code","m2m","machine"],"why":"Выбор гранта определяет всю схему. Implicit/password — типовая ошибка на собеседовании для серверной интеграции.","critical":false},{"id":"token-lifecycle","title":"Срок жизни access token короткий, refresh/ротация, поведение при истечении (401 + WWW-Authenticate)","weight":"high","weightValue":null,"focus":"arch","keywords":["access token","expires_in","refresh","300","15 минут","истеч","401","ротаци","jwt","ttl"],"why":"Вечный токен — это вечная дыра. Короткий TTL ограничивает ущерб от утечки, но требует продуманного обновления.","critical":false},{"id":"scopes","title":"Модель скоупов: ресурс + операция, привязка к учётке партнёра, проверка на каждом запросе","weight":"high","weightValue":null,"focus":"sa","keywords":["scope","скоуп","orders:read","права","разрешен","доступ к ресурс","grant","роль","rbac"],"why":"«Общий токен» из условия лечится именно скоупами. Без granularity партнёр получит больше данных, чем нужно — это нарушение требования регулятора.","critical":false},{"id":"data-minimization","title":"Минимизация данных: партнёр видит только своих клиентов, поля ПДн фильтруются, tenant isolation","weight":"high","weightValue":null,"focus":"sa","keywords":["персональн","пдн","152","tenant","изоли","только своих","маскир","фильтр","минимизац","consent","соглаш"],"why":"Прямое требование задачи: не отдавать больше, чем нужно для сценария. Здесь проверяют зрелость работы с ПДн.","critical":false},{"id":"rate-limit","title":"Лимиты: по client_id (а не по IP), окна и значения, заголовки X-RateLimit, 429 + Retry-After","weight":"high","weightValue":null,"focus":"arch","keywords":["rate limit","лимит","429","retry-after","x-ratelimit","окно","rps","quota","клиент","burst"],"why":"Агрегатор на 50 rps уронит сервис без квот. Лимит по IP бесполезен, если партнёр за NAT или прокси.","critical":false},{"id":"secret-mgmt","title":"Управление секретами: хранение в виде хэша, выдача один раз, ротация с перекрытием, отзыв за минуты","weight":"high","weightValue":null,"focus":"arch","keywords":["хэш","hash","bcrypt","хран","ротаци","отзыв","revoke","один раз","vault","secret","перекрыт","два секрет"],"why":"Требование «не должны видеть секреты после выдачи» и «отзыв за минуты» — это конкретные механизмы, которые надо назвать.","critical":false},{"id":"audit","title":"Аудит: кто, когда, к какому ресурсу, с каким результатом; расследование инцидента; хранение журнала","weight":"mid","weightValue":null,"focus":"sa","keywords":["аудит","audit","журнал","лог","кто","расслед","инцидент","хранен","requestid","события доступа"],"why":"Без журнала обращений невозможно ни расследовать утечку, ни доказать объём переданных ПДн.","critical":false},{"id":"leak-response","title":"Реакция на утечку токена: немедленный отзыв, anomaly detection, уведомление партнёра и ДПО","weight":"mid","weightValue":null,"focus":"sa","keywords":["утечк","leak","отзыв","аномал","компрометац","уведомл","дпо","блокиров","расследован"],"why":"Вопрос «что если токен утечёт» — ключевой в условии. Ответ «ничего страшного» = провал.","critical":false},{"id":"errors","title":"Понятные ошибки партнёру: 401/403/429 различимы, сообщения не раскрывают внутренности, есть документация","weight":"mid","weightValue":null,"focus":"sa","keywords":["401","403","429","ошибк","сообщен","insufficient_scope","invalid_token","документац","developer portal"],"why":"Партнёр, который не может отличить «протух токен» от «нет прав», завалит поддержку тикетами.","critical":false},{"id":"onboarding","title":"Процесс подключения/изменения прав/отключения: роли сотрудников, сроки, тестовое окружение, чек-лист безопасности","weight":"mid","weightValue":null,"focus":"sa","keywords":["подключен","onboarding","регламент","процесс","тестов","песочниц","чек-лист","заявк","соглашен","ответств"],"why":"Техническая схема без процесса внедрения остаётся на бумаге: кто выдаёт доступ и на основании чего — вопрос к аналитику.","critical":false}]'::jsonb, hints = '["Интеграции сервер-сервер, пользователя в потоке нет. Какой грант OAuth 2.0 для этого создан?","Лимит по IP не сработает: партнёры ходят через NAT и облачные прокси. По какому признаку ограничивать?","Ротация секрета без простоя означает, что в какой-то момент валидны два секрета. Как это оформить?"]'::jsonb, interview_questions = '["Почему client_credentials, а не authorization code?","Сколько живёт access token и что делает партнёр, когда он истёк?","Как вы ограничите партнёра только его собственными клиентами?","Токен агрегатора утёк в публичный репозиторий. Ваши действия по минутам?","Как партнёр поймёт, что упёрся в лимит, и что будет при превышении?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Грант-тип\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eOAuth 2.0 Client Credentials Grant\u003c/strong\u003e (\u003ccode\u003egrant_type=client_credentials\u003c/code\u003e). Обоснование: интеграции сервер-сервер, пользователь-владелец ресурса в потоке не участвует, партнёр выступает от своего имени в рамках выданных скоупов. Не подходят: \u003ccode\u003eauthorization_code\u003c/code\u003e (нужен пользователь и редиректы — лишнее для M2M), \u003ccode\u003eimplicit\u003c/code\u003e (устарел, токен во фрагменте URL), \u003ccode\u003epassword\u003c/code\u003e (требует чужие креденшелы, запрещён OAuth 2.1). Дополнительно для чувствительных операций — приватный JWT (client assertion, \u003ccode\u003eprivate_key_jwt\u003c/code\u003e) вместо общего секрета: секрет не ходит по сети.\u003c/p\u003e\u003ch3\u003e2. Поток\u003c/h3\u003e\u003col\u003e\u003cli\u003eПартнёр: \u003ccode\u003ePOST /oauth/token\u003c/code\u003e с \u003ccode\u003eclient_id\u003c/code\u003e, \u003ccode\u003eclient_secret\u003c/code\u003e (или client assertion), \u003ccode\u003egrant_type=client_credentials\u003c/code\u003e, \u003ccode\u003escope=orders:read documents:write\u003c/code\u003e.\u003c/li\u003e\u003cli\u003eAuth Server проверяет учётку, пересечение запрошенных скоупов с разрешёнными, выдаёт \u003ccode\u003eaccess_token\u003c/code\u003e (JWT, TTL 900 секунд) и \u003ccode\u003eexpires_in\u003c/code\u003e. Refresh token для client_credentials не выдаём — партнёр просто запрашивает новый токен; это убирает целый класс утечек.\u003c/li\u003e\u003cli\u003eПартнёр ходит в API с \u003ccode\u003eAuthorization: Bearer\u003c/code\u003e. Gateway валидирует подпись, срок, \u003ccode\u003eiss\u003c/code\u003e/\u003ccode\u003eaud\u003c/code\u003e, статус учётки (не отозвана), скоупы, лимиты.\u003c/li\u003e\u003cli\u003eИстёк токен → \u003ccode\u003e401\u003c/code\u003e + \u003ccode\u003eWWW-Authenticate: error=\"invalid_token\"\u003c/code\u003e; партнёр запрашивает новый. Рекомендуем кэшировать токен до 80% TTL и обновлять заранее.\u003c/li\u003e\u003c/ol\u003e\u003ch3\u003e3. Скоупы и права\u003c/h3\u003e\u003cp\u003eФормат \u003ccode\u003eресурс:операция\u003c/code\u003e, например \u003ccode\u003eorders:read\u003c/code\u003e, \u003ccode\u003edocuments:read\u003c/code\u003e, \u003ccode\u003edocuments:write\u003c/code\u003e, \u003ccode\u003eemployees:manage\u003c/code\u003e, \u003ccode\u003esettings:manage\u003c/code\u003e. Скоупы — whitelist на учётке партнёра: запрос скоупа сверх разрешённого → \u003ccode\u003e400 invalid_scope\u003c/code\u003e, а не «тихо урежем». Проверка — на gateway (быстрый отказ) и повторно в сервисе (защита от обхода gateway).\u003c/p\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eПартнёр\u003c/th\u003e\u003cth\u003eСкоупы\u003c/th\u003e\u003cth\u003eДанные\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eАгрегатор\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eorders:read\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eТолько заказы клиентов, давших согласие агрегатору; ПДн урезаны (без телефонов и адресов)\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eБухгалтерский сервис\u003c/td\u003e\u003ctd\u003e\u003ccode\u003edocuments:read\u003c/code\u003e, \u003ccode\u003edocuments:write\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eДокументы своего tenant; ИНН/наименования — да, паспортные данные — нет\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eКорпоративный клиент\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eemployees:manage\u003c/code\u003e, \u003ccode\u003esettings:manage\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eСотрудники и настройки своего tenant\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003ch3\u003e4. Изоляция данных и ПДн\u003c/h3\u003e\u003cul\u003e\u003cli\u003eВ токен кладём \u003ccode\u003etenant_id\u003c/code\u003e и \u003ccode\u003eclient_id\u003c/code\u003e; все запросы фильтруются по tenant на уровне репозитория, а не в коде контроллера (иначе забудут).\u003c/li\u003e\u003cli\u003eПоля ПДн отдаются через проекцию скоупа: \u003ccode\u003eorders:read\u003c/code\u003e возвращает \u003ccode\u003ecustomerRef\u003c/code\u003e (псевдоним), а не ФИО/телефон. Полный состав — только по отдельному скоупу с письменным согласием и фиксацией в соглашении.\u003c/li\u003e\u003cli\u003eКаждая выдача расширенного скоупа — запись в реестре обработок ПДн: основание, объём, срок, ответственный.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e5. Лимиты\u003c/h3\u003e\u003cul\u003e\u003cli\u003eКлюч лимитирования — \u003ccode\u003eclient_id\u003c/code\u003e (+ отдельно \u003ccode\u003etenant_id\u003c/code\u003e), не IP. Алгоритм — token bucket, окно 1 секунда + минутный потолок.\u003c/li\u003e\u003cli\u003eЗначения: агрегатор 50 rps / 2 000 в минуту; бухгалтерия 10 rps / 300 в минуту; корпоративный клиент 5 rps / 150 в минуту. Повышение — по заявке с обоснованием (не «на глаз»).\u003c/li\u003e\u003cli\u003eОтветы: заголовки \u003ccode\u003eX-RateLimit-Limit\u003c/code\u003e, \u003ccode\u003eX-RateLimit-Remaining\u003c/code\u003e, \u003ccode\u003eX-RateLimit-Reset\u003c/code\u003e. Превышение → \u003ccode\u003e429\u003c/code\u003e + \u003ccode\u003eRetry-After\u003c/code\u003e и код \u003ccode\u003erate_limit_exceeded\u003c/code\u003e.\u003c/li\u003e\u003cli\u003eПики отчётных периодов: отдельная «буст-квота» по расписанию, а не постоянный запас.\u003c/li\u003e\u003cli\u003eЛимит не должен убивать нас самих: при исчерпании общей ёмкости приоритет у партнеров с SLA, остальные получают 429 (деградация предсказуема).\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e6. Жизненный цикл секретов\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eВыдача:\u003c/strong\u003e секрет генерируется криптографически (256 бит), показывается один раз в личном кабинете/по защищённому каналу, в БД хранится только хэш (bcrypt/argon2). Никто из сотрудников не видит секрет после выдачи.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eРотация:\u003c/strong\u003e обязательна раз в 180 дней. Схема с перекрытием: новый секрет активен сразу, старый — ещё 14 дней, затем отзывается. Это позволяет партнёру обновиться без простоя.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eОтзыв:\u003c/strong\u003e кнопка «Отозвать доступ» в кабинете + API для безопасности. Отзыв мгновенный: gateway проверяет статус учётки и \u003ccode\u003etoken_version\u003c/code\u003e в кэше с TTL 60 секунд; при критическом инциденте — принудительная инвалидация кэша (отзыв за \u0026lt; 1 минуты).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eТест/прод:\u003c/strong\u003e отдельные учётки и отдельные скоупы; в тестовой среде — обезличенные данные.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e7. Аудит и расследование\u003c/h3\u003e\u003cul\u003e\u003cli\u003eЖурналируем каждое обращение: время, \u003ccode\u003eclient_id\u003c/code\u003e, \u003ccode\u003etenant_id\u003c/code\u003e, скоупы токена, метод и путь, \u003ccode\u003erequestId\u003c/code\u003e, IP и User-Agent, код ответа, объём выданных записей, идентификаторы затронутых сущностей. Хранение — 12 месяцев в горячем виде, 3 года в архиве.\u003c/li\u003e\u003cli\u003eЖурналируем события безопасности: выдача/ротация/отзыв секретов, изменение скоупов, превышения лимитов, попытки запросить скоуп сверх разрешённого, валидация токена с истёкшим сроком.\u003c/li\u003e\u003cli\u003eAnomaly detection: всплеск запросов в нерабочее время, обращение к нетипичным ресурсам, рост доли 403/429, запросы из новой географии → алерт в безопасность.\u003c/li\u003e\u003cli\u003eРасследование: по \u003ccode\u003eclient_id\u003c/code\u003e и периоду получаем полный список обращений и выгруженных данных — это же основа ответа регулятору об объёме передачи ПДн.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e8. Утечка токена/секрета\u003c/h3\u003e\u003col\u003e\u003cli\u003e0–2 мин: отзыв учётки (или повышение \u003ccode\u003etoken_version\u003c/code\u003e) + инвалидация кэша → все выданные токены невалидны.\u003c/li\u003e\u003cli\u003e2–10 мин: блокировка подозрительных запросов, оценка объёма утечки по журналу (какие данные и за какой период получены).\u003c/li\u003e\u003cli\u003e10–60 мин: уведомление партнёра по регламентному каналу, выпуск нового секрета, разбор причин.\u003c/li\u003e\u003cli\u003eДалее: при затрагивании ПДн — уведомление ДПО и, при необходимости, регулятора в установленный срок; постмортем и правила (например, обязательный \u003ccode\u003eprivate_key_jwt\u003c/code\u003e для партнёров с расширенным доступом).\u003c/li\u003e\u003c/ol\u003e\u003ch3\u003e9. Ошибки для партнёра\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eКод\u003c/th\u003e\u003cth\u003eerror\u003c/th\u003e\u003cth\u003eСмысл\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e401\u003c/td\u003e\u003ctd\u003e\u003ccode\u003einvalid_token\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eТокен истёк/невалиден — получить новый\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e401\u003c/td\u003e\u003ctd\u003e\u003ccode\u003einvalid_client\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eНеверный client_id/secret или учётка отозвана\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e403\u003c/td\u003e\u003ctd\u003e\u003ccode\u003einsufficient_scope\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eНет прав на операцию — в ответе указываем требуемый скоуп\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e403\u003c/td\u003e\u003ctd\u003e\u003ccode\u003etenant_mismatch\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eЗапрос к чужим данным\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e429\u003c/td\u003e\u003ctd\u003e\u003ccode\u003erate_limit_exceeded\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eПревышен лимит + \u003ccode\u003eRetry-After\u003c/code\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e400\u003c/td\u003e\u003ctd\u003e\u003ccode\u003einvalid_scope\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eЗапрошен неразрешённый скоуп\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003cp\u003eСообщения не содержат внутренних деталей (имён сервисов, стеков, версий БД). Всё это описано в портале разработчика вместе с примерами, песочницей и коллекцией Postman.\u003c/p\u003e\u003ch3\u003e10. Процесс подключения\u003c/h3\u003e\u003col\u003e\u003cli\u003eЗаявка партнёра: сценарий интеграции, нужные данные, ожидаемая нагрузка, юрлицо.\u003c/li\u003e\u003cli\u003eАналитик + безопасник определяют минимальный набор скоупов (принцип least privilege) и квоту; для ПДн — основание и соглашение.\u003c/li\u003e\u003cli\u003eСоздание тестовой учётки, выдача секретов, прохождение чек-листа безопасности (хранение секрета, обработка 401/429, идемпотентность записи).\u003c/li\u003e\u003cli\u003eПилот в песочнице: функциональные тесты + тест лимитов.\u003c/li\u003e\u003cli\u003eВыдача прод-учётки после подписания соглашения; запись в реестр партнёров с владельцем и датой следующей ротации.\u003c/li\u003e\u003cli\u003eИзменение прав — только через заявку и повторное согласование; отзыв — по инициативе владельца интеграции или безопасности, с уведомлением партнёра.\u003c/li\u003e\u003c/ol\u003e","plantuml":"@startuml\nautonumber\nparticipant \"Сервис партнёра\" as P\nparticipant \"Auth Server\" as AUTH\ndatabase \"Учётные данные\\n(client_id, secret_hash, scopes, token_version)\" as DB\nparticipant \"API Gateway\" as GW\nparticipant \"Ресурс-сервис\" as API\nparticipant \"Журнал аудита\" as AUD\n\n== Получение токена ==\nP -\u003e AUTH: POST /oauth/token\\ngrant_type=client_credentials\\nclient_id, client_secret, scope=orders:read\nAUTH -\u003e DB: найти учётку, сверить хэш секрета\\nпроверить статус и разрешённые скоупы\nalt учётка валидна\n  DB --\u003e AUTH: scopes, tenant_id, token_version\n  AUTH --\u003e P: 200 access_token (JWT, 900 сек)\\n+ expires_in, scope\n  AUTH -\u003e AUD: событие \"token_issued\"\nelse секрет неверен / учётка отозвана\n  DB --\u003e AUTH: ошибка\n  AUTH --\u003e P: 401 invalid_client\n  AUTH -\u003e AUD: событие \"auth_failed\" (алерт безопасности)\nend\n\n== Рабочий запрос ==\nP -\u003e GW: GET /v1/orders?limit=100\\nAuthorization: Bearer \u003cJWT\u003e\nGW -\u003e GW: проверить подпись, exp, iss, aud\nGW -\u003e DB: status + token_version (кэш 60 сек)\nGW -\u003e GW: скоуп orders:read? лимит 50 rps не исчерпан?\nalt всё в порядке\n  GW -\u003e API: запрос + tenant_id, client_id, requestId\n  API -\u003e API: фильтр по tenant, проекция полей ПДн\n  API --\u003e GW: данные (customerRef, без телефонов)\n  GW --\u003e P: 200 + X-RateLimit-Remaining\n  GW -\u003e AUD: обращение: кто, что, объём, requestId\nelse нет прав\n  GW --\u003e P: 403 insufficient_scope\\n(указываем требуемый скоуп)\n  GW -\u003e AUD: событие \"access_denied\"\nelse лимит исчерпан\n  GW --\u003e P: 429 rate_limit_exceeded + Retry-After\n  GW -\u003e AUD: событие \"rate_limited\"\nelse токен истёк\n  GW --\u003e P: 401 invalid_token + WWW-Authenticate\n  P -\u003e AUTH: новый токен\nend\n\n== Отзыв доступа (инцидент) ==\nnote over AUTH, DB: оператор нажимает \"Отозвать\"\nAUTH -\u003e DB: status=REVOKED, token_version++\nAUTH -\u003e GW: инвалидация кэша (\u003c 1 мин)\nGW --\u003e P: 401 invalid_client на все запросы\nAUTH -\u003e AUD: событие \"credentials_revoked\"\n@enduml\n"}'::jsonb, updated_at = now() WHERE id = 'int-oauth-partner';
UPDATE tasks SET statement = '{"brief":"Каталог товаров ведут в Excel. Нужна схема БД, которая выдержит варианты товаров, цены по складам и историю изменений.","context":["Интернет-магазин. Менеджеры ведут товары в Excel-файле: одна строка — одна позиция. Проблемы начались, когда у футболки появились размеры и цвета, а у одного товара — разные цены на разных складах.","Сейчас в таблице колонки: «Название», «Артикул», «Размер», «Цвет», «Цена», «Склад», «Остаток», «Описание», «Категория», «Бренд». Одна и та же футболка занимает 12 строк, описание и название повторяются, при смене цены менеджеры правят не все строки.","Разработка просит нормальную схему БД. Бизнес просит, чтобы можно было смотреть, кто и когда менял цену."],"goal":"Спроектировать модель данных каталога: сущности, атрибуты, связи, ключи, и показать, как решаются повторяющиеся данные и история изменений цены.","inputs":["Пример строки Excel: «Футболка Basic», артикул TS-BASIC-RED-M, размер M, цвет красный, цена 1 290 ₽, склад МСК-1, остаток 14, описание (2 абзаца), категория «Одежда/Футболки», бренд «Basic».","У товара может быть 1–30 вариантов (размер × цвет), у варианта — свой артикул, своя цена и свои остатки по складам.","Складов 7, товар может отсутствовать на части складов.","Характеристики разные для разных категорий: у футболки — состав и размер, у ноутбука — процессор и память."],"deliverables":["Перечень сущностей с атрибутами, первичными и внешними ключами, указанием обязательности и типа данных.","Диаграмма (ER или PlantUML/Mermaid) со связями и cardinality.","Решение для вариантов товара и для остатков по складам.","Подход к разнотипным характеристикам категорий (минимум два варианта с плюсами и минусами).","Как храним историю изменения цены.","Что происходит с данными при удалении товара или закрытии склада (целостность)."],"constraints":["Один артикул = ровно одна продаваемая позиция: дублей артикулов быть не должно.","Цена и остаток привязаны к складу и могут меняться несколько раз в день.","Каталог — до 200 тысяч товаров и 2 млн вариантов, чтение сильно превышает запись."],"interview":"«Нарисуйте схему БД для каталога товаров с вариантами и остатками по складам. Как будете хранить характеристики разных категорий?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Описание модели","content":"\u003ch3\u003eСущности и атрибуты\u003c/h3\u003e\u003ch3\u003eСвязи\u003c/h3\u003e\u003ch3\u003eХарактеристики категорий\u003c/h3\u003e\u003ch3\u003eИстория цены\u003c/h3\u003e"},{"type":"mermaid","title":"ER-диаграмма","content":"erDiagram\n  CATEGORY ||--o{ PRODUCT : \"содержит\"\n  BRAND ||--o{ PRODUCT : \"производит\"\n  PRODUCT ||--o{ PRODUCT_VARIANT : \"имеет\"\n  PRODUCT_VARIANT ||--o{ STOCK_ITEM : \"учитывается\"\n  WAREHOUSE ||--o{ STOCK_ITEM : \"хранит\"\n"}]'::jsonb, rubric = '[{"id":"product-variant-split","title":"Разделение «товар» (карточка) и «вариант» (продаваемая позиция с артикулом)","weight":"high","weightValue":null,"focus":"sa","keywords":["вариант","variant","sku","карточк","product","артикул","размер","цвет"],"why":"Главная ошибка — хранить всё в одной таблице: описание дублируется, цена «размазана». Разделение карточки и SKU — база предметной области.","critical":false},{"id":"stock-per-warehouse","title":"Остатки отдельной сущностью (вариант × склад), а не колонками «остаток МСК-1», «остаток СПБ-2»","weight":"high","weightValue":null,"focus":"arch","keywords":["остатк","stock","склад","warehouse","таблиц","множествен","пересечен"],"why":"Колонки под склады не масштабируются: новый склад = изменение схемы. Отдельная таблица связей решает это.","critical":false},{"id":"attributes-approach","title":"Подход к характеристикам категорий: EAV / JSONB / отдельные таблицы атрибутов — с плюсами и минусами","weight":"high","weightValue":null,"focus":"arch","keywords":["eav","jsonb","json","атрибут","характеристик","свойств","attribute","динамич","гибк"],"why":"Разнотипные характеристики — самая интересная часть задачи. Один названный подход без альтернатив = слабый ответ.","critical":false},{"id":"price-history","title":"История изменения цены: отдельная таблица с периодом действия или версиями, а не «обновляем поле»","weight":"high","weightValue":null,"focus":"sa","keywords":["истори","history","price_log","верси","период","valid_from","кто изменил","аудит","предыдущ"],"why":"Бизнес прямо просит видеть, кто и когда менял цену. Обновление поля в таблице этого не даст.","critical":false},{"id":"keys-constraints","title":"Ключи и ограничения: уникальность артикула, обязательность, внешние ключи, каскады","weight":"mid","weightValue":null,"focus":"arch","keywords":["unique","уникальн","primary key","foreign key","внешн","ограничен","constraint","not null","каск","индекс"],"why":"Без уникальности артикула каталог обрастёт дублями — это ровно та боль, от которой уходим.","critical":false},{"id":"delete-behaviour","title":"Поведение при удалении: мягкое удаление/архивация вместо физического, сохранение истории заказов","weight":"mid","weightValue":null,"focus":"sa","keywords":["soft delete","мягк","архив","is_deleted","deleted_at","статус","удален","целостн","заказ ссыл"],"why":"Товар в истории заказов есть, а в каталоге его удалили — отчёт поедет. Аналитик должен это предусмотреть.","critical":false},{"id":"read-performance","title":"Учтён перекос «чтение \u003e\u003e запись»: индексы, денормализация для выдачи, кэш","weight":"mid","weightValue":null,"focus":"arch","keywords":["индекс","денормал","кэш","чтен","производительн","витрин","поиск","materialized"],"why":"200 тысяч товаров и 2 млн вариантов: нормализованная схема без индексов и кэша даст медленный каталог.","critical":false},{"id":"category-tree","title":"Категории как иерархия (дерево), а не плоское поле «Одежда/Футболки»","weight":"low","weightValue":null,"focus":"sa","keywords":["иерарх","дерево","parent","родитель","вложен","path","closure","category"],"why":"Строка «Одежда/Футболки» в одной колонке не позволит фильтровать и переносить категории.","critical":false}]'::jsonb, hints = '["Спросите себя: что здесь «товар» — карточка на сайте или конкретная футболка размера M? Это две разные сущности.","Остаток — это свойство не товара и не склада, а их пересечения. Как это выразить в схеме?","Для истории цены есть два подхода: журнал изменений (кто/когда/что) и таблица версий с периодом действия. Чем они отличаются?"]'::jsonb, interview_questions = '["Почему вы разделили product и variant? Что будет, если не разделять?","Как вы храните состав футболки и процессор ноутбука в одной схеме?","Цена меняется 5 раз в день. Как вы узнаете цену на вчерашний день?","Товар сняли с продажи. Удаляете строку? Почему?","Какие индексы добавите и почему?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Сущности\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eСущность\u003c/th\u003e\u003cth\u003eКлючевые атрибуты\u003c/th\u003e\u003cth\u003eКомментарий\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ecategory\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, parent_id (FK → category), name, slug, level, path, is_active\u003c/td\u003e\u003ctd\u003eДерево категорий; \u003ccode\u003epath\u003c/code\u003e (materialized path) ускоряет выборку поддерева\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ebrand\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, name, slug\u003c/td\u003e\u003ctd\u003eСправочник\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eproduct\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, category_id, brand_id, name, slug, description, is_active, created_at\u003c/td\u003e\u003ctd\u003eКарточка товара: общая информация без цены и остатков\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eproduct_variant\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, product_id, sku (UNIQUE), size, color, barcode, price, is_active\u003c/td\u003e\u003ctd\u003eПродаваемая позиция (SKU). \u003ccode\u003eprice\u003c/code\u003e — текущая цена для быстрой выдачи\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ewarehouse\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, code, name, is_active\u003c/td\u003e\u003ctd\u003eСправочник складов\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003estock_item\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, variant_id, warehouse_id, quantity, reserved, updated_at; UNIQUE(variant_id, warehouse_id)\u003c/td\u003e\u003ctd\u003eОстатки на пересечении вариант × склад\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eattribute_def\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, code, name, data_type, unit, is_required, sort_order\u003c/td\u003e\u003ctd\u003eОпределения характеристик\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ecategory_attribute\u003c/code\u003e\u003c/td\u003e\u003ctd\u003ecategory_id, attribute_def_id\u003c/td\u003e\u003ctd\u003eКакие характеристики у какой категории\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003evariant_attribute\u003c/code\u003e\u003c/td\u003e\u003ctd\u003evariant_id, attribute_def_id, value_string / value_number / value_json\u003c/td\u003e\u003ctd\u003eЗначения характеристик (EAV-вариант)\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eprice_history\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, variant_id, warehouse_id?, price_old, price_new, valid_from, valid_to, changed_by, reason, created_at\u003c/td\u003e\u003ctd\u003eИстория цен с периодом действия и автором\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003ch3\u003e2. Связи\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003ccode\u003ecategory 1—∞ product\u003c/code\u003e, \u003ccode\u003ebrand 1—∞ product\u003c/code\u003e, \u003ccode\u003eproduct 1—∞ product_variant\u003c/code\u003e (1–30).\u003c/li\u003e\u003cli\u003e\u003ccode\u003eproduct_variant ∞—∞ warehouse\u003c/code\u003e через \u003ccode\u003estock_item\u003c/code\u003e (у варианта может не быть записи на складе — тогда остаток 0, строку не создаём).\u003c/li\u003e\u003cli\u003e\u003ccode\u003eproduct_variant 1—∞ price_history\u003c/code\u003e, \u003ccode\u003eproduct_variant ∞—∞ attribute_def\u003c/code\u003e через \u003ccode\u003evariant_attribute\u003c/code\u003e.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e3. Характеристики категорий: два подхода\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eВариант A — EAV\u003c/strong\u003e (\u003ccode\u003eattribute_def\u003c/code\u003e + \u003ccode\u003evariant_attribute\u003c/code\u003e): гибко, новые характеристики добавляются без миграций, удобно для админки. Минусы: сложный SQL, нет типов на уровне БД, тяжелее индексировать и валидировать.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eВариант B — JSONB-колонка\u003c/strong\u003e \u003ccode\u003eproduct_variant.attrs\u003c/code\u003e + JSON Schema по категории: просто читать и писать, есть GIN-индексы в PostgreSQL, схема валидируется на уровне приложения. Минусы: слабее целостность, сложнее аналитические запросы и миграции значений.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eРекомендация:\u003c/strong\u003e для каталога с преобладанием чтения — JSONB + \u003ccode\u003eattribute_def\u003c/code\u003e как справочник для админки и валидации (гибрид). EAV оправдан, если по характеристикам нужны отчёты и фильтры в SQL с гарантией типов. Фильтры в каталоге всё равно уходят в поисковый движок (Elasticsearch/OpenSearch), а не в SQL — это снимает часть минусов обоих подходов.\u003c/p\u003e\u003ch3\u003e4. История цены\u003c/h3\u003e\u003cp\u003eДве таблицы с разными задачами:\u003c/p\u003e\u003cul\u003e\u003cli\u003e\u003ccode\u003eprice_history\u003c/code\u003e — журнал изменений: кто, когда, старое/новое значение, причина. Источник для аудита и ответа «кто поднял цену?».\u003c/li\u003e\u003cli\u003e\u003ccode\u003eprice_version\u003c/code\u003e (опционально) — периоды действия: \u003ccode\u003evariant_id, price, valid_from, valid_to\u003c/code\u003e. Позволяет восстановить цену на любую дату для пересчёта старых заказов и отчётов.\u003c/li\u003e\u003c/ul\u003e\u003cp\u003eТекущая цена дублируется в \u003ccode\u003eproduct_variant.price\u003c/code\u003e (денормализация ради скорости выдачи) и обновляется в одной транзакции с записью истории — иначе журнал разъедется с фактом.\u003c/p\u003e\u003ch3\u003e5. Целостность и удаления\u003c/h3\u003e\u003cul\u003e\u003cli\u003eАртикул уникален: \u003ccode\u003eUNIQUE(sku)\u003c/code\u003e. Дубли невозможны на уровне БД.\u003c/li\u003e\u003cli\u003eФизическое удаление запрещено, если на вариант есть заказы: используем \u003ccode\u003eis_active = false\u003c/code\u003e (мягкое снятие с продажи) или статус \u003ccode\u003eARCHIVED\u003c/code\u003e. Ссылки из \u003ccode\u003eorder_item\u003c/code\u003e остаются валидными, отчёты не ломаются.\u003c/li\u003e\u003cli\u003eЗакрытие склада: \u003ccode\u003ewarehouse.is_active = false\u003c/code\u003e, записи \u003ccode\u003estock_item\u003c/code\u003e сохраняются (история), новые резервы не создаются.\u003c/li\u003e\u003cli\u003eУдаление категории с товарами блокируется внешней связью — предлагаем перенос товаров в другую категорию как отдельную операцию.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e6. Производительность\u003c/h3\u003e\u003cul\u003e\u003cli\u003eИндексы: \u003ccode\u003eproduct_variant(sku)\u003c/code\u003e unique, \u003ccode\u003eproduct_variant(product_id)\u003c/code\u003e, \u003ccode\u003estock_item(warehouse_id, variant_id)\u003c/code\u003e, \u003ccode\u003estock_item(variant_id)\u003c/code\u003e, \u003ccode\u003eprice_history(variant_id, valid_from desc)\u003c/code\u003e, \u003ccode\u003eproduct(category_id, is_active)\u003c/code\u003e, \u003ccode\u003ecategory(path)\u003c/code\u003e.\u003c/li\u003e\u003cli\u003eВыдача каталога — через поисковый индекс или read-модель (витрину), а не через JOIN шести таблиц на каждый запрос.\u003c/li\u003e\u003cli\u003eКэш карточки товара (Redis, TTL 5–10 мин) с инвалидацией по событию изменения; остатки не кэшируем надолго — максимум 30 секунд.\u003c/li\u003e\u003c/ul\u003e","mermaid":"erDiagram\n  CATEGORY ||--o{ CATEGORY : \"parent_id\"\n  CATEGORY ||--o{ PRODUCT : \"содержит\"\n  BRAND ||--o{ PRODUCT : \"производит\"\n  PRODUCT ||--o{ PRODUCT_VARIANT : \"имеет SKU\"\n  PRODUCT_VARIANT ||--o{ STOCK_ITEM : \"остатки\"\n  WAREHOUSE ||--o{ STOCK_ITEM : \"хранит\"\n  ATTRIBUTE_DEF ||--o{ CATEGORY_ATTRIBUTE : \"описывает\"\n  CATEGORY ||--o{ CATEGORY_ATTRIBUTE : \"имеет\"\n  PRODUCT_VARIANT ||--o{ VARIANT_ATTRIBUTE : \"значение\"\n  ATTRIBUTE_DEF ||--o{ VARIANT_ATTRIBUTE : \"определяет\"\n  PRODUCT_VARIANT ||--o{ PRICE_HISTORY : \"история цен\"\n\n  PRODUCT {\n    bigint id PK\n    bigint category_id FK\n    bigint brand_id FK\n    string name\n    string slug UK\n    text description\n    bool is_active\n  }\n  PRODUCT_VARIANT {\n    bigint id PK\n    bigint product_id FK\n    string sku UK\n    string size\n    string color\n    decimal price\n    bool is_active\n  }\n  STOCK_ITEM {\n    bigint id PK\n    bigint variant_id FK\n    bigint warehouse_id FK\n    int quantity\n    int reserved\n  }\n  PRICE_HISTORY {\n    bigint id PK\n    bigint variant_id FK\n    decimal price_old\n    decimal price_new\n    datetime valid_from\n    string changed_by\n    string reason\n  }\n"}'::jsonb, updated_at = now() WHERE id = 'des-er-catalog';
UPDATE tasks SET statement = '{"brief":"Статусы заказа живут в коде в виде строк и условий. Нужна формальная модель состояний с правилами переходов.","context":["Сервис доставки еды. Заказ проходит путь от создания до вручения или отмены. Сейчас статусы — строки в таблице, логика переходов размазана по четырём сервисам, и периодически случается «заказ отменён, но курьер его везёт».","Поддержка еженедельно разбирает 30–40 таких инцидентов вручную. Бизнес хочет: формальную модель состояний, понятные правила переходов и явные причины отмен.","Есть внешние участники: платёжный сервис, ресторан, курьерская служба. Их события приходят асинхронно и иногда в неправильном порядке."],"goal":"Описать модель состояний заказа: полный набор состояний, разрешённые переходы с событиями и условиями, обработку «невозможных» переходов и асинхронных событий.","inputs":["События: пользователь создал заказ, оплата подтверждена/отклонена, ресторан принял/отклонил, курьер назначен/забрал/вручил, пользователь отменил, поддержка отменила, истёк таймаут.","Правила бизнеса: отмена пользователем бесплатна до принятия рестораном; после принятия — только через поддержку и с удержанием; после передачи курьеру отмена невозможна.","Возврат денег возможен только если оплата прошла.","События от ресторана и курьера приходят асинхронно, возможны дубли и опоздания."],"deliverables":["Диаграмма состояний (state machine) с событиями на переходах и условиями (guards).","Таблица переходов: из какого состояния, событие, условие, в какое состояние, побочные эффекты.","Обработка недопустимых переходов: что делает система, если событие пришло в «не том» состоянии.","Модель отмены и возврата: виды отмен, кто инициатор, финансовые последствия.","Таймауты: где они нужны, что происходит по истечении.","Как модель помогает разбору инцидентов: журнал переходов, кто его ведёт."],"constraints":["Статус заказа должен быть объясним пользователю в любой момент (нельзя «неизвестное состояние» на экране).","История переходов должна храниться: поддержка разбирает инциденты задним числом.","Модель должна допускать расширение: завтра добавится «частичная отмена» и «предзаказ»."],"interview":"«Нарисуйте машину состояний заказа. Что произойдёт, если ресторан принял заказ, а оплата в это время отклонилась?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Правила переходов","content":"\u003ch3\u003eСостояния\u003c/h3\u003e\u003ch3\u003eТаблица переходов\u003c/h3\u003e\u003ch3\u003eОтмены и возвраты\u003c/h3\u003e\u003ch3\u003eТаймауты\u003c/h3\u003e"},{"type":"mermaid","title":"State machine","content":"stateDiagram-v2\n  [*] --\u003e DRAFT\n  DRAFT --\u003e AWAITING_PAYMENT: оформить\n  AWAITING_PAYMENT --\u003e PAID: оплата прошла\n  AWAITING_PAYMENT --\u003e CANCELLED: оплата отклонена\n  PAID --\u003e ACCEPTED_BY_RESTAURANT: ресторан принял\n  ACCEPTED_BY_RESTAURANT --\u003e DELIVERING: курьер забрал\n  DELIVERING --\u003e DELIVERED: вручён\n  DELIVERED --\u003e [*]\n"}]'::jsonb, rubric = '[{"id":"full-states","title":"Полный набор состояний, включая промежуточные и неопределённые (ожидание оплаты, ожидание ресторана, отменён, возврат)","weight":"high","weightValue":null,"focus":"sa","keywords":["awaiting","ожидан","paid","accepted","delivering","delivered","cancelled","refunded","состояни","статус"],"why":"Упрощённый набор состояний («новый/в работе/готово») не отражает реальность и приводит к тем самым инцидентам из условия.","critical":false},{"id":"transition-table","title":"Таблица переходов с событиями, условиями (guards) и побочными эффектами","weight":"high","weightValue":null,"focus":"sa","keywords":["переход","transition","событи","guard","услов","побочн","эффект","таблиц","trigger"],"why":"Диаграмма без условий и эффектов неполна: именно guard-ы определяют, можно ли отменить заказ.","critical":false},{"id":"illegal-transition","title":"Обработка недопустимых переходов: явная политика (игнорировать/ошибка/компенсация), журнал, алерты","weight":"high","weightValue":null,"focus":"arch","keywords":["недопустим","невозмож","невалидн","игнорир","отклон","конфликт","журнал","алерт","не в том состоянии","race","гонк"],"why":"Условие прямо говорит про асинхронные события в неправильном порядке. Ответ «такого не будет» — провал.","critical":false},{"id":"cancel-model","title":"Модель отмены: инициаторы (пользователь/поддержка/система), причины, финансовые последствия, связь с возвратом","weight":"high","weightValue":null,"focus":"sa","keywords":["отмен","cancel","инициатор","причин","удержан","возврат","refund","поддержк","бесплатн"],"why":"Правила бизнеса из условия завязаны на момент отмены и инициатора. Без этого модель не проверяема.","critical":false},{"id":"timeout","title":"Таймауты состояний: ожидание оплаты, ожидание ресторана, «курьер не назначен», что происходит по истечении","weight":"high","weightValue":null,"focus":"arch","keywords":["таймаут","timeout","истеч","ожидан","дедлайн","просроч","expire","через 15 минут"],"why":"Заказ может зависнуть навсегда, если событие не придёт. Таймауты — часть модели состояний, а не отдельная фича.","critical":false},{"id":"history-log","title":"Журнал переходов: состояние, событие, актор, время, причина — как основа разбора инцидентов","weight":"mid","weightValue":null,"focus":"sa","keywords":["журнал","истори","history","лог переходов","актор","кто","audit","таймлайн","поддержк"],"why":"Бизнес требует объяснимости. Журнал переходов — то, что превращает разбор инцидента из расследования в просмотр таймлайна.","critical":false},{"id":"user-visible","title":"Отдельный слой «статус для пользователя»: внутренние состояния маппятся в понятные подписи","weight":"mid","weightValue":null,"focus":"sa","keywords":["пользовател","отобража","маппинг","подпис","экран","видит","user-facing","текст статус"],"why":"Ограничение требует объяснимости для пользователя. Внутренний AWAITING_RESTAURANT_CONFIRMATION не должен попасть в приложение как есть.","critical":false},{"id":"extensibility","title":"Расширяемость: как добавить частичную отмену / предзаказ без переписывания модели","weight":"mid","weightValue":null,"focus":"arch","keywords":["расшир","частичн","предзаказ","верси","эволюц","backward","новое состояние","гибк"],"why":"Условие прямо требует допускать расширение. Модель без запаса на будущее придётся переписывать.","critical":false},{"id":"concurrency","title":"Конкурентные события и атомарность смены состояния (оптимистичная блокировка / версионирование)","weight":"low","weightValue":null,"focus":"arch","keywords":["version","верси","оптимистич","блокиров","атомарн","одновремен","concurren","cas"],"why":"Два события одновременно (оплата отклонена + ресторан принял) без контроля версий дадут неконсистентный статус.","critical":false}]'::jsonb, hints = '["Начните не с диаграммы, а со списка фактов о заказе, которые важны бизнесу: оплачен ли, принял ли ресторан, везёт ли курьер.","Для каждого перехода напишите guard-условие. Если условия нет — переход будет происходить всегда, и это баг.","Что делать с событием «ресторан принял», если заказ уже отменён пользователем? Опишите политику, а не игнорируйте."]'::jsonb, interview_questions = '["Пользователь отменяет заказ в момент, когда ресторан его принимает. Что произойдёт?","Оплата не пришла за 15 минут. В каком состоянии заказ и что видит пользователь?","Курьер вручил заказ, а через час пришла отмена от ресторана. Как система отреагирует?","Как вы храните историю переходов и кто ею пользуется?","Завтра добавляется частичная отмена. Что изменится в модели?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Состояния\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eСостояние\u003c/th\u003e\u003cth\u003eСмысл\u003c/th\u003e\u003cth\u003eПользователь видит\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eDRAFT\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eКорзина оформляется, заказа ещё нет\u003c/td\u003e\u003ctd\u003e«Корзина»\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eAWAITING_PAYMENT\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eЗаказ создан, ждём результат оплаты\u003c/td\u003e\u003ctd\u003e«Ожидаем оплату»\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ePAYMENT_FAILED\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eОплата отклонена, заказ можно повторить\u003c/td\u003e\u003ctd\u003e«Оплата не прошла»\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ePAID\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eДеньги получены, ждём принятия рестораном\u003c/td\u003e\u003ctd\u003e«Передаём в ресторан»\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eACCEPTED\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eРесторан принял, готовит\u003c/td\u003e\u003ctd\u003e«Готовится»\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eCOURIER_ASSIGNED\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eКурьер назначен, едет в ресторан\u003c/td\u003e\u003ctd\u003e«Курьер в пути»\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eDELIVERING\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eКурьер забрал заказ, везёт\u003c/td\u003e\u003ctd\u003e«Везём заказ»\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eDELIVERED\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eВручён клиенту (терминальное)\u003c/td\u003e\u003ctd\u003e«Доставлен»\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eCANCELLED\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eОтменён (терминальное), с причиной и инициатором\u003c/td\u003e\u003ctd\u003e«Отменён»\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eREFUND_PENDING / REFUNDED\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eВозврат денег в процессе / выполнен\u003c/td\u003e\u003ctd\u003e«Возвращаем деньги»\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eSTUCK_NEEDS_REVIEW\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eРасхождение событий, заказ в ручном разборе\u003c/td\u003e\u003ctd\u003e«Уточняем детали, скоро ответим»\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003ch3\u003e2. Таблица переходов (фрагмент)\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eИз\u003c/th\u003e\u003cth\u003eСобытие\u003c/th\u003e\u003cth\u003eУсловие (guard)\u003c/th\u003e\u003cth\u003eВ\u003c/th\u003e\u003cth\u003eПобочные эффекты\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eDRAFT\u003c/td\u003e\u003ctd\u003echeckout.submitted\u003c/td\u003e\u003ctd\u003eкорзина валидна, адрес в зоне доставки\u003c/td\u003e\u003ctd\u003eAWAITING_PAYMENT\u003c/td\u003e\u003ctd\u003eсоздать платёж, запустить таймаут 15 мин\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eAWAITING_PAYMENT\u003c/td\u003e\u003ctd\u003epayment.succeeded\u003c/td\u003e\u003ctd\u003eсумма совпадает\u003c/td\u003e\u003ctd\u003ePAID\u003c/td\u003e\u003ctd\u003eуведомить ресторан, сбросить таймаут\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eAWAITING_PAYMENT\u003c/td\u003e\u003ctd\u003epayment.failed\u003c/td\u003e\u003ctd\u003e—\u003c/td\u003e\u003ctd\u003ePAYMENT_FAILED\u003c/td\u003e\u003ctd\u003eуведомить пользователя, предложить повтор\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eAWAITING_PAYMENT\u003c/td\u003e\u003ctd\u003etimeout.expired\u003c/td\u003e\u003ctd\u003eоплата не получена\u003c/td\u003e\u003ctd\u003eCANCELLED (reason=PAYMENT_TIMEOUT)\u003c/td\u003e\u003ctd\u003eосвободить позиции меню\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003ePAID\u003c/td\u003e\u003ctd\u003erestaurant.accepted\u003c/td\u003e\u003ctd\u003eзаказ не отменён\u003c/td\u003e\u003ctd\u003eACCEPTED\u003c/td\u003e\u003ctd\u003eзапустить таймаут готовности\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003ePAID\u003c/td\u003e\u003ctd\u003erestaurant.rejected\u003c/td\u003e\u003ctd\u003e—\u003c/td\u003e\u003ctd\u003eCANCELLED (reason=RESTAURANT_REJECTED)\u003c/td\u003e\u003ctd\u003eинициировать возврат\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003ePAID\u003c/td\u003e\u003ctd\u003euser.cancelled\u003c/td\u003e\u003ctd\u003eресторан ещё не принял → бесплатно\u003c/td\u003e\u003ctd\u003eCANCELLED (reason=USER_CANCELLED)\u003c/td\u003e\u003ctd\u003eвозврат 100%\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eACCEPTED\u003c/td\u003e\u003ctd\u003euser.cancelled\u003c/td\u003e\u003ctd\u003eнет → запрет\u003c/td\u003e\u003ctd\u003e— (отклоняем, объясняем)\u003c/td\u003e\u003ctd\u003eпредложить обратиться в поддержку\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eACCEPTED\u003c/td\u003e\u003ctd\u003esupport.cancelled\u003c/td\u003e\u003ctd\u003eрешение поддержки\u003c/td\u003e\u003ctd\u003eCANCELLED (reason=SUPPORT)\u003c/td\u003e\u003ctd\u003eвозврат с удержанием по правилам\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eDELIVERING\u003c/td\u003e\u003ctd\u003eany cancel\u003c/td\u003e\u003ctd\u003eнедопустимо\u003c/td\u003e\u003ctd\u003eDELIVERING\u003c/td\u003e\u003ctd\u003eжурналируем попытку, объясняем пользователю\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eDELIVERING\u003c/td\u003e\u003ctd\u003ecourier.delivered\u003c/td\u003e\u003ctd\u003eподтверждение (код/гео)\u003c/td\u003e\u003ctd\u003eDELIVERED\u003c/td\u003e\u003ctd\u003eзапросить оценку, закрыть платёж\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eCANCELLED\u003c/td\u003e\u003ctd\u003erefund.succeeded\u003c/td\u003e\u003ctd\u003eбыла оплата\u003c/td\u003e\u003ctd\u003eREFUNDED\u003c/td\u003e\u003ctd\u003eуведомить пользователя\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eлюбое\u003c/td\u003e\u003ctd\u003eсобытие пришло в недопустимом состоянии\u003c/td\u003e\u003ctd\u003e—\u003c/td\u003e\u003ctd\u003eтекущее сохраняется\u003c/td\u003e\u003ctd\u003eзапись в журнал + алерт; при повторе — STUCK_NEEDS_REVIEW\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003ch3\u003e3. Недопустимые переходы\u003c/h3\u003e\u003cp\u003eПолитика: \u003cstrong\u003eсобытие не меняет состояние, но не игнорируется молча\u003c/strong\u003e. Каждое такое событие пишется в \u003ccode\u003eorder_state_log\u003c/code\u003e с пометкой \u003ccode\u003eREJECTED_ILLEGAL_TRANSITION\u003c/code\u003e. Классификация:\u003c/p\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eОпоздавший дубль\u003c/strong\u003e (например, \u003ccode\u003epayment.succeeded\u003c/code\u003e после отмены по таймауту) → автоматическая компенсация: инициируем возврат, состояние CANCELLED сохраняется, уведомляем пользователя «оплата прошла после отмены, возвращаем».\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eКонфликт участников\u003c/strong\u003e (ресторан принял + поддержка отменила) → приоритет у отмены (деньги важнее готовки), ресторану уходит команда остановить приготовление, инцидент в разбор.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eНеизвестное событие или неизвестное состояние\u003c/strong\u003e → \u003ccode\u003eSTUCK_NEEDS_REVIEW\u003c/code\u003e, задача в очередь поддержки, пользователь видит нейтральный статус.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e4. Отмены и возвраты\u003c/h3\u003e\u003cp\u003eОтмена — это не состояние «просто отменён», а структура: \u003ccode\u003ecancelledBy\u003c/code\u003e (USER / SUPPORT / SYSTEM / RESTAURANT / COURIER), \u003ccode\u003ecancelReason\u003c/code\u003e (код из справочника), \u003ccode\u003ecancelStage\u003c/code\u003e (на каком этапе), \u003ccode\u003erefundAmount\u003c/code\u003e, \u003ccode\u003erefundPolicy\u003c/code\u003e. Правила:\u003c/p\u003e\u003cul\u003e\u003cli\u003eДо \u003ccode\u003eACCEPTED\u003c/code\u003e — отмена пользователем бесплатна, возврат 100%.\u003c/li\u003e\u003cli\u003eПосле \u003ccode\u003eACCEPTED\u003c/code\u003e до \u003ccode\u003eDELIVERING\u003c/code\u003e — только через поддержку, удержание по правилам (например, стоимость приготовленного блюда), возврат частично.\u003c/li\u003e\u003cli\u003eПосле передачи курьеру — отмена невозможна; доступен возврат после получения по претензии (отдельный процесс, не часть машины состояний заказа).\u003c/li\u003e\u003cli\u003eВозврат только если была успешная оплата; состояние возврата — отдельная подмодель (\u003ccode\u003eREFUND_PENDING → REFUNDED | REFUND_FAILED\u003c/code\u003e), чтобы не смешивать с жизненным циклом доставки.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e5. Таймауты\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003ccode\u003eAWAITING_PAYMENT\u003c/code\u003e: 15 минут → отмена (PAYMENT_TIMEOUT).\u003c/li\u003e\u003cli\u003e\u003ccode\u003ePAID\u003c/code\u003e: 5 минут на принятие рестораном → напоминание, 10 минут → автоотмена с возвратом и предложением другого ресторана.\u003c/li\u003e\u003cli\u003e\u003ccode\u003eACCEPTED\u003c/code\u003e: расчётное время готовки + 15 минут → алерт поддержке, уведомление пользователю с извинением и компенсацией.\u003c/li\u003e\u003cli\u003e\u003ccode\u003eCOURIER_ASSIGNED\u003c/code\u003e: 10 минут без отметки «забрал» → переназначение курьера.\u003c/li\u003e\u003cli\u003e\u003ccode\u003eDELIVERING\u003c/code\u003e: расчётное время доставки + 20 минут → проверка геопозиции, связь с курьером.\u003c/li\u003e\u003cli\u003e\u003ccode\u003eREFUND_PENDING\u003c/code\u003e: 3 рабочих дня → эскалация в финансы.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e6. Атомарность и конкурентность\u003c/h3\u003e\u003cp\u003eСмена состояния — одна транзакция: проверка текущего состояния и guard-ов, обновление с \u003ccode\u003eWHERE status = :expected AND version = :expectedVersion\u003c/code\u003e, запись в журнал переходов, публикация события в outbox. При конфликте версий — перечитываем состояние и пересчитываем guard-ы (оптимистичная блокировка). Это исключает «отменён, но курьер везёт»: второй переход просто не пройдёт по версии.\u003c/p\u003e\u003ch3\u003e7. Журнал переходов\u003c/h3\u003e\u003cp\u003e\u003ccode\u003eorder_state_log\u003c/code\u003e: \u003ccode\u003eorderId, fromState, toState, event, actor (userId/supportId/system), reason, occurredAt, receivedAt, traceId, meta\u003c/code\u003e. Отдельно фиксируем отклонённые события. Экран поддержки — таймлайн заказа: все переходы, события участников, таймауты, суммы возвратов. Это закрывает требование «30–40 инцидентов в неделю разбираем вручную».\u003c/p\u003e\u003ch3\u003e8. Расширяемость\u003c/h3\u003e\u003cul\u003e\u003cli\u003eЧастичная отмена: добавляем подмодель «позиции заказа» со своими состояниями (позиция отменена/возвращена), состояние заказа становится агрегированным (PARTIALLY_CANCELLED). Модель переходов не переписывается — расширяется.\u003c/li\u003e\u003cli\u003eПредзаказ: новое событие \u003ccode\u003escheduled.at\u003c/code\u003e и состояние \u003ccode\u003eSCHEDULED\u003c/code\u003e между \u003ccode\u003ePAID\u003c/code\u003e и \u003ccode\u003eACCEPTED\u003c/code\u003e; таймауты считаются от назначенного времени.\u003c/li\u003e\u003cli\u003eВсе изменения — через версионирование модели: \u003ccode\u003estateModelVersion\u003c/code\u003e в заказе, чтобы старые заказы разбирались по своим правилам.\u003c/li\u003e\u003c/ul\u003e","mermaid":"stateDiagram-v2\n  [*] --\u003e DRAFT\n  DRAFT --\u003e AWAITING_PAYMENT: checkout.submitted\n  AWAITING_PAYMENT --\u003e PAID: payment.succeeded\n  AWAITING_PAYMENT --\u003e PAYMENT_FAILED: payment.failed\n  AWAITING_PAYMENT --\u003e CANCELLED: timeout 15 мин\n  PAYMENT_FAILED --\u003e AWAITING_PAYMENT: повтор оплаты\n  PAYMENT_FAILED --\u003e CANCELLED: пользователь ушёл\n  PAID --\u003e ACCEPTED: restaurant.accepted\n  PAID --\u003e CANCELLED: restaurant.rejected / user.cancelled (100% возврат)\n  PAID --\u003e CANCELLED: timeout 10 мин\n  ACCEPTED --\u003e COURIER_ASSIGNED: courier.assigned\n  ACCEPTED --\u003e CANCELLED: support.cancelled (удержание)\n  COURIER_ASSIGNED --\u003e DELIVERING: courier.picked_up\n  COURIER_ASSIGNED --\u003e ACCEPTED: курьер не назначен, переназначение\n  DELIVERING --\u003e DELIVERED: courier.delivered\n  DELIVERED --\u003e [*]\n  CANCELLED --\u003e REFUND_PENDING: была оплата\n  REFUND_PENDING --\u003e REFUNDED: refund.succeeded\n  REFUND_PENDING --\u003e STUCK_NEEDS_REVIEW: refund.failed\n  STUCK_NEEDS_REVIEW --\u003e CANCELLED: решение поддержки\n  STUCK_NEEDS_REVIEW --\u003e DELIVERED: расхождение снято\n  REFUNDED --\u003e [*]\n"}'::jsonb, updated_at = now() WHERE id = 'des-order-state';
UPDATE tasks SET statement = '{"brief":"Уведомления шлёт каждый сервис сам. Нужен единый сервис: каналы, предпочтения, лимиты, дедупликация и отчётность.","context":["В продукте 11 сервисов шлют письма и push напрямую через свои интеграции с провайдерами. Результат: пользователь получает по 6 писем в день, шаблоны отличаются, отписка работает только в части писем, доставляемость падает, никто не знает, сколько уведомлений отправлено.","Бизнес хочет единый сервис уведомлений: каналы email / push / SMS / in-app, управление предпочтениями пользователя, тихие часы, лимиты, дедупликация, единые шаблоны и аналитика по доставке.","Нагрузка: 3 млн уведомлений в сутки, пики до 400 в секунду (например, массовая рассылка статуса заказа после сбоя). Провайдеры платные: SMS стоит дорого, его надо использовать только когда действительно нужно."],"goal":"Спроектировать сервис уведомлений: архитектура, контракт для сервисов-отправителей, правила приоритизации и дедупликации, управление предпочтениями, надёжность и аналитика.","inputs":["Каналы: email (провайдер с API), push (Firebase/APNs), SMS (агрегатор, дорого), in-app (свои веб и мобайл).","Источники: транзакционные уведомления (статус заказа, оплата) и маркетинговые (акции).","Пользователь может отписаться от маркетинга, но не от транзакционных уведомлений.","Требование юридической безопасности: уведомления о платежах и изменениях условий должны доставляться обязательно."],"deliverables":["Архитектура сервиса: компоненты, взаимодействие с отправителями и провайдерами, хранение.","Контракт запроса на отправку (API или событие): обязательные поля, шаблон, параметры, приоритет, идемпотентность.","Правила: приоритеты уведомлений, дедупликация, тихие часы, частотные лимиты, выбор канала и fallback.","Модель предпочтений пользователя и центры управления подписками (включая требование «нельзя отписаться от транзакционных»).","Надёжность: ретраи провайдеров, очереди, приоритизация, поведение при недоступности канала, гарантия «не потерять» транзакционное уведомление.","Аналитика и эксплуатация: метрики доставки, чтение, отписки, разбор «пользователь говорит, что не получил».","Как мигрировать 11 сервисов на новый сервис уведомлений."],"constraints":["Сервисы-отправители не должны знать про провайдеров и логику каналов.","Транзакционное уведомление о платеже должно уйти даже если email-провайдер недоступен.","Стоимость SMS ограничена бюджетом: нужен контроль и приоритизация."],"interview":"«Спроектируйте сервис уведомлений. Как не заспамить пользователя и при этом гарантированно доставить уведомление о платеже?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Проект сервиса","content":"\u003ch3\u003eАрхитектура\u003c/h3\u003e\u003ch3\u003eКонтракт отправки\u003c/h3\u003e\u003ch3\u003eПравила и приоритеты\u003c/h3\u003e\u003ch3\u003eПредпочтения\u003c/h3\u003e\u003ch3\u003eМетрики\u003c/h3\u003e"},{"type":"mermaid","title":"Компоненты","content":"flowchart LR\n  S1[Сервис заказов] --\u003e Q[Очередь уведомлений]\n  S2[Сервис платежей] --\u003e Q\n  Q --\u003e R[Правила и приоритизация]\n  R --\u003e E[Email провайдер]\n  R --\u003e P[Push]\n  R --\u003e SM[SMS агрегатор]\n  R --\u003e IA[In-app]\n"}]'::jsonb, rubric = '[{"id":"single-entry","title":"Единая точка входа: контракт отправки (событие/API), отправители не знают провайдеров, шаблонизация на стороне сервиса","weight":"high","weightValue":null,"focus":"arch","keywords":["единый","контракт","шаблон","template","api","событи","отправител","абстракц","не знают провайдер"],"why":"Главная боль из условия — 11 сервисов со своими интеграциями. Без единого контракта сервис не решает задачу.","critical":false},{"id":"priority","title":"Приоритеты и классы уведомлений: транзакционные/критические выше маркетинга, отдельные очереди","weight":"high","weightValue":null,"focus":"sa","keywords":["приоритет","priority","транзакц","критич","маркетинг","очередь","queue","класс","critical"],"why":"Без приоритетов массовая рассылка задавит уведомление о платеже. Требование бизнеса прямо об этом.","critical":false},{"id":"dedup","title":"Дедупликация: ключ dedup, окно времени, склейка однотипных уведомлений (digest)","weight":"high","weightValue":null,"focus":"arch","keywords":["дедупл","dedup","дубл","ключ","digest","склейк","группиров","окно","unique"],"why":"Повторные события (ретраи, дубли из Kafka) без дедупликации = спам. Плюс digest решает проблему «6 писем в день».","critical":false},{"id":"preferences","title":"Модель предпочтений: каналы, темы, тихие часы, обязательные категории, отписка с юридическими ограничениями","weight":"high","weightValue":null,"focus":"sa","keywords":["предпочтен","prefer","подписк","отписк","тихи","quiet hours","канал","темы","обязательн","opt-out","opt-in"],"why":"Условие требует: от маркетинга отписаться можно, от транзакционных — нет. Это надо выразить в модели данных.","critical":false},{"id":"fallback","title":"Выбор канала и fallback-цепочка: email → push → SMS с условиями и бюджетом","weight":"high","weightValue":null,"focus":"arch","keywords":["fallback","канал","email","push","sms","in-app","цепочк","переключ","если не доставлен","budget","бюджет"],"why":"Гарантия доставки платежа при недоступном email-провайдере решается именно цепочкой каналов, а не ретраями одного.","critical":false},{"id":"reliability","title":"Надёжность: очереди с ретраями, outbox у отправителя, хранение отложенных, таймауты, DLQ, лимиты провайдеров","weight":"mid","weightValue":null,"focus":"arch","keywords":["очеред","ретра","backoff","dlq","outbox","гарант","не потеря","лимит провайд","circuit","буфер"],"why":"400 уведомлений в секунду и платные провайдеры с лимитами — без очередей и ретраев будут потери.","critical":false},{"id":"rate-limit-user","title":"Частотные лимиты на пользователя: максимум N уведомлений в час/сутки, защита от спама, исключение для критических","weight":"mid","weightValue":null,"focus":"sa","keywords":["лимит","rate limit","не более","в сутки","в час","спам","частот","throttle","quota"],"why":"Бизнес-цель «не заспамить» требует измеримого правила, а не надежды на здравый смысл отправителей.","critical":false},{"id":"analytics","title":"Аналитика и эксплуатация: метрики отправки/доставки/чтения/отписок, статус по каждому уведомлению, экран разбора","weight":"mid","weightValue":null,"focus":"sa","keywords":["метрик","доставлен","delivery","open rate","читаем","отписк","аналитик","dash","статус","разбор","webhook провайд"],"why":"«Никто не знает, сколько отправлено» — одна из болей. Без статуса каждого уведомления поддержка не ответит на жалобу.","critical":false},{"id":"templates","title":"Шаблоны и локализация: версионирование, превью, согласование, единый бренд-вид, параметры","weight":"mid","weightValue":null,"focus":"sa","keywords":["шаблон","template","верси","локал","перевод","согласов","бренд","параметр","переменн","preview"],"why":"«Шаблоны отличаются» — прямая жалоба из условия. Управление шаблонами = отдельная подсистема.","critical":false},{"id":"migration","title":"План миграции 11 сервисов: приоритизация, параллельная работа, обратная совместимость, критерии перевода","weight":"mid","weightValue":null,"focus":"sa","keywords":["миграц","перевод","этап","пилот","совместим","deprecat","план","сервис за сервисом","критер"],"why":"Спроектировать сервис мало: 11 команд должны на него перейти. План миграции — часть ответа аналитика.","critical":false},{"id":"legal","title":"Юридические аспекты: согласие на маркетинг, обязательность уведомлений о платежах, хранение доказательств доставки","weight":"low","weightValue":null,"focus":"sa","keywords":["соглас","consent","закон","юридич","доказательств","хранен","требован","152","рассылк"],"why":"Транзакционные уведомления — юридически значимые. Нужны основания и доказательства доставки.","critical":false}]'::jsonb, hints = '["Разделите два потока: транзакционные (гарантированные, приоритетные) и маркетинговые (можно задержать, склеить, отменить).","Дедупликация требует ключа. Кто его генерирует — отправитель или сервис уведомлений?","Fallback на SMS стоит денег. Какое условие должно выполниться, чтобы мы решились на SMS?"]'::jsonb, interview_questions = '["Пользователь отписался от всего. Придёт ли ему уведомление о списании денег?","Email-провайдер лежит 2 часа. Что произойдёт с транзакционными уведомлениями?","Как вы склеите 5 уведомлений об изменении статуса одного заказа?","Сервис заказов отправил одно и то же событие дважды. Сколько писем получит пользователь?","Как измерить, что сервис уведомлений работает хорошо?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Архитектура\u003c/h3\u003e\u003cp\u003eКомпоненты:\u003c/p\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eNotification Ingress API\u003c/strong\u003e — HTTP/gRPC + событийный вход (топик \u003ccode\u003enotifications.requested\u003c/code\u003e). Принимает запросы, валидирует схему, присваивает \u003ccode\u003enotificationId\u003c/code\u003e, идемпотентен по \u003ccode\u003ededupKey\u003c/code\u003e.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003ePolicy Engine\u003c/strong\u003e — применяет правила: предпочтения, тихие часы, лимиты, приоритеты, дедупликация, выбор канала. Здесь же решение «отправить / склеить в digest / отложить / отклонить».\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eTemplate Service\u003c/strong\u003e — шаблоны с версиями, параметрами, локализацией, превью и согласованием. Рендеринг отдельно от правил.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eChannel Workers\u003c/strong\u003e — по воркеру на канал (email/push/SMS/in-app) со своими очередями, ретраями и лимитами провайдера.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eProvider Adapters\u003c/strong\u003e — адаптеры провайдеров с circuit breaker и метриками; смена провайдера не затрагивает логику.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eDelivery Tracker\u003c/strong\u003e — принимает webhook-и провайдеров (sent/delivered/opened/failed/bounced), ведёт статус каждого уведомления.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003ePreferences Service\u003c/strong\u003e — подписки пользователя по темам и каналам, согласия, quiet hours.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eStorage\u003c/strong\u003e: PostgreSQL (запросы, статусы, предпочтения, шаблоны), Redis (лимиты, дедуп-окна, кэш предпочтений), объектное хранилище (архив рендеров для разборов).\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e2. Контракт отправки\u003c/h3\u003e\u003cpre\u003e\u003ccode\u003ePOST /v1/notifications\n{\n  \"dedupKey\": \"order-8842-status-DELIVERING\",   // обязательный, генерирует отправитель\n  \"userId\": \"u-123\",\n  \"category\": \"TRANSACTIONAL\",                   // TRANSACTIONAL | SECURITY | MARKETING | DIGEST\n  \"templateCode\": \"order_status_v3\",\n  \"params\": { \"orderNumber\": \"8842\", \"status\": \"В пути\", \"eta\": \"18:40\" },\n  \"priority\": \"HIGH\",                            // CRITICAL | HIGH | NORMAL | LOW\n  \"preferredChannels\": [\"push\", \"email\"],        // необязательно, иначе — по политике\n  \"locale\": \"ru-RU\",\n  \"scheduledAt\": null,                           // отложенная отправка\n  \"expiresAt\": \"2026-10-05T19:30:00Z\",           // позже этого не отправляем\n  \"source\": { \"service\": \"orders\", \"traceId\": \"...\" }\n}\u003c/code\u003e\u003c/pre\u003e\u003cp\u003eОтвет \u003ccode\u003e202 Accepted\u003c/code\u003e + \u003ccode\u003enotificationId\u003c/code\u003e. Повтор с тем же \u003ccode\u003ededupKey\u003c/code\u003e возвращает тот же \u003ccode\u003enotificationId\u003c/code\u003e и не создаёт новую отправку. Отправитель не знает ни провайдеров, ни каналов — только категорию, шаблон и приоритет.\u003c/p\u003e\u003ch3\u003e3. Правила\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eПриоритеты и очереди:\u003c/strong\u003e отдельные очереди на CRITICAL/HIGH (транзакционные, безопасность) и NORMAL/LOW (маркетинг). Маркетинг троттлится и может откладываться; транзакционные проходят всегда. Ресурсы провайдеров квотируются: 70% ёмкости зарезервировано за CRITICAL/HIGH.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eДедупликация:\u003c/strong\u003e точный дубль по \u003ccode\u003ededupKey\u003c/code\u003e (TTL 24 часа в Redis + unique в БД). Событийная склейка: одинаковые \u003ccode\u003etemplateCode + userId + entityId\u003c/code\u003e в окне 10 минут → одна отправка с последним значением параметров. Digest: LOW/MARKETING по одному пользователю накапливаются и уходят пачкой раз в сутки в 10:00 (если не в тихих часах).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eТихие часы:\u003c/strong\u003e по умолчанию 22:00–08:00 в таймзоне пользователя; CRITICAL и SECURITY игнорируют тихие часы, HIGH — отправляются, но без звука/вибро (push с \u003ccode\u003einterruption-level: passive\u003c/code\u003e), NORMAL/LOW — откладываются до утра. SMS в тихие часы — только CRITICAL.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЧастотные лимиты:\u003c/strong\u003e MARKETING ≤ 1 в сутки и ≤ 4 в неделю на пользователя; NORMAL ≤ 6 в сутки; TRANSACTIONAL/SECURITY без лимита. Превышение → отклонение с кодом \u003ccode\u003esuppressed_rate_limit\u003c/code\u003e и записью в аналитику (отправитель видит причину).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eВыбор канала и fallback:\u003c/strong\u003e политика по категории. TRANSACTIONAL: push → (через 60 сек, если нет delivered/прочтения и есть email) email → (через 10 мин, если статус платежа/безопасности и оба канала не дали delivered) SMS. SMS включается только для CRITICAL и только если предыдущие каналы не подтвердили доставку в пределах SLA — это держит бюджет. MARKETING: только каналы, на которые пользователь подписан, без SMS. in-app — всегда как дополнительный канал (не требует доставки).\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e4. Предпочтения\u003c/h3\u003e\u003cp\u003eМодель: \u003ccode\u003euser_preferences(userId, topic, channel, enabled)\u003c/code\u003e + \u003ccode\u003etopic.category\u003c/code\u003e. Категории \u003ccode\u003ePAYMENTS\u003c/code\u003e, \u003ccode\u003eSECURITY\u003c/code\u003e, \u003ccode\u003eORDER_STATUS\u003c/code\u003e, \u003ccode\u003eLEGAL\u003c/code\u003e помечены \u003ccode\u003emandatory = true\u003c/code\u003e: тумблер в UI неактивен с подписью «Эти уведомления обязательны и связаны с вашими операциями». Маркетинговые темы — opt-out в один клик, ссылка отписки в каждом письме (требование законодательства о рассылках), состояние согласия с датой и источником хранится как доказательство. Центр управления подписками — единая страница + in-app экран; изменение применяется в течение 60 секунд (инвалидация кэша).\u003c/p\u003e\u003ch3\u003e5. Надёжность\u003c/h3\u003e\u003cul\u003e\u003cli\u003eОтправитель публикует событие через outbox → мы не теряем запрос, если отправитель упал после коммита.\u003c/li\u003e\u003cli\u003eВсе очереди с at-least-once + идемпотентная обработка по \u003ccode\u003enotificationId\u003c/code\u003e (таблица \u003ccode\u003eprocessed_notifications\u003c/code\u003e).\u003c/li\u003e\u003cli\u003eРетраи провайдера: 5 попыток с backoff 5/30/120/600/1800 сек для временных ошибок; постоянные ошибки (bounce, невалидный адрес) — без ретраев, помечаем канал недоступным для пользователя и идём по fallback.\u003c/li\u003e\u003cli\u003eCircuit breaker на провайдера: при 30% ошибок — open, трафик уходит на резервного провайдера (для email два поставщика), событие в мониторинг.\u003c/li\u003e\u003cli\u003eОтложенные и накопленные в digest уведомления хранятся в БД с \u003ccode\u003eexpiresAt\u003c/code\u003e: просроченные не отправляем (устаревшая информация хуже, чем её отсутствие), пишем \u003ccode\u003esuppressed_expired\u003c/code\u003e.\u003c/li\u003e\u003cli\u003eПолная потеря канала (провайдер лежит сутки): транзакционные накапливаются в очереди с приоритетом, по восстановлении отправляются только не истёкшие; пользователь видит статус в приложении (in-app не зависит от внешних провайдеров).\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e6. Аналитика и эксплуатация\u003c/h3\u003e\u003cul\u003e\u003cli\u003eМетрики: количество запросов по категориям и сервисам-отправителям, подавленные (с причиной: дедуп, лимит, отписка, тихие часы, истёк), отправлено по каналам, delivered / failed / bounced / opened / clicked, p95 задержки от запроса до доставки, стоимость по каналам (особенно SMS), число отписок.\u003c/li\u003e\u003cli\u003eСтатус каждого уведомления — запись с полной цепочкой: запрошено → политика (решение) → шаблон/версия → канал → попытки → статус провайдера → прочтение. Хранение 90 дней горячо, 2 года архив.\u003c/li\u003e\u003cli\u003eЭкран разбора для поддержки: по userId или notificationId видно, почему уведомление не ушло (например, «подавлено: пользователь отписан от темы» или «email провайдера вернул hard bounce, SMS не применялся — категория MARKETING»). Это закрывает 90% обращений «я не получил».\u003c/li\u003e\u003cli\u003eАлерты: доля failed \u0026gt; 2% за 15 минут; очередь CRITICAL \u0026gt; 1000 или задержка \u0026gt; 60 сек; рост подавлений по лимиту \u0026gt; 20% (признак бага у отправителя); исчерпание SMS-бюджета на 80%.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e7. Шаблоны\u003c/h3\u003e\u003cp\u003eШаблон — сущность с кодом, версией, каналами (для каждого канала свой вариант: тема письма, заголовок push, текст SMS с учётом лимита символов), параметрами со схемой и валидацией, локализациями. Версионирование: отправитель ссылается на \u003ccode\u003etemplateCode\u003c/code\u003e, активная версия выбирается сервисом; старая версия хранится, чтобы в разборе было видно, какой именно текст ушёл. Изменение шаблона — через ревью (превью + тестовая отправка), для юридических текстов — обязательное согласование.\u003c/p\u003e\u003ch3\u003e8. Миграция 11 сервисов\u003c/h3\u003e\u003col\u003e\u003cli\u003e\u003cstrong\u003eЭтап 0:\u003c/strong\u003e аудит текущих отправок (какие письма реально шлём, частоты, шаблоны), инвентаризация тем и категорий, согласование модели предпочтений, запуск сервиса на in-app + email с одним пилотным сервисом.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЭтап 1:\u003c/strong\u003e пилот — сервис заказов (самый частотный), shadow-режим: шлём через новый сервис, но старая отправка ещё активна; сверяем объёмы и содержание; затем переключаем и глушим старую.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЭтап 2:\u003c/strong\u003e перевод остальных сервисов волнами по 2–3, в порядке убывания трафика. Каждому сервису — гайд, SDK-обёртка и чек-лист (dedupKey, категория, шаблоны).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЭтап 3:\u003c/strong\u003e отключение прямых интеграций с провайдерами, изъятие секретов провайдеров у сервисов, депrecation-период и контроль: алерт на любой прямой вызов провайдера мимо сервиса уведомлений.\u003c/li\u003e\u003c/ol\u003e\u003cp\u003eКритерии перевода этапа: 0 расхождений сверки за 5 дней, p95 задержки в норме, нет роста жалоб.\u003c/p\u003e","mermaid":"flowchart LR\n  subgraph Sources[\"Сервисы-отправители\"]\n    S1[Заказы]\n    S2[Платежи]\n    S3[Маркетинг]\n    S4[Безопасность]\n  end\n  S1 --\u003e|outbox / API + dedupKey| ING[Notification Ingress]\n  S2 --\u003e ING\n  S3 --\u003e ING\n  S4 --\u003e ING\n  ING --\u003e PQ{Очередь по приоритету}\n  PQ --\u003e|CRITICAL/HIGH| PE[Policy Engine]\n  PQ --\u003e|NORMAL/LOW| DIG[Digest и отложенные]\n  DIG --\u003e PE\n  PREF[Preferences] --\u003e PE\n  LIM[Лимиты и тихие часы] --\u003e PE\n  PE --\u003e|пропущено| TPL[Template Service]\n  PE --\u003e|подавлено| SUP[Журнал подавлений]\n  TPL --\u003e CH{Канал}\n  CH --\u003e EW[Email worker]\n  CH --\u003e PW[Push worker]\n  CH --\u003e SW[SMS worker]\n  CH --\u003e IW[In-app]\n  EW --\u003e PA1[Провайдер email A]\n  EW -.fallback.-\u003e PA2[Провайдер email B]\n  PW --\u003e FB[Firebase / APNs]\n  SW --\u003e AGG[SMS агрегатор]\n  PA1 --\u003e|webhook| TR[Delivery Tracker]\n  PA2 --\u003e TR\n  FB --\u003e TR\n  AGG --\u003e TR\n  TR --\u003e AN[Аналитика и экран разбора]\n  TR -.не доставлено.-\u003e PE\n"}'::jsonb, updated_at = now() WHERE id = 'des-notifications';
UPDATE tasks SET statement = '{"brief":"Баллы начисляются и списываются в 400 магазинах и онлайн. Нужна система, которая не потеряет и не задвоит баллы.","context":["Федеральная розничная сеть: 400 офлайн-магазинов (кассы, часть работает офлайн при проблемах со связью), интернет-магазин, мобильное приложение. Запускают программу лояльности: начисление баллов за покупки (процент зависит от уровня участника и категории товара), списание баллов при оплате (не более 30% суммы чека), сгорание баллов через 12 месяцев.","Баллы — это почти деньги: бухгалтерия требует точного учёта, маркетинг — гибких правил акций, ИТ — интеграции с кассами и платёжным сервисом.","Ожидаемая нагрузка: 2 млн чеков в сутки, пик в чёрную пятницу ×4. Касса в магазине не должна ждать ответа сервиса лояльности дольше 2 секунд, иначе очередь."],"goal":"Спроектировать систему лояльности: доменная модель, правила начисления/списания, работа с офлайн-кассами, согласованность balances, интеграции, эксплуатация и метрики.","inputs":["Участники: физлица с картой (пластик или QR в приложении), уровни (Base / Silver / Gold) с разными процентами начисления.","Правила: базовый процент 3%, Silver 5%, Gold 7%; на акционные товары — 0% или повышенный процент; списание до 30% суммы чека, шаг 1 балл = 1 рубль.","Баллы сгорают через 12 месяцев партиями (FIFO по дате начисления).","Возврат товара: баллы, начисленные за покупку, должны быть сторнированы; если они уже потрачены — возникает отрицательный баланс или долг.","Кассы в 60 магазинах периодически теряют связь на 15–60 минут."],"deliverables":["Доменная модель: сущности, агрегаты, границы контекстов, ключевые операции.","Алгоритм начисления и списания с учётом правил, уровней, акционных товаров и лимита 30%.","Работа с офлайн-кассами: что происходит на кассе без связи, как синхронизируемся, какие риски и как их ограничиваем.","Согласованность баланса: как гарантировать, что баллы не задвоятся и не потеряются при ретраях и сбоях.","Сгорание баллов: механизм, как показываем пользователю, спорные случаи.","Возвраты и сторно: алгоритм, включая случай «баллы уже потрачены».","Интеграции: касса, платёжный сервис, мобильное приложение, CRM/маркетинг, бухгалтерия.","Наблюдаемость, метрики программы и эксплуатация: разбор инцидентов, аудит, отчётность.","План запуска: пилот, масштабирование, откат."],"constraints":["Ответ кассе — не более 2 секунд, иначе растёт очередь.","Бухгалтерия требует полную аудируемость каждой операции с баллами (кто, когда, на основании чего).","Правила акций меняются часто и без релизов: маркетинг настраивает их сам.","Нельзя задвоить баллы: это прямые убытки."],"interview":"«Спроектируйте систему лояльности для сети с офлайн-магазинами. Как вы решите проблему кассы без связи и как гарантируете, что баллы не задвоятся?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Проектирование системы","content":"\u003ch3\u003eДоменная модель\u003c/h3\u003e\u003ch3\u003eНачисление и списание\u003c/h3\u003e\u003ch3\u003eОфлайн-кассы\u003c/h3\u003e\u003ch3\u003eСогласованность и аудит\u003c/h3\u003e\u003ch3\u003eСгорание и возвраты\u003c/h3\u003e"},{"type":"mermaid","title":"Контексты","content":"flowchart TD\n  POS[Кассы магазинов] --\u003e LOY[Сервис лояльности]\n  WEB[Интернет-магазин] --\u003e LOY\n  APP[Мобильное приложение] --\u003e LOY\n  LOY --\u003e PAY[Платёжный сервис]\n  LOY --\u003e ACC[Бухгалтерия]\n  MKT[Маркетинг: правила акций] --\u003e LOY\n"}]'::jsonb, rubric = '[{"id":"domain-model","title":"Доменная модель: участник, счёт баллов, партии начислений, транзакции, правила; границы агрегатов","weight":"high","weightValue":null,"focus":"sa","keywords":["участник","счёт","баланс","парти","лот","транзакц","агрегат","домен","сущност","начислен","списан"],"why":"Без понятия «партия начисления» невозможно реализовать сгорание FIFO и сторно при возврате.","critical":false},{"id":"double-spend","title":"Защита от задвоения: идемпотентность по номеру чека, уникальность операций, атомарность списания","weight":"high","weightValue":null,"focus":"arch","keywords":["идемпотент","дубл","задво","unique","номер чека","receipt","транзакц","блокиров","оптимистич","version"],"why":"Прямое ограничение задачи: задвоение = убытки. Ретраи кассы и офлайн-синхронизация гарантированно создадут дубли.","critical":false},{"id":"offline-pos","title":"Офлайн-кассы: локальный режим, валидация баланса на устройстве, лимиты риска, синхронизация и разрешение конфликтов","weight":"high","weightValue":null,"focus":"arch","keywords":["офлайн","offline","касс","локальн","синхрониз","конфликт","буфер","отложен","без связи","лимит риск"],"why":"60 магазинов теряют связь — это центральный кейс задачи. Ответ «касса подождёт» противоречит ограничению в 2 секунды.","critical":false},{"id":"accrual-rules","title":"Расчёт начисления: уровень участника, акционные товары, округления, исключения; правила настраиваются без релиза","weight":"high","weightValue":null,"focus":"sa","keywords":["процент","уровн","silver","gold","акцион","исключен","округлен","правил","движок","конфигур","без релиз"],"why":"Маркетинг меняет акции часто: если правила зашиты в код, каждая акция — это релиз и очередь багов.","critical":false},{"id":"redemption-limit","title":"Списание: проверка лимита 30% от суммы чека, доступного баланса, блокировка/резервирование на время оплаты","weight":"high","weightValue":null,"focus":"sa","keywords":["30%","лимит","списан","резерв","блокиров","доступн","остаток","чек","шаг"],"why":"Лимит и резервирование — то место, где рождаются расхождения: баллы списали, а оплата не прошла.","critical":false},{"id":"burn-fifo","title":"Сгорание баллов: FIFO по партиям, расписание, уведомление пользователя, спорные случаи (сгорело во время оформления)","weight":"mid","weightValue":null,"focus":"sa","keywords":["сгоран","fifo","12 месяц","парти","расписан","уведомл","истеч","expire","batch"],"why":"Сгорание по партиям — требование условия. Плюс это источник клиентских жалоб, которые надо спроектировать заранее.","critical":false},{"id":"returns","title":"Возвраты и сторно: откат начисления, случай «баллы потрачены», отрицательный баланс или долг, правила для бизнеса","weight":"high","weightValue":null,"focus":"sa","keywords":["возврат","сторно","отмен","потрачен","отрицательн","долг","reversal","чек возврат","компенсац"],"why":"Самый болезненный кейс программы лояльности. Без явного правила бизнес получит неконтролируемые убытки или скандалы.","critical":false},{"id":"consistency","title":"Согласованность с оплатой: сага/резерв между лояльностью и платёжным сервисом, что если оплата не прошла после списания","weight":"high","weightValue":null,"focus":"arch","keywords":["саг","saga","резерв","двухфаз","компенсац","оплат","платёжн","расхожден","откат","two-phase"],"why":"Списание баллов и списание денег — две разные системы. Без согласования получаем «баллы списаны, чек не оплачен».","critical":false},{"id":"audit","title":"Аудит и бухгалтерия: журнал операций (двойная запись), неизменяемость, отчётность, сверка","weight":"mid","weightValue":null,"focus":"sa","keywords":["аудит","журнал","бухгалтер","двойн","immutable","неизмен","отчёт","сверк","проводк","ledger"],"why":"Ограничение требует полной аудируемости. Журнал «обновили баланс» не проходит как финансовый учёт.","critical":false},{"id":"perf","title":"Производительность: 2 млн чеков в сутки, ×4 в пик, ответ кассе ≤ 2 сек, кэш правил и баланса","weight":"mid","weightValue":null,"focus":"arch","keywords":["2 млн","нагрузк","пик","кэш","производительн","2 секунд","пропускн","шард","партицион"],"why":"Числа в условии даны не просто так: надо показать, что архитектура выдержит чёрную пятницу.","critical":false},{"id":"anti-fraud","title":"Антифрод: аномалии начисления, лимиты на участника, подозрительные операции, ручные начисления под контролем","weight":"mid","weightValue":null,"focus":"sa","keywords":["фрод","fraud","злоупотреб","аномал","лимит","подозрит","ручн","злоумышл","контроль"],"why":"Баллы = деньги. Программы лояльности атакуют: накрутки, сговор кассиров, баги округления.","critical":false},{"id":"rollout","title":"План запуска: пилот на части магазинов, критерии, откат, обучение кассиров, поддержка","weight":"low","weightValue":null,"focus":"sa","keywords":["пилот","запуск","этап","откат","обучен","кассир","поддержк","масштаб","rollout"],"why":"400 магазинов нельзя включить одной кнопкой. План внедрения — часть проектного ответа.","critical":false}]'::jsonb, hints = '["Начните с того, что такое «баланс». Одно число или набор партий с датами? От этого зависит всё остальное.","Офлайн-касса: можно ли разрешить списание без связи? Если да — какой суммой рискуем и как ограничиваем?","Возврат товара, баллы за который уже потрачены. Три варианта: минус на балансе, долг участника, отказать в возврате баллов. Какой выберете и почему?"]'::jsonb, interview_questions = '["Касса без связи 40 минут, покупатель хочет оплатить баллами. Что произойдёт?","Как вы гарантируете, что повторная отправка чека не начислит баллы дважды?","Клиент вернул товар, баллы за который уже потратил. Ваши действия?","Баллы сгорают в момент, когда клиент оформляет заказ. Что увидит клиент?","Оплата не прошла после списания баллов. Как система придёт в согласованное состояние?","Как бухгалтерия сверит баллы с финансовой отчётностью?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Границы контекстов\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eLoyalty (ядро):\u003c/strong\u003e участники, счета, партии баллов, правила начисления/списания, операции (ledger), сгорание, сторно.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eLoyalty Rules (маркетинг):\u003c/strong\u003e справочник акций и правил, версионирование, период действия, аудит изменений. Отдельный контекст, потому что меняется часто и другими людьми.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003ePOS Integration:\u003c/strong\u003e контракт с кассой, офлайн-режим, синхронизация, очередь чеков.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003ePayments:\u003c/strong\u003e согласование списания баллов и оплаты чека (сага).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eCustomer Facing:\u003c/strong\u003e приложение/сайт — баланс, история, «сколько сгорит», статус уровня.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eFinance/BI:\u003c/strong\u003e учёт обязательств по баллам, отчётность, сверка, резервы.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e2. Доменная модель\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eСущность\u003c/th\u003e\u003cth\u003eСодержимое\u003c/th\u003e\u003cth\u003eКомментарий\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eMember\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, phone/card/QR-id, tier (Base/Silver/Gold), tierValidUntil, consent, createdAt\u003c/td\u003e\u003ctd\u003eАгрегат «участник»; уровень пересчитывается по правилам (сумма покупок за 12 мес)\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ePointsAccount\u003c/code\u003e\u003c/td\u003e\u003ctd\u003ememberId, availableBalance, reservedBalance, currency=POINTS\u003c/td\u003e\u003ctd\u003eБаланс — производная величина от партий; хранится для скорости чтения\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ePointsBatch\u003c/code\u003e (партия/лот)\u003c/td\u003e\u003ctd\u003eid, memberId, amount, remainingAmount, earnedAt, expiresAt, sourceOperationId, ruleVersion\u003c/td\u003e\u003ctd\u003eКлюч к сгоранию FIFO и к сторно при возврате\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eLedgerEntry\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, memberId, type (ACCRUAL/REDEMPTION/REVERSAL/EXPIRE/ADJUSTMENT), amount (+/-), batchId?, operationId, receiptId, occurredAt, actor, reason, ruleVersion\u003c/td\u003e\u003ctd\u003eНеизменяемый журнал; источник истины, баланс пересчитывается из него\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eOperation\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, idempotencyKey (storeId + receiptId + seq), status, sagaState, payload\u003c/td\u003e\u003ctd\u003eИдемпотентность и связь с платёжной сагой\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eRule / Campaign\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, version, period, условия (категории, товары, суммы), процент, исключения, лимиты\u003c/td\u003e\u003ctd\u003eНастраивается маркетингом без релиза, версионируется\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003ch3\u003e3. Начисление\u003c/h3\u003e\u003col\u003e\u003cli\u003eКасса присылает чек: \u003ccode\u003estoreId, receiptId, items[{sku, category, qty, price, promoFlag}], total, memberRef, appliedRedemption\u003c/code\u003e.\u003c/li\u003e\u003cli\u003eПроверяем идемпотентность по \u003ccode\u003estoreId+receiptId\u003c/code\u003e: уже обработан → возвращаем сохранённый результат.\u003c/li\u003e\u003cli\u003eОпределяем активные правила на дату чека (\u003ccode\u003eruleVersion\u003c/code\u003e фиксируется в операции — иначе пересчёт правил задним числом изменит историю).\u003c/li\u003e\u003cli\u003eСчитаем базу начисления: сумма позиций, не исключённых правилами; акционные товары — 0% или повышенный процент по правилу.\u003c/li\u003e\u003cli\u003eПрименяем процент уровня (3/5/7%), округление — вниз до целого балла по позиции, затем суммируем (правило округления фиксируем в спецификации, иначе расхождения с бухгалтерией).\u003c/li\u003e\u003cli\u003eПроверяем антифрод-лимиты (максимум баллов на участника в сутки, аномальные чеки).\u003c/li\u003e\u003cli\u003eПишем \u003ccode\u003eLedgerEntry(ACCRUAL)\u003c/code\u003e + создаём \u003ccode\u003ePointsBatch\u003c/code\u003e с \u003ccode\u003eexpiresAt = earnedAt + 12 мес\u003c/code\u003e, обновляем баланс — всё в одной транзакции.\u003c/li\u003e\u003c/ol\u003e\u003ch3\u003e4. Списание и лимит 30%\u003c/h3\u003e\u003cul\u003e\u003cli\u003eЗапрос списания: \u003ccode\u003ememberRef, amountPoints, receiptId, orderId\u003c/code\u003e. Проверки: доступный баланс ≥ суммы; сумма ≤ 30% от суммы чека (округление вниз до целого рубля); участник активен; нет блокировки (фрод/возвраты).\u003c/li\u003e\u003cli\u003eПри оформлении создаём \u003cstrong\u003eрезервирование\u003c/strong\u003e: \u003ccode\u003ereservedBalance += X\u003c/code\u003e, запись \u003ccode\u003eREDEMPTION_HOLD\u003c/code\u003e с TTL 15 минут. После успеха оплаты — фиксация списания по FIFO-партиям; после отказа/таймаута — освобождение резерва.\u003c/li\u003e\u003cli\u003eСписание по партиям: сначала те, что сгорают раньше (FIFO), фиксируем в \u003ccode\u003eLedgerEntry\u003c/code\u003e связи с \u003ccode\u003ebatchId\u003c/code\u003e — это даёт точный расчёт сгораний и сторно.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e5. Согласованность с оплатой (сага)\u003c/h3\u003e\u003cp\u003eПоток: \u003ccode\u003eReservePoints → Payment → (success) ConfirmRedemption\u003c/code\u003e / \u003ccode\u003e(failure|timeout) ReleaseReservation\u003c/code\u003e. Оркестратор — сервис чека. Если Confirm не дошёл до лояльности — резерв истекает по TTL и автоматически освобождается (никаких «навсегда зависших» списаний). Все шаги идемпотентны по \u003ccode\u003eoperationId\u003c/code\u003e. Расхождение ловит почасовая сверка: операции \u003ccode\u003eCONFIRMED\u003c/code\u003e в лояльности должны иметь успешный платёж, и наоборот.\u003c/p\u003e\u003ch3\u003e6. Офлайн-кассы\u003c/h3\u003e\u003cp\u003eСтратегия — \u003cstrong\u003eограниченный офлайн с контролируемым риском\u003c/strong\u003e:\u003c/p\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eКэш на кассе:\u003c/strong\u003e при наличии связи локально хранится снимок баланса участника (TTL 24 часа) и активные правила. Касса идентифицирует участника по QR/карте офлайн.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eНачисление офлайн:\u003c/strong\u003e разрешено всегда (риск — начислить лишнее, а не потерять деньги клиента). Чек ставится в локальную очередь и синхронизируется при появлении связи; идемпотентность по \u003ccode\u003estoreId+receiptId\u003c/code\u003e исключает задвоение.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eСписание офлайн:\u003c/strong\u003e разрешено в пределах \u003ccode\u003emin(кэшированный баланс, риск-лимит)\u003c/code\u003e. Риск-лимит настраивается: по умолчанию 3 000 баллов на чек и 20 000 на магазин в сутки; для участников с большим балансом — не выше 30% кэшированного баланса. Сверх лимита — отказ с вежливым сценарием («оплатите баллами, когда восстановится связь, или полностью деньгами»).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eСинхронизация:\u003c/strong\u003e очередь чеков с порядковыми номерами, ретраи с backoff, контроль целостности (касса сообщает о пропущенных номерах). При расхождении кэшированного баланса и фактического: если баллов уже меньше, чем списали офлайн, — возникает перерасход, который фиксируется как \u003ccode\u003eOVERDRAFT\u003c/code\u003e и разбирается по правилам (см. п. 8), клиенту не блокируем покупки.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eАльтернатива для крупных списаний:\u003c/strong\u003e предзагрузка «офлайн-кошелька» по запросу клиента (явно снял N баллов для офлайн-использования) — снижает риск, но усложняет UX; оставляем как опцию фазы 2.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e7. Сгорание\u003c/h3\u003e\u003cul\u003e\u003cli\u003eНочной батч по \u003ccode\u003eexpiresAt\u003c/code\u003e: выбираем партии с истёкшим сроком, списываем \u003ccode\u003eremainingAmount\u003c/code\u003e записью \u003ccode\u003eEXPIRE\u003c/code\u003e, фиксируем в журнале и в отчёте.\u003c/li\u003e\u003cli\u003eПользователю заранее: уведомление за 30 и за 3 дня («сгорит 450 баллов»), в приложении — блок «скоро сгорят».\u003c/li\u003e\u003cli\u003eСпорный кейс: клиент оформляет заказ в момент сгорания. Решение — на время активного резерва партия не сгорает (резерв имеет приоритет), батч её пропускает и переносит на следующий запуск. Правило фиксируем в спецификации и в тексте оферты.\u003c/li\u003e\u003cli\u003eБухгалтерия: сгорание — это списание обязательства, отдельная проводка и отчёт за период.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e8. Возвраты и сторно\u003c/h3\u003e\u003col\u003e\u003cli\u003eЧек возврата ссылается на исходный чек. Находим \u003ccode\u003eACCRUAL\u003c/code\u003e по \u003ccode\u003ereceiptId\u003c/code\u003e и сторнируем начисление: запись \u003ccode\u003eREVERSAL\u003c/code\u003e с отрицательной суммой, привязанная к партии.\u003c/li\u003e\u003cli\u003eЕсли партия уже частично/полностью потрачена → \u003cstrong\u003eотрицательный остаток партии\u003c/strong\u003e превращается в «долг участника» (\u003ccode\u003ePointsDebt\u003c/code\u003e):\u003c/li\u003e\u003cli\u003eПравила для долга (согласуются с бизнесом и юристами, наш выбор): долг удерживается из будущих начислений автоматически; покупки с баллами при долге недоступны, обычные покупки — доступны; если долг не погашен 90 дней — списываем как убыток с отчётом в финотдел. Баланс участника никогда не показываем отрицательным в UI — показываем «задолженность: N баллов».\u003c/li\u003e\u003cli\u003eЕсли при возврате было списание баллов (клиент платил баллами) — возвращаем баллы той же операцией \u003ccode\u003eREVERSAL\u003c/code\u003e с новым сроком жизни (не продлеваем старый, но и не обнуляем: новая партия со сроком 12 мес от даты возврата; правило фиксируем в оферте).\u003c/li\u003e\u003cli\u003eЧастичный возврат — сторно пропорционально возвращённым позициям, с пересчётом правил (акционная позиция могла давать 0%).\u003c/li\u003e\u003c/ol\u003e\u003ch3\u003e9. Аудит и бухгалтерия\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003ccode\u003eLedgerEntry\u003c/code\u003e — append-only, изменения запрещены на уровне БД (никаких UPDATE), исправления только новыми записями.\u003c/li\u003e\u003cli\u003eБаланс — материализованное представление; ночная сверка: сумма журнала = сумма балансов = сумма остатков партий. Расхождение → алерт и блокировка батчей до разбора.\u003c/li\u003e\u003cli\u003eДля бухгалтерии: ежемесячный отчёт — начислено, списано, сгорело, сторнировано, обязательство на конец периода (в рублях по курсу 1 балл = 1 ₽), детализация по магазинам и кампаниям. Каждая проводка ссылается на \u003ccode\u003eoperationId\u003c/code\u003e и чек.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e10. Производительность\u003c/h3\u003e\u003cul\u003e\u003cli\u003e2 млн чеков/сутки ≈ 23 чека/сек в среднем, пик ×4 ≈ 90–120/сек; с учётом всплесков закладываем 500/сек. Это немного для одной БД, поэтому главная забота — не шардинг, а горячие строки: один участник может иметь несколько одновременных операций.\u003c/li\u003e\u003cli\u003eШардирование по \u003ccode\u003ememberId\u003c/code\u003e (hash) — 16 шардов с запасом на рост; журнал и партии живут в одном шарде с участником, чтобы списание по FIFO было локальной транзакцией.\u003c/li\u003e\u003cli\u003eОтвет кассе ≤ 2 сек: правила и баланс кэшируем (Redis, TTL 60 сек с инвалидацией по событию), расчёт начисления — чистая функция, без внешних вызовов в критическом пути. Интеграция с бухгалтерией и антифродом — асинхронно после ответа кассе.\u003c/li\u003e\u003cli\u003eБатчи сгорания и сверки — в низконагруженное окно, порционно (по 1000 партий), с паузами, чтобы не блокировать запись.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e11. Антифрод\u003c/h3\u003e\u003cul\u003e\u003cli\u003eЛимиты: максимум начислений на участника в сутки, максимальная сумма чека без ручной проверки, частота возвратов, серия мелких чеков у одного кассира.\u003c/li\u003e\u003cli\u003eРучные начисления (компенсации) — только ролью поддержки с указанием причины, лимитом на сотрудника и обязательным аудитом; массовые начисления — через отдельный процесс с двойным подтверждением.\u003c/li\u003e\u003cli\u003eМониторинг аномалий: отклонение распределения начислений по магазину, всплеск списаний перед сгоранием, повторные возвраты.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e12. Метрики программы\u003c/h3\u003e\u003cul\u003e\u003cli\u003eБизнес: доля участников в чеках, penetration (чеки с баллами / все чеки), redemption rate (списано / начислено), средний чек участника vs неучастника, повторные покупки, стоимость программы (начислено − сгорело) в рублях, обязательство на балансе.\u003c/li\u003e\u003cli\u003eТехнические: p95 времени ответа кассе, доля офлайн-чеков и время синхронизации, число расхождений сверки, число OVERDRAFT, размер очереди батчей.\u003c/li\u003e\u003cli\u003eКлиентские: жалобы «не начислили», «сгорело», NPS программы, обращения в поддержку на 1000 чеков.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e13. План запуска\u003c/h3\u003e\u003col\u003e\u003cli\u003e\u003cstrong\u003eФаза 1 (пилот, 20 магазинов + онлайн):\u003c/strong\u003e только начисление и просмотр баланса в приложении, без списания. Цель — проверить стабильность интеграции с кассами, качество чеков, расчёт правил. Критерии: 0 расхождений сверки 14 дней подряд, p95 \u0026lt; 1 сек, доля неуспешной синхронизации \u0026lt; 0,1%.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eФаза 2:\u003c/strong\u003e включаем списание в пилоте (онлайн + 20 магазинов), добавляем офлайн-режим с консервативными лимитами (1 000 баллов), антифрод, поддержку. Критерии: нет инцидентов задвоения, overdraft \u0026lt; 0,05% операций.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eФаза 3:\u003c/strong\u003e масштабирование волнами по 100 магазинов, обучение кассиров, рост лимитов офлайна по данным пилота. Откат — флаг на магазин: прекращаем списание, начисление продолжаем (баллы не теряются).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eФаза 4:\u003c/strong\u003e сгорание (включаем через 12 месяцев после первых начислений), уровни участников, акции маркетинга.\u003c/li\u003e\u003c/ol\u003e","plantuml":"@startuml\nautonumber\nskinparam maxMessageSize 250\nactor \"Покупатель\" as C\nparticipant \"Касса (POS)\" as POS\nparticipant \"POS Integration\" as PI\nparticipant \"Loyalty Core\" as LOY\ndatabase \"Ledger + Batches\" as DB\nparticipant \"Payments\" as PAY\nparticipant \"Rules Engine\" as RULE\nparticipant \"Finance / BI\" as FIN\n\n== Начисление и списание в одном чеке ==\nC -\u003e POS: Товары + QR-карта участника\nPOS -\u003e PI: рассчитать баллы (участник, позиции, сумма)\nPI -\u003e LOY: quote(memberRef, items, total)\nLOY -\u003e RULE: активные правила на дату чека\nRULE --\u003e LOY: процент, исключения, ruleVersion\nLOY --\u003e PI: начислим 137 баллов, доступно 2 450, лимит списания 735\nPI --\u003e POS: показать на экране\nC -\u003e POS: \"Списать 500 баллов\"\nPOS -\u003e PI: redeem(memberRef, 500, receiptId)\nPI -\u003e LOY: ReservePoints (idempotencyKey = storeId+receiptId)\nLOY -\u003e DB: reservedBalance += 500 (TTL 15 мин)\nLOY --\u003e PI: HOLD OK\nPI --\u003e POS: к оплате с учётом баллов\nPOS -\u003e PAY: оплата чека\nalt оплата успешна\n  PAY --\u003e PI: success\n  PI -\u003e LOY: ConfirmRedemption(operationId)\n  LOY -\u003e DB: списание по FIFO-партиям + LedgerEntry(REDEMPTION) + Accrual(137) + новая партия\n  LOY --\u003e PI: OK\n  PI -\u003e POS: чек закрыт, баллы начислены\n  POS --\u003e C: чек + \"начислено 137 баллов\"\nelse оплата не прошла / таймаут\n  PAY --\u003e PI: failed\n  PI -\u003e LOY: ReleaseReservation(operationId)\n  LOY -\u003e DB: reservedBalance -= 500\n  LOY --\u003e PI: OK\n  PI --\u003e POS: баллы не списаны, чек не оплачен\nend\nLOY -\u003e\u003e FIN: событие операции (асинхронно)\n\n== Офлайн-режим ==\nnote over POS, PI: связь пропала\nC -\u003e POS: товары + QR\nPOS -\u003e POS: локальный расчёт по кэшированным правилам\\nсписание в пределах min(кэш-баланс, риск-лимит)\nPOS --\u003e C: чек пробит, баллы начислены (предварительно)\nPOS -\u003e POS: чек в локальную очередь (seq)\n... связь восстановлена ...\nPOS -\u003e PI: синхронизация очереди чеков\nPI -\u003e LOY: processReceipt (idempotencyKey = storeId+receiptId)\nalt чек уже обработан\n  LOY --\u003e PI: дубль, возвращаем прежний результат\nelse чек новый\n  LOY -\u003e DB: LedgerEntry + партии, корректировка баланса\n  LOY --\u003e PI: OK / OVERDRAFT если баланс ушёл в минус\n  PI -\u003e FIN: расхождение в отчёт\nend\n@enduml\n","mermaid":"flowchart TD\n  subgraph Core[\"Контекст Loyalty Core\"]\n    M[Member\\nуровень, согласия]\n    A[PointsAccount\\navailable / reserved]\n    B[PointsBatch\\nпартии, expiresAt]\n    L[LedgerEntry\\nappend-only журнал]\n    O[Operation\\nidempotencyKey, sagaState]\n  end\n  subgraph Rules[\"Контекст Rules / Marketing\"]\n    R[Campaign + RuleVersion\\nпроценты, исключения]\n  end\n  subgraph Channels[\"Каналы\"]\n    POS[POS Integration\\nофлайн-очередь]\n    WEB[Интернет-магазин]\n    APP[Приложение]\n  end\n  subgraph External[\"Внешние\"]\n    PAY[Payments\\nсага списания]\n    FIN[Finance / BI\\nобязательства, сверка]\n    FRD[Anti-fraud]\n  end\n  POS --\u003e O\n  WEB --\u003e O\n  APP --\u003e M\n  O --\u003e L\n  L --\u003e B\n  B --\u003e A\n  R --\u003e O\n  O \u003c--\u003e PAY\n  L --\u003e FIN\n  O --\u003e FRD\n  B --\u003e|сгорание FIFO| L\n  L --\u003e|сторно возвратов| O\n"}'::jsonb, updated_at = now() WHERE id = 'des-loyalty';
UPDATE tasks SET statement = '{"brief":"Ежедневный отчёт по продажам идёт 40 минут и иногда падает по таймауту. Нужен диагноз и план лечения.","context":["Команда продаж каждое утро ждёт отчёт: выручка по магазинам и категориям за вчера, сравнение с прошлой неделей. Отчёт формируется SQL-запросом к операционной базе заказов (PostgreSQL, 80 млн строк в \u003ccode\u003eorder_items\u003c/code\u003e).","Запрос запускается в 6:00 утра через планировщик. Раньше он шёл 3 минуты, за год вырос до 40 и дважды падал по таймауту. Продажи уже начали выгружать данные в Excel руками.","Разработчики говорят: «добавим индексы». ДБA говорит: «запрос написан плохо». Бизнес говорит: «просто сделайте быстрее»."],"goal":"Провести диагностику как аналитик: что именно измеряем, какие гипотезы проверяем, какие данные запрашиваем у команды, и предложить план решений с оценкой эффекта и рисков.","inputs":["Текст запроса (упрощённо): выборка из \u003ccode\u003eorders\u003c/code\u003e JOIN \u003ccode\u003eorder_items\u003c/code\u003e JOIN \u003ccode\u003eproducts\u003c/code\u003e JOIN \u003ccode\u003estores\u003c/code\u003e с фильтрами по дате, группировкой по магазину и категории, двумя подзапросами для сравнения с прошлой неделей и \u003ccode\u003eORDER BY\u003c/code\u003e по выручке.","Фильтр по дате написан как \u003ccode\u003eWHERE DATE(o.created_at) = :yesterday\u003c/code\u003e.","В \u003ccode\u003eorder_items\u003c/code\u003e 80 млн строк, индексы есть по \u003ccode\u003eorder_id\u003c/code\u003e и по \u003ccode\u003eproduct_id\u003c/code\u003e.","Отчёт нужен к 8:00, данных за сегодня в нём быть не должно.","Операционная база одновременно обслуживает оформление заказов."],"deliverables":["Список гипотез о причинах деградации и как каждую проверить (какие метрики/планы запроса посмотреть).","Конкретные претензии к запросу с объяснением, почему это медленно.","Варианты решения: от быстрого к системному, с оценкой трудозатрат и эффекта.","Как не сломать операционную нагрузку: где выполнять отчёт.","Что предложить бизнесу по формату отчёта (может быть, данные нужны не так, как он просит).","Критерии успеха: как поймём, что стало лучше."],"constraints":["Операционная БД не должна страдать: оформление заказов приоритетнее отчёта.","Решение должно быть внедрено за 2 недели силами одного разработчика.","Нельзя «просто купить более мощный сервер» без обоснования."],"interview":"«Отчёт тормозит. Что вы будете делать как аналитик? И что вы скажете бизнесу?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Диагностика и план","content":"\u003ch3\u003eГипотезы\u003c/h3\u003e\u003ch3\u003eЧто не так с запросом\u003c/h3\u003e\u003ch3\u003eВарианты решения\u003c/h3\u003e\u003ch3\u003eКритерии успеха\u003c/h3\u003e"},{"type":"plantuml","title":"Схема потоков данных","content":"@startuml\ndatabase \"Операционная БД\\n(заказы)\" as OLTP\nnode \"Планировщик 06:00\" as CRON\nrectangle \"Отчёт\" as RPT\n\nCRON -\u003e OLTP: тяжёлый запрос\nOLTP --\u003e RPT: результат\nRPT --\u003e [Excel / почта] : выгрузка\n@enduml\n"}]'::jsonb, rubric = '[{"id":"measure-first","title":"Сначала диагностика: EXPLAIN ANALYZE, план запроса, статистика БД, а не сразу «добавим индексов»","weight":"high","weightValue":null,"focus":"arch","keywords":["explain","план запрос","analyze","диагност","статистик","pg_stat","профилир","измер"],"why":"Без плана запроса любые рекомендации — гадание. Это первый шаг, который отличает инженера от «эксперта по советам».","critical":false},{"id":"function-on-column","title":"Найдена ошибка \u003ccode\u003eDATE(created_at)\u003c/code\u003e: функция на колонке убивает использование индекса","weight":"high","weightValue":null,"focus":"arch","keywords":["date(","функци","индекс не использу","sargable","диапазон","created_at \u003e","обёртк","преобразован"],"why":"Классика: \u003ccode\u003eWHERE DATE(col) = x\u003c/code\u003e заставляет БД сканировать всю таблицу. Условие прямо даёт эту строку.","critical":false},{"id":"missing-index","title":"Предложение индекса под фактический паттерн доступа (дата + покрывающий/составной индекс)","weight":"high","weightValue":null,"focus":"arch","keywords":["индекс","index","составн","composite","покрывающ","covering","include","b-tree","created_at"],"why":"Индекс по order_id не помогает фильтру по дате. Нужен индекс, соответствующий предикату запроса.","critical":false},{"id":"subqueries","title":"Претензии к структуре: коррелированные подзапросы, двойное сканирование, ORDER BY без нужды","weight":"mid","weightValue":null,"focus":"arch","keywords":["подзапрос","subquery","коррелир","cte","window","оконн","join","двойн","order by","агрегац"],"why":"Два подзапроса «за прошлую неделю» часто означают тройное сканирование 80-миллионной таблицы.","critical":false},{"id":"olap-separation","title":"Отделение аналитической нагрузки: реплика, витрина/DWH, материализованное представление, а не запрос в OLTP","weight":"high","weightValue":null,"focus":"arch","keywords":["реплик","read replica","dwh","хранилищ","витрин","materialized","материализов","olap","отдельн","clickhouse"],"why":"Ограничение требует не трогать операционную базу. Без выноса отчёта любое ускорение запроса — полумера.","critical":false},{"id":"preaggregation","title":"Предподсчёт: ежедневная агрегация по магазину/категории вместо пересчёта 80 млн строк","weight":"high","weightValue":null,"focus":"sa","keywords":["агрегац","предподсч","итогов","summary","по дням","ежедн","накапли","инкремент"],"why":"Отчёт по дням не требует пересчёта всей истории: достаточно хранить агрегат за день и читать 2 строки на магазин.","critical":false},{"id":"business-value","title":"Работа с бизнесом: зачем отчёт, что реально нужно, можно ли реже/другой формат/самообслуживание","weight":"mid","weightValue":null,"focus":"sa","keywords":["зачем","бизнес","потребн","дашборд","самообслуж","bi","частот","что решают","интерактив","фильтр"],"why":"Часто 40-минутный отчёт решает задачу, которую закрывает дашборд с фильтром. Аналитик должен это выяснить.","critical":false},{"id":"success-criteria","title":"Критерии успеха и план внедрения: целевое время, срок, риск, откат","weight":"mid","weightValue":null,"focus":"sa","keywords":["критер","целев","секунд","минут","срок","2 недел","риск","откат","оценк","эффект"],"why":"«Сделали быстрее» — не результат. Нужны измеримые критерии и учёт ограничения в 2 недели.","critical":false}]'::jsonb, hints = '["Посмотрите на предикат \u003ccode\u003eWHERE DATE(o.created_at) = :yesterday\u003c/code\u003e. Может ли БД использовать индекс по created_at?","Сколько раз запрос читает order_items: один раз или три (сегодня, прошлая неделя, итоги)?","Отчёт нужен к 8:00 про вчера. Почему бы не посчитать агрегат один раз ночью и хранить его?"]'::jsonb, interview_questions = '["С чего начнёте диагностику и какие данные попросите у команды?","Почему \u003ccode\u003eDATE(created_at) = :yesterday\u003c/code\u003e — это проблема и как переписать?","Какой индекс предложите и что он даст?","Отчёт всё ещё бьёт по операционной БД. Что сделаете?","Бизнес просит «просто быстрее». О чём вы его спросите?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Диагностика (что просим у команды)\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003ccode\u003eEXPLAIN (ANALYZE, BUFFERS)\u003c/code\u003e запроса с боевыми параметрами — смотрим фактические строки vs оценки планировщика, тип сканирования (Seq Scan на order_items = диагноз), время по узлам.\u003c/li\u003e\u003cli\u003eСписок индексов таблиц и статистику их использования: \u003ccode\u003epg_stat_user_indexes\u003c/code\u003e (idx_scan = 0 → индекс не работает).\u003c/li\u003e\u003cli\u003eАктуальность статистики: \u003ccode\u003elast_analyze\u003c/code\u003e/\u003ccode\u003elast_autoanalyze\u003c/code\u003e в \u003ccode\u003epg_stat_user_tables\u003c/code\u003e; при сильном перекосе планировщик выбирает плохой план.\u003c/li\u003e\u003cli\u003eИсторию длительности за год (мониторинг/журнал планировщика) — когда именно началась деградация: рост данных, новый JOIN, изменение плана после обновления БД.\u003c/li\u003e\u003cli\u003eОбъёмы: строк в orders/order_items, доля строк за сутки, размер таблиц и индексов.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e2. Гипотезы и что нашли\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eГипотеза\u003c/th\u003e\u003cth\u003eКак проверяем\u003c/th\u003e\u003cth\u003eВердикт\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eФункция на колонке даты не даёт использовать индекс\u003c/td\u003e\u003ctd\u003eEXPLAIN: Seq Scan на orders вместо Index Scan\u003c/td\u003e\u003ctd\u003e\u003cstrong\u003eПодтверждено\u003c/strong\u003e: \u003ccode\u003eDATE(o.created_at) = :yesterday\u003c/code\u003e → полное сканирование\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eНет индекса под фильтр по дате\u003c/td\u003e\u003ctd\u003epg_stat_user_indexes\u003c/td\u003e\u003ctd\u003e\u003cstrong\u003eПодтверждено\u003c/strong\u003e: индексы только по order_id и product_id\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eКоррелированные подзапросы сканируют таблицу ещё дважды\u003c/td\u003e\u003ctd\u003eEXPLAIN: число узлов сканирования order_items\u003c/td\u003e\u003ctd\u003e\u003cstrong\u003eПодтверждено\u003c/strong\u003e: 3 прохода по 80 млн строк\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eУстаревшая статистика\u003c/td\u003e\u003ctd\u003elast_autoanalyze\u003c/td\u003e\u003ctd\u003eЧастично: автоанализ идёт, но перекос оценок из-за пунктов выше\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eРост данных за год\u003c/td\u003e\u003ctd\u003eистория объёмов\u003c/td\u003e\u003ctd\u003e\u003cstrong\u003eПодтверждено\u003c/strong\u003e: 22 млн → 80 млн строк; без индексов время растёт линейно\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eКонкуренция с операционной нагрузкой в 6:00\u003c/td\u003e\u003ctd\u003eметрики БД по времени суток\u003c/td\u003e\u003ctd\u003eВносит вклад: в 6:00 идёт ночная выгрузка и бэкап\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003ch3\u003e3. Быстрые исправления (1–2 дня, один разработчик)\u003c/h3\u003e\u003col\u003e\u003cli\u003eПереписать предикат на SARGable-диапазон: \u003ccode\u003eWHERE o.created_at \u0026gt;= :yesterdayStart AND o.created_at \u0026lt; :todayStart\u003c/code\u003e. То же для периода «прошлая неделя».\u003c/li\u003e\u003cli\u003eДобавить составной индекс: \u003ccode\u003eCREATE INDEX CONCURRENTLY idx_orders_created_at_store ON orders (created_at, store_id) INCLUDE (id, total_amount)\u003c/code\u003e. CONCURRENTLY — чтобы не блокировать запись. Покрывающая часть убирает обращение к таблице.\u003c/li\u003e\u003cli\u003eЗаменить подзапросы на один проход с условной агрегацией: \u003ccode\u003eSUM(CASE WHEN created_at BETWEEN ... THEN amount END)\u003c/code\u003e как «эта неделя», вторая колонка — «прошлая неделя». Или CTE с одним сканированием и двумя диапазонами дат.\u003c/li\u003e\u003cli\u003eУбрать \u003ccode\u003eORDER BY\u003c/code\u003e из SQL, если сортировка делается в Excel/BI: сортировка 40 строк результата бесплатна, но сортировка промежуточного набора — нет.\u003c/li\u003e\u003cli\u003eПеренести запуск с 6:00 на 3:30, чтобы не пересекаться с бэкапом и выгрузкой.\u003c/li\u003e\u003c/ol\u003e\u003cp\u003e\u003cstrong\u003eОжидаемый эффект:\u003c/strong\u003e 40 минут → 30–90 секунд за счёт Index Scan и одного прохода. Проверить EXPLAIN ANALYZE до и после, приложить цифры.\u003c/p\u003e\u003ch3\u003e4. Системное решение (2 недели)\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eНе бить по операционной БД:\u003c/strong\u003e отчёт выполняется на read-реплике. Если реплики нет — минимум ограничиваем ресурс: \u003ccode\u003estatement_timeout\u003c/code\u003e, \u003ccode\u003ework_mem\u003c/code\u003e для сессии отчёта, запуск в окне низкой нагрузки.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eПредподсчёт:\u003c/strong\u003e ночной батч складывает дневные агрегаты в таблицу \u003ccode\u003esales_daily_agg(date, store_id, category_id, orders_count, revenue, discount_sum)\u003c/code\u003e — инкрементально, только за вчерашний день (идемпотентно: delete+insert по дате). Отчёт читает 2 × N строк из агрегата → секунды, а не минуты.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eМатериализованное представление\u003c/strong\u003e как промежуточный вариант, если батч внедрять долго: \u003ccode\u003eREFRESH MATERIALIZED VIEW CONCURRENTLY\u003c/code\u003e ночью.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eДальше по мере роста:\u003c/strong\u003e вынос отчётности в DWH/OLAP-хранилище (ClickHouse/Greenplum) с репликацией CDC; операционная БД остаётся для транзакций.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e5. Разговор с бизнесом\u003c/h3\u003e\u003cul\u003e\u003cli\u003eВыясняем: кто читает отчёт, какие решения принимает, какие строки реально использует, нужна ли детализация до позиции (скорее всего нет — только магазин × категория).\u003c/li\u003e\u003cli\u003eПредлагаем дашборд в BI поверх \u003ccode\u003esales_daily_agg\u003c/code\u003e: фильтр по периоду и магазину, сравнение с прошлой неделей «из коробки», обновление раз в сутки. Отчёт как рассылка сохраняется, но формируется из агрегата.\u003c/li\u003e\u003cli\u003eЕсли бизнесу нужны данные к 8:00 — гарантируем готовность к 7:00 с алертом при сбое батча и ручным перезапуском (runbook для дежурного).\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e6. Критерии успеха\u003c/h3\u003e\u003cul\u003e\u003cli\u003eВремя формирования отчёта ≤ 2 минут (p95) в течение 14 дней.\u003c/li\u003e\u003cli\u003eОтчёт готов к 7:00 каждый день, 0 падений по таймауту за месяц.\u003c/li\u003e\u003cli\u003eНагрузка на операционную БД в окно отчёта не растёт: p95 времени оформления заказа без изменений.\u003c/li\u003e\u003cli\u003eЦифры отчёта совпадают с прежними (сверка за 5 дней до переключения — обязательна, иначе бизнес не примет).\u003c/li\u003e\u003cli\u003eРучные выгрузки в Excel прекратились (спрашиваем у продаж через месяц).\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e7. Риски\u003c/h3\u003e\u003cul\u003e\u003cli\u003eИндекс занимает место и замедляет запись в orders: оцениваем размер, следим за WAL и временем INSERT после внедрения.\u003c/li\u003e\u003cli\u003eПереписанный запрос может дать другие цифры (округления, часовые пояса): поэтому сверка до/после обязательна, особенно граница суток в UTC vs локальное время.\u003c/li\u003e\u003cli\u003eБатч агрегации может не отработать: нужны алерт, идемпотентный перезапуск и возможность пересчитать период вручную.\u003c/li\u003e\u003c/ul\u003e","plantuml":"@startuml\ntitle Было / Стало\n\nrectangle \"Было\" {\n  node \"Планировщик 06:00\" as C1\n  database \"OLTP: orders 80M\\nSeq Scan ×3\" as DB1\n  rectangle \"Отчёт 40 мин\\n(иногда timeout)\" as R1\n  C1 --\u003e DB1 : тяжёлый JOIN + подзапросы\n  DB1 --\u003e R1\n}\n\nrectangle \"Стало\" {\n  node \"Планировщик 03:30\" as C2\n  database \"OLTP\" as DB2\n  database \"Read-реплика\" as REP\n  rectangle \"Батч: sales_daily_agg\\n(инкремент за вчера)\" as AGG\n  rectangle \"Отчёт из агрегата\\n≤ 2 мин\" as R2\n  rectangle \"BI-дашборд для продаж\" as BI\n  DB2 --\u003e REP : потоковая репликация\n  C2 --\u003e AGG\n  AGG --\u003e REP : читает только вчера\n  REP --\u003e R2\n  AGG --\u003e BI\n}\n@enduml\n"}'::jsonb, updated_at = now() WHERE id = 'db-slow-report';
UPDATE tasks SET statement = '{"brief":"Одна широкая таблица на 60 колонок хранит заявки. Дубли, расхождения, невозможность отчётности. Нужна нормализация.","context":["Сервисный центр принимает заявки на ремонт. Всё живёт в таблице \u003ccode\u003erequests\u003c/code\u003e на 60 колонок: данные клиента (ФИО, телефон, адрес), данные устройства (марка, модель, серийный номер), данные заявки (дата, статус, исполнитель, стоимость), текстовые поля («описание неисправности», «что сделано», «комментарий руководителя»), а также колонки вида «услуга1», «услуга2», «услуга3» с ценами.","Проблемы: один клиент с тремя заявками заведён трижды с разными написаниями телефона; историю статусов не восстановить; отчёт по выручке в разрезе услуг считается вручную, потому что услуг может быть больше трёх; исполнители жалуются, что «всё в одну кучу».","Разработка готова переделать схему, но просит обоснование и план переноса данных — система работает, заявки терять нельзя."],"goal":"Спроектировать нормализованную схему, объяснить выбор, описать план переноса данных и что изменится для пользователей и отчётности.","inputs":["Текущая таблица: 60 колонок, 1,2 млн строк, рост 8 тысяч заявок в месяц.","Колонки «услуга1..3» заполнены на 65%, у 12% заявок услуг больше трёх — их дописывают в текстовый комментарий.","Телефон клиента хранится в свободном формате: «89161234567», «+7 (916) 123-45-67», «916-123-45-67».","Статусы заявки меняются по 5–8 раз, история нигде не сохраняется.","Пользователи: приёмщик, мастер, руководитель отдела, бухгалтерия."],"deliverables":["Целевая схема: сущности, атрибуты, ключи, связи, обоснование нормальных форм (какие НФ достигаются и почему дальше не идём).","Решение для услуг заявки (вместо «услуга1..3») и для истории статусов.","Справочники: что выносим в них, как поддерживаем.","План переноса данных: очистка, дубли клиентов, маппинг, проверка, этапы, откат.","Влияние на интерфейсы и отчётность: что станет возможным, что сломается.","Осознанная денормализация, если она нужна, с обоснованием."],"constraints":["Система работает 24/7, простой не более 30 минут.","Исторические данные должны остаться доступны: старые заявки нужны для гарантийных обязательств.","Приёмщики не должны учиться работать заново: экран создания заявки остаётся таким же по скорости."],"interview":"«У вас таблица на 60 колонок. Нормализуйте. До какой НФ и почему не дальше? Как перенесёте данные без простоя?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Целевая схема и план","content":"\u003ch3\u003eСущности и обоснование НФ\u003c/h3\u003e\u003ch3\u003eУслуги и история статусов\u003c/h3\u003e\u003ch3\u003eПлан переноса\u003c/h3\u003e\u003ch3\u003eВлияние на отчётность\u003c/h3\u003e"},{"type":"mermaid","title":"ER-диаграмма","content":"erDiagram\n  CLIENT ||--o{ REQUEST : \"подаёт\"\n  DEVICE ||--o{ REQUEST : \"ремонтируется\"\n  REQUEST ||--o{ REQUEST_SERVICE : \"содержит\"\n  SERVICE ||--o{ REQUEST_SERVICE : \"оказывается\"\n  EMPLOYEE ||--o{ REQUEST : \"исполняет\"\n"}]'::jsonb, rubric = '[{"id":"entities","title":"Выделены сущности: клиент, устройство, заявка, услуга, исполнитель, справочники — со связями и ключами","weight":"high","weightValue":null,"focus":"sa","keywords":["client","клиент","device","устройств","request","заявк","service","услуг","employee","исполнит","сущност","связ"],"why":"Суть задачи — разделение сущностей. Одна таблица «всё в одном» — причина всех перечисленных болей.","critical":false},{"id":"nf-justification","title":"Обоснование нормальных форм: что устраняем (1НФ — повторяющиеся группы, 2НФ/3НФ — транзитивные зависимости), почему не идём дальше","weight":"high","weightValue":null,"focus":"sa","keywords":["1нф","2нф","3нф","нормальн","транзитивн","зависим","повторяющ","групп","bcnf","избыточн","аномал"],"why":"«Нормализуем» без объяснения, какие аномалии устраняются, — это лозунг, а не проектное решение.","critical":false},{"id":"services-m2m","title":"Услуги: связь many-to-many с ценой и количеством на связи, вместо «услуга1..3»","weight":"high","weightValue":null,"focus":"arch","keywords":["many-to-many","многие ко многим","request_service","связующ","цена","количеств","позиц","m2m"],"why":"12% заявок имеют больше трёх услуг и попадают в текст. Только связь M2M закрывает отчётность по услугам.","critical":false},{"id":"status-history","title":"История статусов отдельной таблицей (событийная модель), а не полем «текущий статус»","weight":"high","weightValue":null,"focus":"arch","keywords":["истори","history","статус","лог","журнал","переход","событи","timestamp","кто изменил"],"why":"Бизнес жалуется, что историю не восстановить. Плюс это нужно для SLA-отчётности.","critical":false},{"id":"client-dedup","title":"Дедупликация клиентов: нормализация телефона, правила объединения, что делать с конфликтами данных","weight":"high","weightValue":null,"focus":"sa","keywords":["дубл","дедупл","телефон","нормализ","объедин","формат","канонич","merge","конфликт"],"why":"Условие прямо говорит про три записи одного клиента с разными написаниями телефона. Без этого отчётность по клиентам невозможна.","critical":false},{"id":"dicts","title":"Справочники: марки/модели, типы неисправностей, статусы, услуги — с кодами, версионированием и владельцем","weight":"mid","weightValue":null,"focus":"sa","keywords":["справочник","dict","каталог","код","тип неисправн","модель","марк","владел","верси"],"why":"Текстовые поля «марка» и «модель» в свободной форме не дают аналитики. Справочники — обязательное условие для отчётов.","critical":false},{"id":"migration-plan","title":"План переноса: этапы, очистка, маппинг, проверка (сверка объёмов и сумм), простой ≤ 30 мин, откат","weight":"high","weightValue":null,"focus":"sa","keywords":["миграц","перенос","этап","очистк","сверк","проверк","откат","простой","бэкап","валидац"],"why":"Ограничение — работающая система и 30 минут простоя. Без плана переноса схема останется на бумаге.","critical":false},{"id":"ui-impact","title":"Влияние на пользователей: как изменится экран заявки, что станет возможным, как обучаем","weight":"mid","weightValue":null,"focus":"sa","keywords":["интерфейс","экран","приёмщик","мастер","обучен","скорост","форм","пользовател","ux"],"why":"Ограничение: приёмщики не должны учиться заново. Аналитик обязан продумать влияние на рабочие места.","critical":false},{"id":"denormalization","title":"Осознанная денормализация там, где она оправдана (кешированная сумма заявки, ФИО клиента в отчёте)","weight":"mid","weightValue":null,"focus":"arch","keywords":["денормал","избыточн","кэш","total","сумма заявки","производит","вычисля","хранит итог"],"why":"Догматичная нормализация убьёт производительность экрана. Зрелый ответ — знать, где можно нарушить правило.","critical":false},{"id":"reporting","title":"Какая отчётность становится возможной: выручка по услугам, загрузка мастеров, SLA, повторные обращения","weight":"mid","weightValue":null,"focus":"sa","keywords":["отчёт","выручк","услуг","загрузк","sla","повторн","аналитик","дашборд","метри"],"why":"Смысл нормализации — не красота схемы, а возможность считать то, что раньше считали руками.","critical":false}]'::jsonb, hints = '["Колонки «услуга1..3» — нарушение 1НФ (повторяющиеся группы). Как выглядит правильное решение?","Телефон «+7 (916) 123-45-67» и «89161234567» — это один клиент. Какой этап переноса данных это обнаруживает?","Денормализация не всегда зло. Где вы оставите избыточное поле и почему?"]'::jsonb, interview_questions = '["До какой нормальной формы вы доводите схему и почему останавливаетесь?","Как храните историю статусов и что это даёт бизнесу?","У клиента три записи с разными телефонами. Как объединяете и кто решает конфликты?","Как перенесёте 1,2 млн строк с простоем не более 30 минут?","Где вы оставите денормализацию и как обеспечите согласованность?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Целевая схема\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eСущность\u003c/th\u003e\u003cth\u003eАтрибуты\u003c/th\u003e\u003cth\u003eОбоснование\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eclient\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, phone_norm (UNIQUE), phone_raw, full_name, email, address_id, created_at, is_merged_into\u003c/td\u003e\u003ctd\u003eОдна запись на человека; дубли устраняются, а не хранятся\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eaddress\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, city, street, house, flat, postal_code\u003c/td\u003e\u003ctd\u003eАдрес вынесен: у клиента их может быть несколько, и адрес нужен в отчётах по географии\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003edevice\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, brand_id, model_id, serial_number, client_id, purchase_date, warranty_until\u003c/td\u003e\u003ctd\u003eУстройство — самостоятельная сущность: гарантийные обязательства, повторные ремонты\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ebrand\u003c/code\u003e, \u003ccode\u003emodel\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eсправочники: id, name, code, is_active\u003c/td\u003e\u003ctd\u003eВместо свободного текста — для аналитики по маркам\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003erequest\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, request_no, client_id, device_id, defect_type_id, description, status_id, assignee_id, created_at, closed_at, total_amount, source\u003c/td\u003e\u003ctd\u003eЯдро: только то, что относится к самой заявке\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003erequest_service\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, request_id, service_id, quantity, unit_price, amount, performed_by, comment\u003c/td\u003e\u003ctd\u003eM2M с атрибутами на связи: любое число услуг, цены на момент оказания\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eservice\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eсправочник: id, code, name, category_id, default_price, is_active\u003c/td\u003e\u003ctd\u003eОтчётность по услугам, управление ценами\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003erequest_status_history\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, request_id, status_id, changed_at, changed_by, reason, duration_prev_sec\u003c/td\u003e\u003ctd\u003eИстория переходов для SLA и разборов\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eemployee\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, full_name, role, department_id, is_active\u003c/td\u003e\u003ctd\u003eВместо текстового «исполнитель»\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ework_note\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eid, request_id, author_id, created_at, text, note_type\u003c/td\u003e\u003ctd\u003eКомментарии отдельной сущностью: их может быть много, и у них есть автор и время\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003ch3\u003e2. Обоснование нормальных форм\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003e1НФ:\u003c/strong\u003e устраняем повторяющиеся группы «услуга1..3» и «телефон1..2» → связь \u003ccode\u003erequest_service\u003c/code\u003e и отдельные строки контактов. Устраняем множественные значения в одной ячейке («услуги перечислены через запятую в комментарии»).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003e2НФ:\u003c/strong\u003e все неключевые атрибуты зависят от полного ключа. Например, \u003ccode\u003eunit_price\u003c/code\u003e услуги зависит и от заявки, и от услуги → живёт в \u003ccode\u003erequest_service\u003c/code\u003e, а \u003ccode\u003edefault_price\u003c/code\u003e — в справочнике.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003e3НФ:\u003c/strong\u003e убираем транзитивные зависимости: название марки не хранится в заявке (заявка → device → model → brand), ФИО мастера — в \u003ccode\u003eemployee\u003c/code\u003e, название статуса — в справочнике статусов.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eДальше (BCNF/4НФ) не идём:\u003c/strong\u003e в схеме нет перекрывающихся функциональных зависимостей и независимых многозначных зависимостей, а дальнейшее дробление увеличит число JOIN на экранах без пользы для бизнеса. Осознанно останавливаемся на 3НФ.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e3. Осознанная денормализация\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003ccode\u003erequest.total_amount\u003c/code\u003e — сумма позиций. Держим как вычисляемое поле: обновляется триггером или на уровне приложения в одной транзакции с изменением позиций. Нужно для экранов списка заявок и для быстрой сверки с бухгалтерией (иначе SUM по 1,2 млн заявок на каждый экран).\u003c/li\u003e\u003cli\u003e\u003ccode\u003erequest_status_history.duration_prev_sec\u003c/code\u003e — длительность предыдущего статуса, чтобы SLA-отчёт не считал оконные функции по всей истории.\u003c/li\u003e\u003cli\u003eКонтроль согласованности: ночная сверка \u003ccode\u003etotal_amount\u003c/code\u003e против суммы позиций, расхождения — в алерт и очередь исправления.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e4. План переноса данных\u003c/h3\u003e\u003col\u003e\u003cli\u003e\u003cstrong\u003eПрофилирование (1–2 дня).\u003c/strong\u003e Скрипты-аудиты: сколько строк, доля пустых полей, варианты написания телефонов, дубли клиентов, распределение числа услуг, «мусор» в текстовых полях (например, услуги, записанные в комментарий). Результат — отчёт о качестве данных и список правил очистки.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eПравила очистки.\u003c/strong\u003e Телефон → канонический формат \u003ccode\u003e7XXXXXXXXXX\u003c/code\u003e (регулярка + нормализация кодов 8/7). Дубли клиентов: слияние по совпадению нормализованного телефона И (ФИО или адрес); при конфликте данных — правило приоритета (последняя заявка важнее) и ручной разбор неоднозначных пар (ожидаем 3–5% случаев, выгружаем мастеру данных). Марка/модель — маппинг строк в справочник с таблицей соответствий, нераспознанные — в «прочее» на ручную доработку.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eСкрипты миграции.\u003c/strong\u003e Отдельные шаги: создание целевых таблиц → наполнение справочников → перенос клиентов с дедупликацией (с сохранением таблицы соответствия \u003ccode\u003eold_client_id → new_client_id\u003c/code\u003e) → устройства → заявки → услуги (из «услуга1..3» и парсинг комментариев — с пометкой \u003ccode\u003emigrated_from_comment = true\u003c/code\u003e) → история статусов (восстановить нельзя: создаём одну запись «статус на дату миграции» с пометкой \u003ccode\u003eis_historical = true\u003c/code\u003e и честно говорим бизнесу, что история начинается с даты миграции).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eПроверка.\u003c/strong\u003e Сверка: количество заявок до/после, суммы по всем заявкам, суммы в разрезе месяца, число клиентов после дедупликации, выборочная ручная проверка 50 заявок. Автоматические проверки целостности: нет заявок без клиента, нет услуг с нулевой ценой (кроме гарантийных), все FK валидны.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eВыполнение.\u003c/strong\u003e Двойная запись (shadow) — не нужна, схема меняется радикально. Вариант: пятница вечер, бэкап, миграция на копии (прогоняем заранее и замеряем время), затем боевой прогон. Целевое окно ≤ 30 минут достигается тем, что основной объём (справочники, клиенты, устройства, исторические заявки) переносится \u003cstrong\u003eзаранее\u003c/strong\u003e в фоновом режиме, а в окно простоя — только дельта за последние сутки и переключение приложения.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eОткат.\u003c/strong\u003e До переключения приложения — просто не переключаемся (старая таблица не тронута). После переключения — возврат на старую схему возможен в течение 3 суток, пока включена обратная синхронизация новых заявок в legacy-таблицу; далее откат = аварийная процедура, поэтому держим 3 дня наблюдения.\u003c/li\u003e\u003c/ol\u003e\u003ch3\u003e5. Влияние на пользователей\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eПриёмщик:\u003c/strong\u003e экран создания заявки остаётся одностраничным; вместо трёх полей «услуга» — добавление строк с автодополнением из справочника (быстрее, чем раньше). Клиент находится по телефону с автоматическим определением дублей — приёмщик видит предупреждение «похоже, это тот же клиент».\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eМастер:\u003c/strong\u003e видит историю статусов и все работы по устройству (раньше — только текущую заявку).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eРуководитель:\u003c/strong\u003e отчёты по услугам, загрузке мастеров, SLA по статусам, повторным ремонтам — всё то, что раньше считалось вручную.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eБухгалерия:\u003c/strong\u003e сверка сумм по заявкам и услугам без ручной выборки; гарантированно совпадает с \u003ccode\u003etotal_amount\u003c/code\u003e благодаря ночной сверке.\u003c/li\u003e\u003cli\u003eОбучение: 30-минутный брифинг для приёмщиков + инструкция с картинками; пилот на одном сервисном центре неделю до общего включения.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e6. Что станет возможным (и зачем всё это)\u003c/h3\u003e\u003cul\u003e\u003cli\u003eВыручка в разрезе услуг, мастеров, марок, географии — одним запросом.\u003c/li\u003e\u003cli\u003eSLA по этапам: сколько заявка ждала мастера, сколько была в работе.\u003c/li\u003e\u003cli\u003eПовторные обращения по одному устройству (признак качества ремонта).\u003c/li\u003e\u003cli\u003eПрогноз загрузки и планирование запчастей по маркам.\u003c/li\u003e\u003cli\u003eПерсональная история клиента: «обращался трижды, всегда по одной модели».\u003c/li\u003e\u003c/ul\u003e","mermaid":"erDiagram\n  CLIENT ||--o{ REQUEST : \"подаёт\"\n  CLIENT ||--o{ DEVICE : \"владеет\"\n  CLIENT }o--|| ADDRESS : \"проживает\"\n  DEVICE ||--o{ REQUEST : \"ремонтируется\"\n  BRAND ||--o{ MODEL : \"включает\"\n  MODEL ||--o{ DEVICE : \"определяет\"\n  REQUEST ||--o{ REQUEST_SERVICE : \"содержит\"\n  SERVICE ||--o{ REQUEST_SERVICE : \"оказывается\"\n  REQUEST ||--o{ REQUEST_STATUS_HISTORY : \"меняет статус\"\n  STATUS ||--o{ REQUEST_STATUS_HISTORY : \"фиксируется\"\n  REQUEST ||--o{ WORK_NOTE : \"комментируется\"\n  EMPLOYEE ||--o{ REQUEST : \"исполняет\"\n  EMPLOYEE ||--o{ REQUEST_STATUS_HISTORY : \"меняет\"\n  DEFECT_TYPE ||--o{ REQUEST : \"классифицирует\"\n\n  CLIENT {\n    bigint id PK\n    string phone_norm UK\n    string full_name\n    bigint address_id FK\n    bigint is_merged_into FK\n  }\n  REQUEST {\n    bigint id PK\n    string request_no UK\n    bigint client_id FK\n    bigint device_id FK\n    bigint status_id FK\n    bigint assignee_id FK\n    decimal total_amount\n    datetime created_at\n  }\n  REQUEST_SERVICE {\n    bigint id PK\n    bigint request_id FK\n    bigint service_id FK\n    int quantity\n    decimal unit_price\n    decimal amount\n  }\n  REQUEST_STATUS_HISTORY {\n    bigint id PK\n    bigint request_id FK\n    bigint status_id FK\n    bigint changed_by FK\n    datetime changed_at\n    int duration_prev_sec\n  }\n"}'::jsonb, updated_at = now() WHERE id = 'db-normalization';
UPDATE tasks SET statement = '{"brief":"Финансисты и коммерческий директор считают выручку по-разному и получают разные цифры. Нужна единая витрина.","context":["Компания продаёт подписки (B2B SaaS) и разовые услуги. Выручку сейчас считают в трёх местах: бухгалтерия — в учётной системе по закрытым актам, коммерческий отдел — в CRM по оплаченным счетам, аналитик — в Excel по выгрузке из биллинга. Цифры расходятся на 4–7%, и каждый месяц совет директоров начинается со спора «чья цифра правильная».","Задача: построить единую витрину данных по выручке с понятными правилами расчёта, качеством данных и SLA обновления.","Есть требования: признание выручки по методу начисления (не по оплате), разбивка по продуктам и сегментам клиентов, ретроспектива 3 года, обновления ежедневно к 9:00."],"goal":"Спроектировать витрину: источники, модель данных, бизнес-правила расчёта метрик, качество данных, SLA и процесс согласования определений.","inputs":["Источники: биллинг (подписки и платежи), CRM (сделки и клиенты), учётная система (акты и закрывающие документы), сервис поддержки (возвраты и претензии).","Расхождения: CRM считает выручкой оплаченный счёт, бухгалтерия — подписанный акт, биллинг — начисление по графику подписки.","Есть возвраты, скидки, многоэтапные сделки (пилот → продление), апгрейды подписки в середине периода, продажи через партнёров.","Потребители: CFO, коммерческий директор, совет директоров, продуктовые команды, финансисты для отчётности."],"deliverables":["Реестр метрик выручки с едиными определениями (что такое выручка, MRR/ARR, признанная выручка, отток) и владельцами определений.","Модель данных витрины: слои (источники → детальная → агрегаты), ключевые таблицы и измерения.","Правила расчёта для сложных случаев: апгрейд в середине месяца, возврат, скидка, партнёрская продажа, многолетний контракт.","Качество данных: проверки, классификация ошибок, что делать с «грязными» данными в отчёте.","SLA: время готовности, допустимая задержка, действия при сбое, кто уведомляется.","Процесс: как согласуются новые метрики, как решается спор о цифрах, как меняются определения во времени.","Как объяснять расхождение с бухгалтерской отчётностью (а не прятать его)."],"constraints":["Бухгалтерская отчётность остаётся источником истины для регулятора: витрина не подменяет её, а объясняет различия.","Источники не могут быть изменены быстро: CRM заполняют менеджеры как хотят.","Отчёт к 9:00 каждый день, включая дни закрытия месяца."],"interview":"«Три отдела считают выручку по-разному. Что вы сделаете как аналитик? И как спроектируете витрину?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Проект витрины","content":"\u003ch3\u003eРеестр метрик\u003c/h3\u003e\u003ch3\u003eМодель данных\u003c/h3\u003e\u003ch3\u003eСложные случаи\u003c/h3\u003e\u003ch3\u003eКачество и SLA\u003c/h3\u003e"},{"type":"mermaid","title":"Слои данных","content":"flowchart LR\n  B[Биллинг] --\u003e S[Staging]\n  C[CRM] --\u003e S\n  A[Учётная система] --\u003e S\n  SUP[Поддержка] --\u003e S\n  S --\u003e D[Детальный слой]\n  D --\u003e M[Витрина выручки]\n  M --\u003e R[Отчёты и дашборды]\n"}]'::jsonb, rubric = '[{"id":"metric-registry","title":"Реестр метрик с определениями, формулами, источниками и владельцами — до проектирования таблиц","weight":"high","weightValue":null,"focus":"sa","keywords":["реестр","словар","определен","глоссар","метри","владел","форму","согласован","единый"],"why":"Проблема не в таблицах, а в разных определениях. Начинать со схемы БД — классическая ошибка.","critical":false},{"id":"accrual-vs-cash","title":"Различие методов: начисление vs оплата vs закрытые документы, и какой метод для какой метрики","weight":"high","weightValue":null,"focus":"sa","keywords":["начислен","accrual","кассов","оплат","акт","закрыт","признан","revenue recognition","метод"],"why":"Все три цифры «правильные» в своём методе. Без явного разделения спор не разрешится никогда.","critical":false},{"id":"reconciliation","title":"Сверка с бухгалтерией: объяснение расхождений (bridge), а не подгонка цифр","weight":"high","weightValue":null,"focus":"sa","keywords":["сверк","reconcil","расхожден","bridge","объясн","бухгалтер","мост","разниц","регулятор"],"why":"Ограничение требует не подменять бухгалтерию. Мост «биллинг → бухгалтерия» с расшифровкой статей — ключевой артефакт.","critical":false},{"id":"layered-model","title":"Слоистая модель: staging → detail → aggregates (или raw/mart), воспроизводимость, идемпотентная пересборка","weight":"high","weightValue":null,"focus":"arch","keywords":["staging","слой","detail","детальн","aggregate","агрегат","mart","витрин","пересбор","идемпотент","raw"],"why":"Без слоёв любая правка источника ломает отчёты, а пересчёт истории невозможен.","critical":false},{"id":"dimensions","title":"Измерения: дата, продукт, сегмент клиента, канал/партнёр, версия бюджета; медленно меняющиеся измерения","weight":"mid","weightValue":null,"focus":"arch","keywords":["измерен","dimension","продукт","сегмент","партнёр","дата","scd","медленно меняющ","иерарх","snapshot"],"why":"Сегмент клиента меняется во времени: если хранить его как атрибут факта, история пересчитается задним числом.","critical":false},{"id":"hard-cases","title":"Правила для сложных случаев: апгрейд в середине периода, возврат, скидка, многолетний контракт, партнёрская продажа","weight":"high","weightValue":null,"focus":"sa","keywords":["апгрейд","возврат","скидк","многолетн","партнёр","proration","пропорц","amortiz","период","отток","churn"],"why":"Именно эти кейсы дают 4–7% расхождения. Общие слова «считаем по начислению» их не закрывают.","critical":false},{"id":"dq","title":"Качество данных: проверки на входе, классификация ошибок, изоляция «грязных» записей, видимость проблем в отчёте","weight":"high","weightValue":null,"focus":"sa","keywords":["качеств","dq","проверк","валидац","аномал","грязн","изоли","карантин","полнот","дубл"],"why":"CRM заполняют менеджеры как хотят — ограничение из условия. Без карантинной зоны отчёт будет молча врать.","critical":false},{"id":"sla-ops","title":"SLA и эксплуатация: время готовности, мониторинг пайплайна, действия при сбое, уведомления, деградация отчёта","weight":"mid","weightValue":null,"focus":"arch","keywords":["sla","к 9:00","готовност","мониторинг","алерт","сбой","деградац","runbook","дежурн","задержк"],"why":"Отчёт к 9:00 для совета директоров — жёсткое требование. Нужен процесс, а не надежда на планировщик.","critical":false},{"id":"governance","title":"Управление изменениями: как появляется новая метрика, кто утверждает, версионирование определений","weight":"mid","weightValue":null,"focus":"sa","keywords":["владел","утвержд","процесс","изменен","верси","governance","комитет","регламент","новый метрик"],"why":"Без процесса через полгода снова будет три разных цифры: каждый добавит «свою выручку».","critical":false},{"id":"adoption","title":"Внедрение: как заставить три отдела пользоваться одной витриной (миграция отчётов, отказ от Excel, обучение)","weight":"mid","weightValue":null,"focus":"sa","keywords":["внедрен","миграц","excel","отуч","дашборд","обучен","единственный источник","принят","пилот"],"why":"Технически правильная витрина, которой не пользуются, задачу не решает. Это организационная часть ответа.","critical":false}]'::jsonb, hints = '["Прежде чем проектировать таблицы, соберите определения. Сколько у вас получилось «выручек» и чем они отличаются?","Клиент перешёл с тарифа Basic на Pro 15-го числа. Как посчитать MRR за месяц? А признанную выручку?","Что делать с записью в CRM, где сумма сделки указана в тексте «примерно 300 тыс.»?"]'::jsonb, interview_questions = '["Чья цифра правильная: CRM, бухгалтерии или биллинга?","Как вы посчитаете выручку по многолетнему контракту с предоплатой?","Клиент вернул деньги через 2 месяца после оказания услуги. Что произойдёт с метриками?","Отчёт не успел собраться к 9:00. Ваши действия?","Коммерческий директор просит «показать выручку как в прошлом отчёте», но определение изменилось. Что делаете?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Реестр метрик (фрагмент)\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eМетрика\u003c/th\u003e\u003cth\u003eОпределение\u003c/th\u003e\u003cth\u003eМетод\u003c/th\u003e\u003cth\u003eИсточник\u003c/th\u003e\u003cth\u003eВладелец\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ebooked_revenue\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eСумма подписанных договоров/счетов за период, без учёта признания\u003c/td\u003e\u003ctd\u003eДоговорной\u003c/td\u003e\u003ctd\u003eCRM\u003c/td\u003e\u003ctd\u003eКоммерческий директор\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ebilled_revenue\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eНачисления биллинга по графикам подписок и актам разовых услуг\u003c/td\u003e\u003ctd\u003eНачисление\u003c/td\u003e\u003ctd\u003eБиллинг\u003c/td\u003e\u003ctd\u003eФинансовый контролёр\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003erecognized_revenue\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eВыручка, признанная по методу начисления (услуга оказана), с учётом amortization предоплат\u003c/td\u003e\u003ctd\u003eНачисление (МСФО/РСБУ)\u003c/td\u003e\u003ctd\u003eУчётная система + биллинг\u003c/td\u003e\u003ctd\u003eCFO\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ecash_revenue\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eФактически поступившие деньги\u003c/td\u003e\u003ctd\u003eКассовый\u003c/td\u003e\u003ctd\u003eБанк/биллинг\u003c/td\u003e\u003ctd\u003eКазначейство\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eMRR\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eЕжемесячная повторяющаяся выручка по активным подпискам на конец периода (proration по дням активности)\u003c/td\u003e\u003ctd\u003eНачисление\u003c/td\u003e\u003ctd\u003eБиллинг\u003c/td\u003e\u003ctd\u003eCFO\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eARR\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eMRR × 12 на конец периода\u003c/td\u003e\u003ctd\u003e—\u003c/td\u003e\u003ctd\u003eпроизводная\u003c/td\u003e\u003ctd\u003eCFO\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003enet_revenue\u003c/code\u003e\u003c/td\u003e\u003ctd\u003erecognized_revenue − возвраты − скидки − партнёрские комиссии\u003c/td\u003e\u003ctd\u003eНачисление\u003c/td\u003e\u003ctd\u003eвитрина\u003c/td\u003e\u003ctd\u003eCFO\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003echurn_revenue\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eMRR, потерянный из-за оттока (без учёта downgrades — они отдельной метрикой)\u003c/td\u003e\u003ctd\u003e—\u003c/td\u003e\u003ctd\u003eвитрина\u003c/td\u003e\u003ctd\u003eКоммерческий директор\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003cp\u003eКаждая метрика — запись в словаре с формулой, примером расчёта, историей изменений определения (версии и дата применения) и владельцем. Совет директоров смотрит \u003ccode\u003erecognized_revenue\u003c/code\u003e и \u003ccode\u003eMRR\u003c/code\u003e; коммерческий отдел — \u003ccode\u003ebooked_revenue\u003c/code\u003e и \u003ccode\u003eMRR\u003c/code\u003e; казначейство — \u003ccode\u003ecash_revenue\u003c/code\u003e. Все три доступны, но с явными подписями метода.\u003c/p\u003e\u003ch3\u003e2. Объяснение расхождений (bridge)\u003c/h3\u003e\u003cp\u003eОтдельный отчёт «мост»: \u003ccode\u003ebilled_revenue\u003c/code\u003e → \u003ccode\u003erecognized_revenue\u003c/code\u003e → бухгалтерская выручка. Статьи моста: неподписанные акты, выручка будущих периодов (предоплаты), возвраты и кредит-ноты, курсовые разницы, партнёрские комиссии, ручные корректировки бухгалтерии, межпериодные операции. Мост собирается из тех же детальных данных, поэтому любое расхождение раскрывается до конкретной сделки. Это снимает спор «чья цифра правильная»: все правильные, разница объяснена.\u003c/p\u003e\u003ch3\u003e3. Модель данных\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eRaw / staging:\u003c/strong\u003e копии источников без изменений (снапшоты на дату), история загрузок. Здесь данные «как пришли».\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eDetail (ядро):\u003c/strong\u003e согласованные сущности — \u003ccode\u003edim_date\u003c/code\u003e, \u003ccode\u003edim_customer\u003c/code\u003e (с SCType2 по сегменту), \u003ccode\u003edim_product\u003c/code\u003e, \u003ccode\u003edim_channel\u003c/code\u003e, \u003ccode\u003efact_invoice_line\u003c/code\u003e (позиции счетов), \u003ccode\u003efact_subscription_period\u003c/code\u003e (подписки по месяцам с proration), \u003ccode\u003efact_payment\u003c/code\u003e, \u003ccode\u003efact_credit_note\u003c/code\u003e (возвраты), \u003ccode\u003efact_revenue_recognition\u003c/code\u003e. Каждая факт-строка несёт \u003ccode\u003esource_system\u003c/code\u003e, \u003ccode\u003esource_id\u003c/code\u003e, \u003ccode\u003erule_version\u003c/code\u003e, \u003ccode\u003edq_status\u003c/code\u003e.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eAggregates (витрины):\u003c/strong\u003e \u003ccode\u003emv_revenue_daily\u003c/code\u003e (день × продукт × сегмент × канал × метод), \u003ccode\u003emv_mrr_monthly\u003c/code\u003e (с разложением на new / expansion / contraction / churn), \u003ccode\u003emv_bridge_monthly\u003c/code\u003e. Агрегаты пересобираются идемпотентно за период: delete-insert по партиции даты, чтобы правки истории не требовали ручного вмешательства.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e4. Правила для сложных случаев\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eАпгрейд в середине месяца:\u003c/strong\u003e MRR считается по дням: старый тариф до даты изменения + новый после. В разложении MRR это contraction старого плана и expansion нового, а не «изменение». Для recognized_revenue — фактическое оказание по дням.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eВозврат:\u003c/strong\u003e кредит-нота уменьшает выручку периода, в котором оформлен возврат (не задним числом в прошлом периоде — иначе отчёты «поедут»). Для MRR возврат подписки = churn в месяце возврата. Все возвраты видны отдельной строкой в мосте.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eСкидка:\u003c/strong\u003e хранится как атрибут позиции счёта (\u003ccode\u003ediscount_amount\u003c/code\u003e, \u003ccode\u003ediscount_reason_code\u003c/code\u003e), валовая и чистая выручка — отдельные меры. Отчёт «выручка до скидок» и «net» доступны оба, по умолчанию — net.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eМноголетний контракт с предоплатой:\u003c/strong\u003e деньги — \u003ccode\u003ecash_revenue\u003c/code\u003e в момент оплаты; признание — по графику оказания (равномерно или по факту этапов), разница — «выручка будущих периодов» (deferred) в мосте.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eПартнёрская продажа:\u003c/strong\u003e выручка — по цене для клиента; комиссия партнёра — в расходах, а не в уменьшении выручки (если по учётной политике так); в витрине есть измерение \u003ccode\u003echannel = partner\u003c/code\u003e и мера \u003ccode\u003epartner_commission\u003c/code\u003e, чтобы коммерческий директор видел net-эффект.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eПилот → продление:\u003c/strong\u003e пилот со скидкой 100% не входит в MRR; при конверсии начинается new MRR. Правило фиксируется в \u003ccode\u003erule_version\u003c/code\u003e, чтобы старые отчёты не пересчитывались.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e5. Качество данных\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eПрофили и проверки на входе:\u003c/strong\u003e полнота (обязательные поля сделки: сумма, дата, клиент, продукт), валидность (сумма \u0026gt; 0, дата в допустимом диапазоне, валюта из справочника), уникальность (нет дублей счетов по \u003ccode\u003esource_id\u003c/code\u003e), согласованность (сделка в CRM имеет счёт в биллинге; счёт имеет акт или причину отсутствия), своевременность (источник прислал данные за сутки).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eКлассификация ошибок:\u003c/strong\u003e \u003cem\u003eблокер\u003c/em\u003e (нет суммы счёта, дубль) — запись в карантин, в отчёт не попадает, задача владельцу источника; \u003cem\u003eпредупреждение\u003c/em\u003e (нет сегмента клиента) — попадает в отчёт с меткой «не классифицировано» отдельной строкой; \u003cem\u003eкосметика\u003c/em\u003e (разные написания названий) — маппинг справочником.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eКарантин виден:\u003c/strong\u003e в отчёте строка «Не распределено из-за качества данных: N записей на сумму X» — цифра выручки не «съезжает» молча. Доля карантина — KPI качества, цель \u0026lt; 0,5%.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eПравила для «грязной» CRM:\u003c/strong\u003e текстовые суммы не парсим молча — сделка уходит в карантин с задачей менеджеру; обязательность полей внедряется в CRM как отдельная инициатива с бизнес-обоснованием (аналитик готовит список полей и цену ошибки).\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e6. SLA и эксплуатация\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eГотовность:\u003c/strong\u003e витрина собрана к 07:30, отчёты опубликованы к 08:00, буфер до дедлайна 9:00. Пайплайн стартует в 02:00 после получения снапшотов источников.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eМониторинг:\u003c/strong\u003e статус каждого шага (время начала/конца, объём строк), алерты: шаг упал, шаг идёт дольше обычного в 2 раза, объём строк отклоняется от медианы на ±30%, карантин \u0026gt; 1%, готовность позже 08:00.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eДействия при сбое:\u003c/strong\u003e runbook для дежурного (перезапуск шага, пересборка периода), если к 08:30 данных нет — публикация отчёта с пометкой «данные на вчерашний день, обновление задерживается» + уведомление CFO и подписчиков. Никогда не публикуем silently stale данные.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЗакрытие месяца:\u003c/strong\u003e отдельный регламент: витрина не публикуется как финальная до закрытия периода бухгалтерией (T+3 рабочих дня); до этого — статус «предварительно». Финальная версия помечается и не меняется; корректировки — новым периодом с объяснением.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e7. Управление и внедрение\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eНовая метрика:\u003c/strong\u003e заявка → черновик определения (формула, источник, пример, граничные случаи) → согласование владельцем метрики и CFO для финансовых → публикация в словаре с версией → реализация. Без записи в словаре метрика в отчёт не попадает.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eИзменение определения:\u003c/strong\u003e только новой версией с датой применения; исторические отчёты пересчитываются только по решению владельца метрики, с уведомлением всех потребителей и строкой «пересчитано по правилам vX».\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eВнедрение:\u003c/strong\u003e пилот с финансовым отделом (1 месяц, сверка с их Excel), затем перевод отчёта для совета директоров на витрину с сохранением старой версии на квартал параллельно; обучение и поддержка; официальный отказ от Excel-выгрузок как источника цифр (приказ + отключение ручных выгрузок). Критерий успеха: три месяца подряд расхождение между отчётами отделов = 0, вопросы «чья цифра верная» на совете не поднимаются.\u003c/li\u003e\u003c/ul\u003e","mermaid":"flowchart LR\n  subgraph Sources[\"Источники\"]\n    B[Биллинг]\n    C[CRM]\n    A[Учётная система]\n    S[Поддержка: возвраты]\n    BN[Банк: платежи]\n  end\n  subgraph Raw[\"Raw / Staging\"]\n    R1[Снапшоты источников]\n    R2[Журнал загрузок]\n  end\n  subgraph DQ[\"Качество данных\"]\n    Q1[Проверки: полнота, дубли, валюта]\n    Q2[Карантин + задачи владельцам]\n  end\n  subgraph Detail[\"Detail layer\"]\n    D1[dim_date / dim_customer SCD2]\n    D2[dim_product / dim_channel]\n    F1[fact_invoice_line]\n    F2[fact_subscription_period]\n    F3[fact_credit_note]\n    F4[fact_revenue_recognition]\n  end\n  subgraph Mart[\"Витрины\"]\n    M1[mv_revenue_daily]\n    M2[mv_mrr_monthly]\n    M3[mv_bridge_monthly]\n  end\n  B --\u003e R1\n  C --\u003e R1\n  A --\u003e R1\n  S --\u003e R1\n  BN --\u003e R1\n  R1 --\u003e Q1\n  Q1 --\u003e Q2\n  Q1 --\u003e F1\n  Q1 --\u003e F2\n  Q1 --\u003e F3\n  F1 --\u003e F4\n  D1 --\u003e M1\n  D2 --\u003e M1\n  F4 --\u003e M1\n  F2 --\u003e M2\n  M1 --\u003e M3\n  M1 --\u003e RPT[Отчёты CFO / совета]\n  M2 --\u003e RPT\n  M3 --\u003e RPT\n  M3 -.объяснение расхождений.-\u003e A\n"}'::jsonb, updated_at = now() WHERE id = 'db-dwh-metrics';
UPDATE tasks SET statement = '{"brief":"Историческую таблицу транзакций надо разбить на новую схему и перенести в другой кластер. Сервис работает 24/7.","context":["Финтех-компания. Таблица \u003ccode\u003etransactions\u003c/code\u003e — 200 млн строк, 340 ГБ, растёт на 1,5 млн строк в сутки. Она живёт в одном кластере с операционной нагрузкой, запросы истории начали мешать оформлению платежей.","Решено: перейти на новую схему (другая структура полей, разделение на таблицу операций и таблицу проводок) и перенести данные в отдельный кластер, оптимизированный под чтение истории.","Простой сервиса недопустим: платежи идут круглосуточно, пик — будни 10:00–14:00. Окно на миграцию — 3 месяца, команда 2 разработчика и аналитик."],"goal":"Составить план миграции: целевая схема и маппинг, стратегия переноса (батчи/CDC), обеспечение согласованности, валидация, переключение, откат, эксплуатация во время миграции.","inputs":["Новая схема: \u003ccode\u003eoperations\u003c/code\u003e (операция: клиент, сумма, статус, тип) + \u003ccode\u003epostings\u003c/code\u003e (проводки по операции: счёт, сумма, направление) — нормализация «одна операция → много проводок».","В старой таблице проводки лежат в двух колонках \u003ccode\u003edebit_account\u003c/code\u003e/\u003ccode\u003ecredit_account\u003c/code\u003e, а для многосторонних операций — в JSON-поле \u003ccode\u003eextra_postings\u003c/code\u003e (заполнено у 8% строк).","Часть исторических данных неконсистентна: 0,3% строк имеют нулевую сумму, 120 тысяч строк — статус, которого нет в новом справочнике.","Требование: после миграции история должна читаться с той же производительностью или лучше, а данные — совпадать с источником построчно."],"deliverables":["Маппинг полей и трансформации, включая разбор JSON-проводок и обработку неконсистентных данных.","Стратегия переноса: исторический батч + инкремент (CDC или двойная запись), порядок, управление нагрузкой на источник.","Обеспечение согласованности: как не потерять и не задвоить строки при работающем сервисе, точка пересечения батча и инкремента.","Валидация: сверки (объёмы, суммы, контрольные выборки), критерии приёмки каждого этапа.","Переключение чтения и записи: этапы, feature flags, канарейка, точка невозврата.","План отката на каждом этапе и критерии его запуска.","Эксплуатация: мониторинг прогресса, оценка сроков, действия при деградации источника, коммуникация с командой поддержки.","Риски и как их снижаем."],"constraints":["Простой недопустим. Нагрузка на исходный кластер во время миграции не должна превышать +15% по CPU/IO.","Окно 3 месяца, 2 разработчика.","Финансовые данные: расхождение даже в одну строку недопустимо, требуется аудиторский след миграции."],"interview":"«Как вы перенесёте 200 млн строк в новую схему без простоя и как докажете, что ничего не потерялось?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"План миграции","content":"\u003ch3\u003eМаппинг и трансформации\u003c/h3\u003e\u003ch3\u003eСтратегия переноса\u003c/h3\u003e\u003ch3\u003eВалидация\u003c/h3\u003e\u003ch3\u003eПереключение и откат\u003c/h3\u003e"},{"type":"plantuml","title":"Этапы и потоки","content":"@startuml\ndatabase \"Источник: transactions\\n200M строк\" as SRC\nnode \"Мигратор (батчи)\" as MIG\nqueue \"CDC / двойная запись\" as CDC\ndatabase \"Цель: operations + postings\" as DST\nrectangle \"Сервис платежей\" as APP\n\nSRC -\u003e MIG : исторический перенос\nSRC -\u003e CDC : изменения онлайн\nCDC -\u003e DST : инкремент\nMIG -\u003e DST : батчи\nAPP -\u003e SRC : запись (пока)\nAPP -\u003e DST : чтение (канарейка)\n@enduml\n"}]'::jsonb, rubric = '[{"id":"mapping","title":"Маппинг полей и трансформации: нормализация проводок, разбор JSON, справочник статусов, правила для аномалий","weight":"high","weightValue":null,"focus":"sa","keywords":["маппинг","mapping","трансформ","json","extra_postings","debit","credit","проводк","справочник статус","преобразован"],"why":"Переход «плоская таблица → operations + postings» с JSON у 8% строк — это содержательная работа аналитика, а не «скопируем select-ом».","critical":false},{"id":"dirty-data","title":"Обработка неконсистентных данных: нулевые суммы, неизвестные статусы — правила, карантин, согласование с бизнесом","weight":"high","weightValue":null,"focus":"sa","keywords":["нулев","неконсист","аномал","карантин","грязн","неизвестн","исключен","правило","ручн","согласован","0,3%"],"why":"Условие даёт конкретные проценты мусора. Без явных правил мигратор либо упадёт, либо молча перенесёт неверные данные.","critical":false},{"id":"strategy","title":"Стратегия: исторический батч + инкремент (CDC или двойная запись), точка пересечения, порядок обработки","weight":"high","weightValue":null,"focus":"arch","keywords":["cdc","debezium","wal","двойн","батч","инкремент","backfill","точка пересечен","snapshot","binlog"],"why":"Нельзя «остановить и скопировать»: сервис работает. Нужны два потока и их согласование.","critical":false},{"id":"idempotency","title":"Идемпотентность переноса: ключ строки, upsert, защита от дублей при повторном запуске батча","weight":"high","weightValue":null,"focus":"arch","keywords":["идемпотент","upsert","on conflict","дубл","ключ","повторн","перезапуск","unique"],"why":"Батчи будут перезапускать после сбоев. Без идемпотентности получим двойные проводки в финансовых данных.","critical":false},{"id":"throttling","title":"Управление нагрузкой на источник: размер батча, паузы, ограничение по CPU/IO, работа в низконагруженное окно","weight":"high","weightValue":null,"focus":"arch","keywords":["throttl","нагрузк","батч размер","пауз","ограничен","io","cpu","ночн","окно","adaptive","скорост"],"why":"Ограничение +15% по CPU/IO — конкретное требование. Миграция, убившая прод, хуже несделанной миграции.","critical":false},{"id":"validation","title":"Валидация: сверка объёмов и сумм по партиям, контрольные суммы, выборочная построчная проверка, независимый аудит","weight":"high","weightValue":null,"focus":"sa","keywords":["сверк","валидац","контрольн","checksum","сумм","объём","выборк","аудит","reconcil","построчно"],"why":"Финансовые данные: «вроде перенесли» не принимается. Нужны многоуровневые сверки с числами.","critical":false},{"id":"cutover","title":"Переключение: чтение через канарейку/сравнение, затем запись, feature flags, критерии каждого шага","weight":"high","weightValue":null,"focus":"sa","keywords":["переключен","cutover","канаре","flag","чтен","запис","shadow","сравнен","этап","критер"],"why":"Переключение «в один момент» на финансовых данных — неприемлемый риск. Нужны шаги с измеримыми критериями.","critical":false},{"id":"rollback","title":"Откат на каждом этапе: условия, механика, сохранение обратной записи, точка невозврата","weight":"high","weightValue":null,"focus":"arch","keywords":["откат","rollback","обратн","двусторонн","точка невозврата","услов","вернуть","deprecat"],"why":"Без отката каждый шаг — ставка на удачу. Аудитория спросят: «а если пойдёт не так?»","critical":false},{"id":"audit-trail","title":"Аудиторский след миграции: журнал перенесённых партий, правила трансформаций и их версии, отчёт о расхождениях","weight":"mid","weightValue":null,"focus":"sa","keywords":["аудит","журнал","след","traceab","верси правил","отчёт","документ","протокол","миграцион"],"why":"Финтех + требование аудиторского следа из условия. Миграция должна быть воспроизводима и объяснима задним числом.","critical":false},{"id":"monitoring","title":"Мониторинг прогресса: скорость, ETA, лаг инкремента, ошибки по типам, дашборд миграции","weight":"mid","weightValue":null,"focus":"arch","keywords":["мониторинг","прогресс","eta","лаг","скорост","дашборд","метри","ошибк","статус"],"why":"3 месяца миграции без метрик = сюрприз на 89-й день. Нужен прогноз завершения и ранние сигналы проблем.","critical":false},{"id":"timeline","title":"Реалистичная оценка сроков и ресурсов: расчёт пропускной способности, этапы, буфер","weight":"mid","weightValue":null,"focus":"sa","keywords":["срок","оценк","часов","дней","буфер","ресурс","производительн","строк в секунду","план-график"],"why":"Окно 3 месяца и 2 разработчика: надо посчитать, физически ли успеем (200 млн строк / X строк в секунду).","critical":false}]'::jsonb, hints = '["Посчитайте: 200 млн строк при 5 000 строк/сек — это сколько часов? А при ограничении нагрузки на источник?","Инкремент может идти через CDC по WAL или через двойную запись в приложении. Чем они отличаются по рискам?","Точка пересечения: батч дошёл до строки N, а CDC уже принёс изменения строки N-100. Как не потерять более свежую версию?"]'::jsonb, interview_questions = '["Как вы докажете, что перенеслись все 200 млн строк и суммы совпадают?","Батч упал на середине. Что произойдёт при перезапуске?","Как переключите запись без простоя и когда наступит точка невозврата?","Строка со статусом, которого нет в новом справочнике. Ваши действия?","Нагрузка на источник выросла на 25%. Что делаете?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Маппинг и трансформации\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eИсточник\u003c/th\u003e\u003cth\u003eЦель\u003c/th\u003e\u003cth\u003eПравило\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003etransactions.id\u003c/code\u003e\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eoperations.id\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eПереносим как есть (сохраняем внешние ссылки и историю). Новый PK не вводим — иначе сломаются интеграции\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eclient_id, amount, currency, type, status, created_at\u003c/code\u003e\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eoperations.*\u003c/code\u003e\u003c/td\u003e\u003ctd\u003e1:1, статус — через справочник (см. ниже)\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003edebit_account\u003c/code\u003e / \u003ccode\u003ecredit_account\u003c/code\u003e\u003c/td\u003e\u003ctd\u003e\u003ccode\u003epostings\u003c/code\u003e (2 строки)\u003c/td\u003e\u003ctd\u003eДебет: направление=D, сумма=amount; Кредит: направление=C, сумма=amount. Постинги получают \u003ccode\u003eoperation_id\u003c/code\u003e и \u003ccode\u003eposting_seq\u003c/code\u003e (1, 2)\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003eextra_postings\u003c/code\u003e (JSON, 8% строк)\u003c/td\u003e\u003ctd\u003e\u003ccode\u003epostings\u003c/code\u003e (N строк)\u003c/td\u003e\u003ctd\u003eПарсим JSON-массив, каждая запись → posting с \u003ccode\u003eposting_seq\u003c/code\u003e продолжая нумерацию. Валидация: сумма дебетов = сумма кредитов; иначе — карантин\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003emigrated_at, migration_batch_id, rule_version\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eслужебные поля цели\u003c/td\u003e\u003ctd\u003eДля аудиторского следа и повторного разбора\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003cp\u003e\u003cstrong\u003eПравила для аномалий (согласованы с бизнесом и фиксированы документально):\u003c/strong\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eНулевая сумма (0,3% ≈ 600 тыс. строк):\u003c/strong\u003e анализируем выборку — это технические/отменённые операции. Правило: переносим с типом \u003ccode\u003eZERO_AMOUNT\u003c/code\u003e и признаком \u003ccode\u003erequires_review = true\u003c/code\u003e, в отчётности по выручке не участвуют. Не удаляем: финансовые данные уничтожать нельзя без решения владельцев.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eНеизвестный статус (120 тыс. строк):\u003c/strong\u003e строим таблицу соответствия «старый статус → новый» по фактическому распределению; нераспознанные (ожидаем \u0026lt; 5 тыс.) маппим в \u003ccode\u003eLEGACY_UNKNOWN\u003c/code\u003e с сохранением исходного значения в \u003ccode\u003eraw_status\u003c/code\u003e. Новый справочник содержит служебное значение именно для миграции, в UI оно не показывается.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eНебаланс проводок (дебет ≠ кредит):\u003c/strong\u003e запись в карантин, отдельный отчёт, разбор с бухгалтерией до переключения. В цель не переносим до решения.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eБитый JSON в \u003ccode\u003eextra_postings\u003c/code\u003e:\u003c/strong\u003e карантин + сохранение исходной строки в \u003ccode\u003eraw_extra\u003c/code\u003e, чтобы разобрать позже.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e2. Стратегия переноса\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eДва потока:\u003c/strong\u003e\u003c/p\u003e\u003col\u003e\u003cli\u003e\u003cstrong\u003eИсторический батч (backfill).\u003c/strong\u003e Читаем источник партициями по диапазону \u003ccode\u003eid\u003c/code\u003e (а не OFFSET — иначе деградация на больших смещениях), размер батча 5 000 строк, пауза между батчами адаптивная. Порядок — от старых к новым. Каждая партия: чтение → трансформация → upsert в цель → запись в \u003ccode\u003emigration_batches\u003c/code\u003e (batch_id, диапазон, число строк, контрольная сумма, время, статус, ошибки). Читаем с read-реплики источника, чтобы не грузить мастера.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eИнкремент.\u003c/strong\u003e Вариант A (выбираем): \u003cstrong\u003eCDC по WAL\u003c/strong\u003e (Debezium → Kafka → коннектор в цель). Плюсы: не трогаем код сервиса, ловим все изменения включая удаления, минимальный риск расхождения. Минусы: нужна инфраструктура Kafka и схема-реестр, задержка секунды. Вариант B: двойная запись в приложении — отклоняем: требует изменения кода в критическом пути платежей, риск рассинхрона при частичном сбое записи.\u003c/li\u003e\u003c/ol\u003e\u003cp\u003e\u003cstrong\u003eТочка пересечения:\u003c/strong\u003e CDC стартует \u003cem\u003eдо\u003c/em\u003e начала батча (с фиксацией LSN-позиции), поэтому все изменения, происходящие во время backfill, уже попадают в цель. Конфликт версий решаем правилом: \u003cstrong\u003eCDC всегда приоритетнее батча\u003c/strong\u003e (в целевой таблице сравниваем \u003ccode\u003esource_updated_at\u003c/code\u003e/версию строки и не перезаписываем более свежую данными батча). Upsert батча выполняется с условием \u003ccode\u003eWHERE target.source_updated_at IS NULL OR target.source_updated_at \u0026lt; excluded.source_updated_at\u003c/code\u003e.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eУдаления:\u003c/strong\u003e CDC воспроизводит удаления. В финансовой истории физические удаления маловероятны (обычно статусная отмена), но обрабатываем: удалённая в источнике строка помечается в цели \u003ccode\u003edeleted_at\u003c/code\u003e, а не стирается — так остаётся след.\u003c/p\u003e\u003ch3\u003e3. Нагрузка на источник и сроки\u003c/h3\u003e\u003cul\u003e\u003cli\u003eОграничение: батч потребляет не более 15% CPU/IO реплики. Реализация: адаптивный троттлинг — измеряем длительность батча и время ожидания реплики (replication lag), при росте лага \u0026gt; 5 сек увеличиваем паузу, при стабильности — уменьшаем. Плюс жёсткий лимит: не более 5 000 строк/сек и окно интенсивного переноса 00:00–06:00 (днём — 1 000 строк/сек).\u003c/li\u003e\u003cli\u003eОценка: 200 млн строк при средней скорости 3 500 строк/сек (ночью 5 000, днём 1 000, средневзвешенно с учётом окон) ≈ 16 часов чистого времени; реалистично с трансформациями, паузами и повторами — \u003cstrong\u003e10–14 календарных дней\u003c/strong\u003e. Это даёт большой буфер в 3-месячном окне: основные сроки уйдут на валидацию, согласование правил и переключение, а не на копирование.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e4. Валидация (четыре уровня)\u003c/h3\u003e\u003col\u003e\u003cli\u003e\u003cstrong\u003eОбъёмы:\u003c/strong\u003e по каждому дню \u003ccode\u003ecreated_at\u003c/code\u003e — число строк источника против числа операций в цели. Расхождение = 0 (кроме документированного карантина, который сверяется отдельным списком).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eСуммы:\u003c/strong\u003e сумма \u003ccode\u003eamount\u003c/code\u003e по дням и по валютам; сумма дебета и кредита по проводкам; баланс «дебет = кредит» по каждой операции (проверка SQL-агрегатом, а не построчно — быстро).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eКонтрольные суммы:\u003c/strong\u003e хэш по партиям (например, сумма хэшей ключевых полей, упорядоченных по id) — источник против цели. Позволяет локализовать расхождение до батча.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eВыборочная построчная:\u003c/strong\u003e случайная выборка 5 000 строк + обязательная выборка сложных кейсов (все типы аномалий, операции с \u003ccode\u003eextra_postings\u003c/code\u003e, крайние даты). Сравнение по всем полям после трансформации.\u003c/li\u003e\u003c/ol\u003e\u003cp\u003eВсе сверки автоматизированы и запускаются ежедневно во время миграции; результат — отчёт с трендом. Критерий приёмки этапа: 4 уровня зелёные 3 дня подряд.\u003c/p\u003e\u003ch3\u003e5. Переключение\u003c/h3\u003e\u003col\u003e\u003cli\u003e\u003cstrong\u003eЭтап A — тень чтения (2 недели).\u003c/strong\u003e Сервис продолжает читать и писать в источник. Параллельно 5% запросов истории дублируются в новую схему, результаты сравниваются (shadow compare), расхождения — в журнал. Пользователь видит только старые данные. Критерий: 0 функциональных расхождений на 1 млн сравнений; p95 времени чтения новой схемы не хуже старой.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЭтап B — чтение из новой схемы (2 недели).\u003c/strong\u003e Флаг переключает чтение истории на новый кластер: 5% → 25% → 100% пользователей (канарейка по сегментам). Старый кластер остаётся источником истины для записи. Критерий: нет роста обращений в поддержку, нет инцидентов, метрики чтения в норме.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЭтап C — запись в новую схему.\u003c/strong\u003e Самый рискованный шаг. Механика: включаем двойную запись (источник + цель) на 1 неделю с проверкой согласованности; затем флаг «основная запись — цель», источник продолжает получать запись как резерв ещё 2 недели; CDC разворачиваем в обратную сторону (цель → источник), чтобы откат оставался возможным. Критерий: 0 расхождений двойной записи за 7 дней.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eТочка невозврата:\u003c/strong\u003e через 4 недели стабильной записи в новую схему — обратный CDC и резервная запись в источник отключаются, старая таблица переводится в read-only архив. До этой точки откат доступен за минуты.\u003c/li\u003e\u003c/ol\u003e\u003ch3\u003e6. Откат\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eЭтап\u003c/th\u003e\u003cth\u003eУсловия отката\u003c/th\u003e\u003cth\u003eМеханика\u003c/th\u003e\u003cth\u003eВремя\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eA (тень чтения)\u003c/td\u003e\u003ctd\u003eДеградация источника, лаг репликации \u0026gt; 30 сек, рост ошибок\u003c/td\u003e\u003ctd\u003eВыключить теневое сравнение (флаг)\u003c/td\u003e\u003ctd\u003eсекунды\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eB (чтение из цели)\u003c/td\u003e\u003ctd\u003eРасхождение данных, ошибки UI, p95 хуже на 20%+\u003c/td\u003e\u003ctd\u003eФлаг обратно на источник\u003c/td\u003e\u003ctd\u003eсекунды\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eC (запись в цель)\u003c/td\u003e\u003ctd\u003eЛюбое расхождение двойной записи, инцидент с платежами\u003c/td\u003e\u003ctd\u003eФлаг на источник; данные цели восстанавливаются обратным CDC (он работает до точки невозврата)\u003c/td\u003e\u003ctd\u003eминуты\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eПосле точки невозврата\u003c/td\u003e\u003ctd\u003e—\u003c/td\u003e\u003ctd\u003eТолько вперёд: исправление данных в цели, процедура restore из архива источника (часы, с привлечением ДБО и аудиторов)\u003c/td\u003e\u003ctd\u003eчасы\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003ch3\u003e7. Мониторинг и коммуникация\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eДашборд миграции:\u003c/strong\u003e прогресс в % и строках, скорость (строк/сек), ETA, лаг CDC, размер карантина по типам аномалий, ошибки по категориям, нагрузка на источник (CPU/IO/replication lag), статус сверок.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eАлерты:\u003c/strong\u003e лаг CDC \u0026gt; 60 сек; батч упал дважды подряд; карантин вырос \u0026gt; 1% от партии; нагрузка на источник \u0026gt; +15%; расхождение сверки любого уровня.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eКоммуникация:\u003c/strong\u003e еженедельный статус заинтересованным сторонам (прогресс, риски, решения по аномалиям), канал для оперативных вопросов, инструкция поддержки «что отвечать клиенту, если история выглядит иначе» (в период канарейки возможны разные данные у разных пользователей — это ожидаемо и объяснимо).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eАудиторский след:\u003c/strong\u003e журнал партий, версия правил трансформации на каждую партию (\u003ccode\u003erule_version\u003c/code\u003e), отчёты сверок, протоколы решений по аномалиям с подписями владельцев данных. Всё хранится 5 лет.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e8. Риски\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eПравила трансформации неверны\u003c/strong\u003e (самый дорогой риск) → митигируем: прогон на выборке 1 млн строк до старта, ревью правил с бухгалтерией, shadow-сравнение на этапе A.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eНагрузка на источник убивает прод\u003c/strong\u003e → троттлинг, чтение с реплики, ночные окна, автоматическая пауза по лагу.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eКарантин окажется большим, чем ожидаем\u003c/strong\u003e → профилирование данных до старта (мы уже знаем 0,3% и 120 тыс., но проверяем распределение JSON и баланс проводок заранее).\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eСроки: 2 разработчика на 3 месяца\u003c/strong\u003e → этапы с независимой ценностью, автоматизация сверок с первой недели, отказ от самописного CDC в пользу готового решения.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eИзменение схемы источника во время миграции\u003c/strong\u003e (другая команда добавит колонку) → мораторий на DDL в таблице \u003ccode\u003etransactions\u003c/code\u003e на период миграции, зафиксированный приказом; при необходимости — пересмотр маппинга с новой версией правил.\u003c/li\u003e\u003c/ul\u003e","plantuml":"@startuml\ntitle Миграция: потоки и этапы\n\ndatabase \"Источник\\ntransactions 200M\" as SRC\ndatabase \"Read-реплика\" as REP\nnode \"Мигратор\\n(батчи по 5000)\" as MIG\nqueue \"Kafka + Debezium (CDC)\" as CDC\nnode \"Трансформатор\\nrule_version, карантин\" as TR\ndatabase \"Цель\\noperations + postings\" as DST\nrectangle \"Сервис платежей\" as APP\nrectangle \"Сверки и дашборд\" as VAL\n\nSRC --\u003e REP : потоковая репликация\nREP --\u003e MIG : чтение партициями по id\nMIG --\u003e TR\nSRC ..\u003e CDC : WAL (стартует до батча)\nCDC --\u003e TR\nTR --\u003e DST : upsert с приоритетом свежей версии\nTR --\u003e VAL : журнал партий, контрольные суммы\nVAL --\u003e DST : 4 уровня сверки\nAPP -\u003e SRC : запись (этапы A, B)\nAPP -\u003e DST : чтение (канарейка на этапе B)\nAPP -\u003e DST : двойная запись (этап C)\nDST ..\u003e SRC : обратный CDC до точки невозврата\nnote bottom of TR\n  Аномалии:\n  нулевые суммы -\u003e ZERO_AMOUNT + requires_review\n  неизвестный статус -\u003e LEGACY_UNKNOWN (raw_status сохранён)\n  небаланс проводок -\u003e карантин + разбор с бухгалтерией\nend note\n@enduml\n"}'::jsonb, updated_at = now() WHERE id = 'db-migration';
UPDATE tasks SET statement = '{"brief":"Директор сказал: «Сделайте как у X, у них клиенты в восторге». Через две недели разработка хочет задачи в спринт.","context":["Вы аналитик в компании, которая продаёт онлайн-курсы. На встрече директор по маркетингу сказал: «У конкурента X появилась персональная подборка курсов на главной. Клиенты в восторге, конверсия растёт. Нам надо так же, в следующем квартале».","Других деталей нет: неизвестно, что именно делает X, зачем это нам, какие данные у нас есть, кто будет поддерживать подборки, как измерять эффект.","Через две недели планирование спринта: команде разработки нужны задачи, иначе квартал «встанет»."],"goal":"Превратить расплывчатую идею в проработанные требования: выяснить цель, определить скоуп первой версии, описать user stories с критериями приёмки и зафиксировать открытые вопросы.","inputs":["Что известно: у нас 400 курсов, 180 тысяч пользователей, есть данные о просмотрах и покупках, есть категории и теги курсов.","Известно про X только со слов директора: «на главной показывают рекомендуемые курсы».","Нет: цели в метриках, ограничений по срокам и бюджету, понимания, кто владеет контентом подборок.","Команда: 2 разработчика, дизайнер на 20%, вы — аналитик."],"deliverables":["Список вопросов стейкхолдерам (не «что сделать», а «зачем и как измерим») и план их закрытия за две недели.","Формулировка цели и гипотезы: какую проблему решаем, для кого, как измерим успех.","Границы первой версии: что входит, что не входит и почему (явное «out of scope»).","3–5 user stories с критериями приёмки в проверяемом виде.","Основные и альтернативные сценарии (минимум: нет данных о пользователе, новый пользователь, пользователь не согласен на персонализацию, подборка пустая).","Нефункциональные требования, которые важны уже в первой версии.","Риски и открытые вопросы с владельцами и сроками."],"constraints":["Срок — две недели на аналитику, затем планирование спринта.","Нельзя обещать «как у X»: мы не знаем, что именно у них и какие у них данные.","Персонализация затрагивает данные о поведении пользователей: нужны основания и согласия."],"interview":"«Вам сказали „сделайте как у конкурента“. Ваши действия? Что вы принесёте на планирование через две недели?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Требования","content":"\u003ch3\u003eЦель и гипотеза\u003c/h3\u003e\u003ch3\u003eВопросы стейкхолдерам\u003c/h3\u003e\u003ch3\u003eСкоуп MVP\u003c/h3\u003e\u003ch3\u003eUser stories и критерии приёмки\u003c/h3\u003e\u003ch3\u003eРиски\u003c/h3\u003e"},{"type":"mermaid","title":"Сценарий пользователя","content":"flowchart TD\n  A[Пользователь заходит на главную] --\u003e B{Есть данные о поведении?}\n  B --\u003e|да| C[Показываем персональную подборку]\n  B --\u003e|нет| D[Показываем подборку по умолчанию]\n  C --\u003e E{Кликнул?}\n  D --\u003e E\n  E --\u003e|да| F[Переход на курс]\n  E --\u003e|нет| G[Что меняем?]\n"}]'::jsonb, rubric = '[{"id":"why-first","title":"Выяснение цели и бизнес-проблемы до проектирования решения; вопросы «зачем», а не «что сделать»","weight":"high","weightValue":null,"focus":"sa","keywords":["зачем","цель","проблем","гипотез","метри","зачем нам","конверс","бизнес-задач","интервью"],"why":"«Как у конкурента» — не требование. Без цели невозможно выбрать скоуп и понять, что успех.","critical":false},{"id":"hypothesis-metrics","title":"Измеримая гипотеза и метрики успеха: целевое значение, срок, как считаем, как не обманываем себя","weight":"high","weightValue":null,"focus":"sa","keywords":["гипотез","метри","конверс","ctr","arpu","удержан","baseline","целев","a/b","эксперимент"],"why":"Директор ссылается на «конверсия растёт». Наша версия должна иметь свою цифру и способ проверки.","critical":false},{"id":"stakeholder-questions","title":"Структурированные вопросы стейкхолдерам с владельцами и сроками закрытия","weight":"high","weightValue":null,"focus":"sa","keywords":["вопрос","стейкхолдер","уточнить","владел","срок","открыт","интервью","согласован"],"why":"Две недели — жёсткий срок. Вопросы должны быть конкретными и адресными, иначе время уйдёт впустую.","critical":false},{"id":"scope-boundaries","title":"Явные границы: что в первой версии, что НЕ входит и почему; критерий урезания скоупа","weight":"high","weightValue":null,"focus":"sa","keywords":["scope","mvp","первая верси","не входит","out of scope","границ","объем","урез","приоритет"],"why":"2 разработчика и квартал: без явного «не делаем» скоуп расползётся до ML-рекомендаций.","critical":false},{"id":"stories-ac","title":"User stories с проверяемыми критериями приёмки (дано/когда/тогда или измеримые утверждения)","weight":"high","weightValue":null,"focus":"sa","keywords":["user story","как пользователь","критери","приёмк","acceptance","дано","когда","тогда","given","when","then"],"why":"Разработка идёт в спринт: истории без критериев приёмки превращаются в споры на демо.","critical":false},{"id":"alt-scenarios","title":"Альтернативные и граничные сценарии: новый пользователь, нет данных, пустая подборка, отказ от персонализации","weight":"high","weightValue":null,"focus":"sa","keywords":["новый пользовател","нет данных","пуст","отказ","альтернативн","граничн","по умолчанию","cold start","согла","opt"],"why":"Самая частая причина «недоделанной» фичи — непродуманный cold start и пустые состояния.","critical":false},{"id":"privacy","title":"Данные о поведении: основание обработки, согласие, возможность отключить персонализацию, хранение","weight":"mid","weightValue":null,"focus":"sa","keywords":["согла","consent","персональн","152","данные поведен","отключить","opt-out","cookie","хранен","обезлич"],"why":"Ограничение прямо указывает на персонализацию. Игнорирование согласия = юридический риск и блокировка релиза.","critical":false},{"id":"nfr","title":"НФТ первой версии: время отклика главной страницы, доступность, поведение при деградации (фолбэк на статическую подборку)","weight":"mid","weightValue":null,"focus":"arch","keywords":["нфт","время отклик","200 мс","производительн","доступност","деградац","фолбэк","fallback","кэш","нагрузк"],"why":"Подборка на главной странице: если сервис рекомендаций тормозит, тормозит весь сайт.","critical":false},{"id":"ops-ownership","title":"Кто владеет контентом и правилами подборок: поддержка, маркетинг, ответственность за «странные» рекомендации","weight":"mid","weightValue":null,"focus":"sa","keywords":["владел","поддержк","маркетинг","ответств","админ","управлен","редактир","кто","процесс","регламент"],"why":"Персональные подборки требуют владельца правил. Без этого «почему мне показывают это» уходит в поддержку без ответа.","critical":false},{"id":"experiment-plan","title":"План проверки гипотезы: как измеряем, контрольная группа, срок, критерий остановки","weight":"mid","weightValue":null,"focus":"sa","keywords":["a/b","эксперимент","контрольн","групп","измер","срок","остановк","статзнач","сплит"],"why":"Без плана проверки мы через квартал не сможем сказать, сработало ли решение.","critical":false}]'::jsonb, hints = '["Начните с вопроса «какую проблему бизнеса мы решаем». Директор говорит про конверсию — какую именно и на каком шаге воронки?","Персональные рекомендации — дорого. Что можно сделать за две недели разработки и всё проверить гипотезу?","Каждый критерий приёмки должен быть проверяемым: «подборка релевантна» — не критерий, «показываем не более 6 курсов, из категорий, которые пользователь просматривал» — критерий."]'::jsonb, interview_questions = '["Какие три вопроса вы зададите директору первыми?","Что войдёт в первую версию, а что вы сознательно не будете делать?","Как вы поймёте через месяц, что фича сработала?","Новый пользователь без истории. Что он увидит на главной?","Разработка говорит «персонализация — это ML, минимум 3 месяца». Ваши действия?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Что выясняем до проектирования\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eВопросы директору по маркетингу (встреча 45 минут):\u003c/strong\u003e\u003c/p\u003e\u003col\u003e\u003cli\u003eКакую бизнес-проблему решаем: низкая конверсия из visits в покупку, низкая возвращаемость, или «нужно не отставать от рынка»?\u003c/li\u003e\u003cli\u003eКакая метрика для вас главная и какое целевое значение вы готовы защищать? (например, конверсия главной в покупку с 2,1% до 2,6% за 3 месяца)\u003c/li\u003e\u003cli\u003eЧто именно вы видели у X: скриншот, на каких данных это работает, есть ли у нас такие данные?\u003c/li\u003e\u003cli\u003eКто у нас будет владельцем подборок и правил: маркетинг или продукт?\u003c/li\u003e\u003cli\u003eКакой бюджет и срок: мы говорим про эксперимент за 2 недели разработки или про полноценную рекомендательную систему в квартале?\u003c/li\u003e\u003cli\u003eГотовы ли вы к A/B: половине пользователей показываем старую главную?\u003c/li\u003e\u003c/ol\u003e\u003cp\u003e\u003cstrong\u003eВопросы данным/разработке:\u003c/strong\u003e какие события поведения собираются (просмотры, добавления в корзину, покупки, поисковые запросы), за какой период, качество данных; есть ли теги и категории у всех 400 курсов; кто заполняет описания.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eВопросы юристу/ДПО:\u003c/strong\u003e основание обработки поведенческих данных для персонализации, нужно ли явное согласие, как реализуем opt-out, сроки хранения профиля.\u003c/p\u003e\u003ch3\u003e2. Цель и гипотеза\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eПроблема:\u003c/strong\u003e на главной странице сейчас общий список курсов, пользователь не видит релевантного продолжения — 68% визитов заканчиваются без клика по курсу (берём из аналитики до встречи, чтобы говорить цифрами).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eГипотеза:\u003c/strong\u003e «Если на главной показывать блок “Продолжить обучение” и “Похожее на просмотренное” из курсов той же категории/тега, что и недавняя активность пользователя, то конверсия главной в просмотр курса вырастет с 32% до 38%, а конверсия в покупку — с 2,1% до 2,4% за 8 недель».\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eПроверка:\u003c/strong\u003e A/B 50/50, минимум 4 недели, статистическая значимость 95%; метрики: CTR блока, конверсия в просмотр карточки, конверсия в покупку, доля пользователей, увидевших пустой блок (технологическая метрика), отписки/жалобы. Критерий остановки: падение конверсии в покупку более чем на 5% относительно контроля в первые 7 дней.\u003c/p\u003e\u003ch3\u003e3. Скоуп первой версии\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eДелаем:\u003c/strong\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eБлок «Продолжить обучение» (незавершённые курсы пользователя) — если есть активные записи.\u003c/li\u003e\u003cli\u003eБлок «Вам может подойти» — детерминированные правила: категории и теги последних 10 просмотренных курсов, исключение уже купленных, сортировка по популярности внутри категории.\u003c/li\u003e\u003cli\u003eФолбэк для нового пользователя: «Популярное в этом месяце» + «Новинки» (статическая подборка, которую редактирует маркетинг).\u003c/li\u003e\u003cli\u003eОтказ от персонализации в настройках профиля (opt-out) + согласие при первом визите согласно политике.\u003c/li\u003e\u003cli\u003eАналитика: показы блока, клики, позиция курса, пустые показы.\u003c/li\u003e\u003c/ul\u003e\u003cp\u003e\u003cstrong\u003eНЕ делаем (осознанно):\u003c/strong\u003e ML-рекомендации и коллаборативная фильтрация, рекомендации в письмах и push, персональные скидки, рекомендации на странице курса, перестройка главной. Обоснование: проверяем гипотезу «персонализация на главной повышает конверсию» минимальными средствами; если гипотеза подтвердится — вторая версия с ML будет обоснована цифрами.\u003c/p\u003e\u003ch3\u003e4. User stories и критерии приёмки\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eUS-1. Продолжить обучение.\u003c/strong\u003e Как возвращающийся пользователь, я хочу видеть на главной свои незавершённые курсы, чтобы не искать их в каталоге.\u003c/p\u003e\u003cul\u003e\u003cli\u003eДано: у пользователя есть ≥1 курс со статусом «в процессе». Когда: он открывает главную. Тогда: первым блоком показан «Продолжить обучение» с не более чем 3 курсами, отсортированными по дате последнего обращения, с прогрессом в процентах.\u003c/li\u003e\u003cli\u003eДано: незавершённых курсов больше 3. Тогда: видны первые 3 и ссылка «Все мои курсы».\u003c/li\u003e\u003cli\u003eДано: пользователь не авторизован. Тогда: блок не показывается (не показываем чужие данные на общем экране).\u003c/li\u003e\u003c/ul\u003e\u003cp\u003e\u003cstrong\u003eUS-2. Персональная подборка.\u003c/strong\u003e Как пользователь, я хочу видеть курсы, похожие на то, что я смотрел, чтобы быстрее найти подходящее.\u003c/p\u003e\u003cul\u003e\u003cli\u003eДано: у пользователя есть ≥3 просмотренных карточек курсов за 30 дней. Тогда: блок «Вам может подойти» содержит 6 курсов из тех же категорий/тегов, без уже купленных и без уже просмотренных полностью, упорядоченных по популярности за 30 дней.\u003c/li\u003e\u003cli\u003eДано: после исключения купленных осталось меньше 6 курсов. Тогда: показываем столько, сколько есть, и дополняем из «Популярного» (не показываем пустот).\u003c/li\u003e\u003cli\u003eДано: история просмотров отсутствует. Тогда: блок заменяется на «Популярное в этом месяце».\u003c/li\u003e\u003cli\u003eВремя формирования блока ≤ 200 мс на p95; при недоступности сервиса подборок показываем статический фолбэк, главная страница не деградирует.\u003c/li\u003e\u003c/ul\u003e\u003cp\u003e\u003cstrong\u003eUS-3. Управление персонализацией.\u003c/strong\u003e Как пользователь, я хочу отключить персональные рекомендации, чтобы мои данные не использовались.\u003c/p\u003e\u003cul\u003e\u003cli\u003eДано: пользователь выключил «Персональные рекомендации» в настройках. Тогда: в течение 5 минут блоки на главной заменяются на неперсонализированные, поведенческий профиль перестаёт обновляться.\u003c/li\u003e\u003cli\u003eДано: пользователь нажал «Сбросить историю рекомендаций». Тогда: профиль очищается, блоки переходят в режим нового пользователя, действие подтверждается сообщением.\u003c/li\u003e\u003c/ul\u003e\u003cp\u003e\u003cstrong\u003eUS-4. Управление статической подборкой.\u003c/strong\u003e Как маркетолог, я хочу настраивать содержимое блока «Популярное» без разработчиков, чтобы быстро реагировать на акции.\u003c/p\u003e\u003cul\u003e\u003cli\u003eДано: маркетолог добавил курсы в подборку в админке. Тогда: изменения видны на главной в течение 10 минут, история изменений сохраняется (кто, когда, что).\u003c/li\u003e\u003cli\u003eДано: в подборке меньше 6 активных курсов. Тогда: админка предупреждает, недостающие позиции заполняются автоматически по популярности.\u003c/li\u003e\u003c/ul\u003e\u003cp\u003e\u003cstrong\u003eUS-5. Аналитика.\u003c/strong\u003e Как продакт, я хочу видеть эффективность блоков, чтобы принять решение о второй версии.\u003c/p\u003e\u003cul\u003e\u003cli\u003eПо каждому блоку: показы, уникальные показы, клики, CTR, позиция курсов, конверсия клика в покупку (с атрибуцией 7 дней), доля пустых показов.\u003c/li\u003e\u003cli\u003eДашборд с разрезом по варианту A/B доступен с первого дня релиза.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e5. Альтернативные и граничные сценарии\u003c/h3\u003e\u003cul\u003e\u003cli\u003eНовый пользователь (cold start) → статические подборки; после 3 просмотров → персонализация (фиксируем порог в спецификации, а не «когда-нибудь»).\u003c/li\u003e\u003cli\u003eПользователь смотрел только бесплатные курсы → не показываем платные «в лоб»: правило — чередуем, чтобы не создавать ощущение «мне продают дорогое» (решение маркетинга, фиксируем).\u003c/li\u003e\u003cli\u003eПодборка пустая после всех исключений → фолбэк на «Популярное», никогда не показываем пустой блок и заголовок без содержимого.\u003c/li\u003e\u003cli\u003eСервис подборок недоступен → фолбэк за ≤ 200 мс, событие в мониторинг, главная страница работает.\u003c/li\u003e\u003cli\u003eПользователь отключил персонализацию → блоки без истории, никаких поведенческих данных не обрабатываем.\u003c/li\u003e\u003cli\u003eКурс снят с продажи → исключаем из подборок в течение 10 минут (событие из каталога), иначе пользователь кликает и видит ошибку.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e6. НФТ первой версии\u003c/h3\u003e\u003cul\u003e\u003cli\u003eВремя ответа блока ≤ 200 мс (p95), с кэшированием результата на пользователя на 10 минут.\u003c/li\u003e\u003cli\u003eДеградация: фолбэк обязателен, ошибка блока не влияет на остальную часть главной.\u003c/li\u003e\u003cli\u003eНагрузка: 180 тысяч пользователей, пик 300 RPS на главную — расчёт ёмкости кэша и хранилища профилей.\u003c/li\u003e\u003cli\u003eДоступность: блок не критичен для оформления покупки, поэтому его SLA ниже, чем у платёжного потока; это согласуем с бизнесом явно.\u003c/li\u003e\u003cli\u003eБезопасность/приватность: профили хранятся обезличенно (userId + вектор интересов), доступ по ролям, срок хранения 12 месяцев, удаление по запросу.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e7. Риски и открытые вопросы\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eРиск/вопрос\u003c/th\u003e\u003cth\u003eВладелец\u003c/th\u003e\u003cth\u003eСрок\u003c/th\u003e\u003cth\u003eМитигция\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eЦелевая метрика не согласована\u003c/td\u003e\u003ctd\u003eДиректор по маркетингу\u003c/td\u003e\u003ctd\u003e2 дня\u003c/td\u003e\u003ctd\u003eБез согласованной метрики не берём в спринт\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eКачество тегов курсов низкое (30% без тегов)\u003c/td\u003e\u003ctd\u003eКонтент-менеджер\u003c/td\u003e\u003ctd\u003e1 неделя\u003c/td\u003e\u003ctd\u003eДозаполнение тегов до релиза; иначе персонализация нерелевантна\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eТребуется ли согласие на персонализацию\u003c/td\u003e\u003ctd\u003eДПО/юрист\u003c/td\u003e\u003ctd\u003e3 дня\u003c/td\u003e\u003ctd\u003eЕсли да — добавляем экран согласия, это +2 дня разработки\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eНет событий просмотра карточек в аналитике\u003c/td\u003e\u003ctd\u003eРазработка\u003c/td\u003e\u003ctd\u003e3 дня\u003c/td\u003e\u003ctd\u003eЕсли нет — расширяем трекинг заранее, иначе правила строить не на чем\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eОжидание «как у X» = ML-рекомендации\u003c/td\u003e\u003ctd\u003eДиректор\u003c/td\u003e\u003ctd\u003e1 встреча\u003c/td\u003e\u003ctd\u003eПоказываем оценку: ML = 3+ месяца и данные; предлагаем проверить гипотезу правилами за 2 недели\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003ch3\u003e8. Что несу на планирование\u003c/h3\u003e\u003cp\u003eОдна страница: цель и гипотеза с метрикой, скоуп MVP (список «делаем/не делаем»), 5 user stories с критериями приёмки, схема блоков главной, список НФТ, открытые вопросы с владельцами и датами. Оценка разработки — 2 спринта (4 недели) при закрытых вопросах; дизайн — 3 дня параллельно.\u003c/p\u003e"}'::jsonb, updated_at = now() WHERE id = 'req-vague-feature';
UPDATE tasks SET statement = '{"brief":"Мобильное приложение получает данные «как получится». Нужен согласованный контракт, который переживёт обновления приложения.","context":["У продукта есть веб и мобильное приложение (iOS/Android). Бэкенд отдаёт данные через набор REST-эндпоинтов, которые исторически выросли из внутреннего API. Мобильная команда жалуется: при изменении полей приложение падает, пагинации нет (список из 5 000 элементов приходит целиком), ошибки возвращаются в разном формате, а старые версии приложения в маркете живут годами.","Сейчас 22% пользователей на версиях приложения старше 6 месяцев. Любое ломающее изменение API = тысячи неработающих установок и шквал отзывов.","Нужно спроектировать контракт для нового раздела «Мои операции» и зафиксировать правила, по которым API будет развиваться дальше."],"goal":"Описать контракт эндпоинтов раздела (методы, поля, типы, обязательность, коды ответов), правила версионирования и обратной совместимости, пагинацию, обработку ошибок и нефункциональные требования.","inputs":["Раздел «Мои операции»: список операций пользователя (до 5 000 за год), фильтр по периоду и типу, карточка операции с деталями, статусы операций меняются со временем.","Клиенты: мобильное приложение (iOS, Android) и веб. Версии приложения в маркете не обновляются принудительно.","Операции приходят из трёх внутренних систем, часть полей доступна не для всех типов операций.","Есть требование безопасности: не отдавать полные номера карт и счетов."],"deliverables":["Спецификация эндпоинтов: методы, пути, параметры запроса, состав ответов с типами и обязательностью, примеры.","Правила пагинации и сортировки для больших списков.","Единый формат ошибок: структура, коды, сообщения, что можно показывать пользователю.","Политика версионирования: где версия (URL/заголовок), что считается ломающим изменением, как поддерживаем старые клиенты, сроки поддержки.","Обратная совместимость: правила добавления/удаления полей, поведение клиента при неизвестном поле.","НФТ: время ответа, лимиты, кэширование, офлайн-поведение, деградация.","Процесс согласования контракта между мобильной командой и бэкендом, и как тестируем совместимость."],"constraints":["Нельзя сломать существующие версии приложения: минимум 12 месяцев поддержки.","Приложение работает в плохих сетях: нужен кэш и корректное поведение при таймаутах.","Команда бэкенда одна на веб и мобиль: решения должны быть общими, а не «специальный API под мобилку»."],"interview":"«Спроектируйте API для мобильного приложения. Как вы будете менять контракт, если 22% пользователей на старых версиях?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Спецификация","content":"\u003ch3\u003eЭндпоинты\u003c/h3\u003e\u003ch3\u003eПагинация\u003c/h3\u003e\u003ch3\u003eФормат ошибок\u003c/h3\u003e\u003ch3\u003eВерсионирование\u003c/h3\u003e"},{"type":"plantuml","title":"Sequence: загрузка списка","content":"@startuml\nautonumber\nactor \"Пользователь\" as U\nparticipant \"Мобильное приложение\" as APP\nparticipant \"API Gateway\" as GW\nparticipant \"Сервис операций\" as OPS\n\nU -\u003e APP: открыл \"Мои операции\"\nAPP -\u003e GW: GET /v1/operations?limit=30\\nIf-None-Match: ?\nGW -\u003e OPS: запрос\nOPS --\u003e GW: данные\nGW --\u003e APP: 200 / 304 / 4xx ?\nAPP --\u003e U: список\n@enduml\n"}]'::jsonb, rubric = '[{"id":"endpoint-spec","title":"Полная спецификация: методы, пути, параметры, поля ответа с типами и обязательностью, примеры запросов","weight":"high","weightValue":null,"focus":"sa","keywords":["get","post","/v1/","параметр","обязательн","тип","string","integer","пример","openapi","схем"],"why":"Контракт — это документ, по которому две команды работают параллельно. «Отдадим список операций» контрактом не является.","critical":false},{"id":"pagination","title":"Пагинация для больших списков: cursor-based (или offset с оговорками), limit, hasNext, стабильность при изменении данных","weight":"high","weightValue":null,"focus":"arch","keywords":["пагинац","cursor","offset","limit","page","hasnext","next_cursor","страниц","5000"],"why":"Условие прямо говорит: 5 000 элементов приходят целиком. Offset-пагинация на изменяющихся данных даёт дубли и пропуски — это надо обсудить.","critical":false},{"id":"error-format","title":"Единый формат ошибки: структура, машиночитаемый код, человекочитаемое сообщение, валидация полей, что показываем пользователю","weight":"high","weightValue":null,"focus":"sa","keywords":["ошибк","error","код","формат","валидац","field","сообщен","problem","400","404","422"],"why":"«Ошибки в разном формате» — одна из жалоб. Мобильное приложение должно различать «нет сети», «нет прав», «неверные данные».","critical":false},{"id":"versioning","title":"Политика версионирования: где указывается версия, что считается ломающим изменением, срок поддержки, как деприкейтим","weight":"high","weightValue":null,"focus":"arch","keywords":["верси","version","v1","v2","breaking","ломающ","поддержк","deprecat","заголовок","url","срок"],"why":"22% пользователей на старых версиях — ключевое ограничение. Без политики версионирования каждое изменение ломает часть аудитории.","critical":false},{"id":"compat-rules","title":"Правила обратной совместимости: добавление полей безопасно, удаление/переименование/смена типа — нет; поведение клиента при неизвестном поле","weight":"high","weightValue":null,"focus":"sa","keywords":["совместим","добавлен","удален","переименов","неизвестн","tolerant reader","backward","игнорир","обязательн полей"],"why":"Правило «клиент игнорирует неизвестные поля» должно быть зафиксировано, иначе добавление поля сломает парсинг.","critical":false},{"id":"security-fields","title":"Безопасность данных: маскирование карт/счетов, минимум данных в ответе, авторизация, запрет чужих операций","weight":"mid","weightValue":null,"focus":"sa","keywords":["маскир","последн","карт","счёт","безопасн","авториз","доступ","чуж","token","pii"],"why":"Ограничение требует не отдавать полные номера. Это надо отразить в контракте явно, а не надеяться на разработку.","critical":false},{"id":"caching-offline","title":"Кэширование и офлайн: ETag/If-None-Match, TTL, поведение без сети, повтор при таймауте, идемпотентность","weight":"mid","weightValue":null,"focus":"arch","keywords":["кэш","etag","if-none-match","304","офлайн","offline","ttl","cache-control","повтор","таймаут"],"why":"Ограничение «плохие сети» требует кэша и предсказуемого поведения при обрывах.","critical":false},{"id":"status-model","title":"Модель статусов операций: справочник значений, как клиент реагирует на новый статус, версионирование справочника","weight":"mid","weightValue":null,"focus":"sa","keywords":["статус","справочник","значен","enum","новый статус","unknown","маппинг","state"],"why":"Статусы меняются со временем, а старые версии приложения не знают новых значений. Нужна стратегия «unknown status».","critical":false},{"id":"process","title":"Процесс согласования: OpenAPI как источник истины, contract tests, кто утверждает изменения, как тестируем совместимость","weight":"mid","weightValue":null,"focus":"sa","keywords":["openapi","swagger","contract test","согласован","ревью","codegen","мок","источник истины","процесс"],"why":"Одна бэкенд-команда на веб и мобиль: без процесса согласования контракт живёт своей жизнью.","critical":false},{"id":"nfr-numbers","title":"НФТ с числами: p95 времени ответа, размер ответа, лимиты запросов, деградация","weight":"low","weightValue":null,"focus":"arch","keywords":["p95","мс","размер","лимит","rate","нагрузк","деградац","кб"],"why":"«Быстро» — не требование. Числа позволяют тестировать и принимать решение о кэше.","critical":false}]'::jsonb, hints = '["Cursor-пагинация против offset: что происходит, когда в список добавили новую операцию, пока пользователь листал?","Старое приложение не знает нового значения статуса. Упадет ли оно? Как этого избежать на уровне контракта?","Версия в URL или в заголовке — что удобнее для gateway, аналитики и поддержки старых клиентов?"]'::jsonb, interview_questions = '["Как вы удалите поле из ответа, если им пользуется старая версия приложения?","Почему cursor, а не page/offset?","Что вернёт API, если клиент пришлёт limit=100000?","Бэкенд добавил новое значение статуса. Что увидит пользователь на версии приложения двухлетней давности?","Как вы протестируете обратную совместимость перед релизом?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Эндпоинты раздела\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eGET /v1/operations\u003c/strong\u003e — список операций пользователя.\u003c/p\u003e\u003cp\u003eПараметры запроса:\u003c/p\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eПараметр\u003c/th\u003e\u003cth\u003eТип\u003c/th\u003e\u003cth\u003eОбяз.\u003c/th\u003e\u003cth\u003eОписание\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003ecursor\u003c/code\u003e\u003c/td\u003e\u003ctd\u003estring\u003c/td\u003e\u003ctd\u003eнет\u003c/td\u003e\u003ctd\u003eНепрозрачный курсор из предыдущего ответа\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003elimit\u003c/code\u003e\u003c/td\u003e\u003ctd\u003einteger\u003c/td\u003e\u003ctd\u003eнет\u003c/td\u003e\u003ctd\u003e1–100, по умолчанию 30; при превышении → 400 \u003ccode\u003einvalid_limit\u003c/code\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003efrom\u003c/code\u003e, \u003ccode\u003eto\u003c/code\u003e\u003c/td\u003e\u003ctd\u003edate (ISO 8601)\u003c/td\u003e\u003ctd\u003eнет\u003c/td\u003e\u003ctd\u003eПериод по дате операции; максимум 366 дней, иначе 400\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003etype\u003c/code\u003e\u003c/td\u003e\u003ctd\u003estring\u003c/td\u003e\u003ctd\u003eнет\u003c/td\u003e\u003ctd\u003eФильтр по типу из справочника; неизвестное значение → 400\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003ccode\u003estatus\u003c/code\u003e\u003c/td\u003e\u003ctd\u003estring\u003c/td\u003e\u003ctd\u003eнет\u003c/td\u003e\u003ctd\u003eФильтр по статусу; повторяется для нескольких значений\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003cp\u003eОтвет \u003ccode\u003e200\u003c/code\u003e:\u003c/p\u003e\u003cpre\u003e\u003ccode\u003e{\n  \"items\": [\n    {\n      \"id\": \"op_01H8ZK...\",            // string, обязат., стабильный идентификатор\n      \"type\": \"CARD_PAYMENT\",           // string, обязат., из справочника\n      \"status\": \"COMPLETED\",            // string, обязат., из справочника\n      \"amount\": { \"value\": \"1250.00\", \"currency\": \"RUB\" },  // string для денег!\n      \"title\": \"Продукты\",              // string, обязат., для отображения\n      \"merchantName\": \"ООО Ромашка\",     // string, может отсутствовать\n      \"cardMask\": \"4587\",               // string, только последние 4 цифры\n      \"occurredAt\": \"2026-10-04T12:31:00Z\",\n      \"detailsUrl\": \"/v1/operations/op_01H8ZK\"  // подсказка клиенту, где взять детали\n    }\n  ],\n  \"pagination\": { \"nextCursor\": \"eyJ...\", \"hasMore\": true },\n  \"meta\": { \"serverTime\": \"2026-10-05T09:00:00Z\", \"dictionaryVersion\": 3 }\n}\u003c/code\u003e\u003c/pre\u003e\u003cp\u003eПравила: сумма — строкой (избегаем проблем точности float у клиентов), время — ISO 8601 UTC, все даты и словари версионируются в \u003ccode\u003emeta\u003c/code\u003e.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eGET /v1/operations/{id}\u003c/strong\u003e — детали операции: расширенный состав (проводки, чеки, описание, история статусов). \u003ccode\u003e404\u003c/code\u003e при отсутствии или если операция не принадлежит пользователю (не раскрываем существование чужих данных).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eGET /v1/dictionaries/operation-types\u003c/strong\u003e — справочники типов и статусов с версиями: клиент может заранее знать, какие значения появятся, и маппить неизвестные на «Другое».\u003c/p\u003e\u003ch3\u003e2. Пагинация\u003c/h3\u003e\u003cp\u003eВыбираем \u003cstrong\u003ecursor-based\u003c/strong\u003e (ключевой курсор — \u003ccode\u003eoccurredAt\u003c/code\u003e + \u003ccode\u003eid\u003c/code\u003e, кодируется base64). Обоснование: список операций меняется постоянно (новые операции добавляются в начало). Offset-пагинация при вставке строки сдвигает окно → пользователь видит дубль или пропуск. Cursor стабилен: «дай следующие 30 после вот этой позиции».\u003c/p\u003e\u003cul\u003e\u003cli\u003e\u003ccode\u003elimit\u003c/code\u003e ограничен 100: защита от выгрузки всей истории одним запросом.\u003c/li\u003e\u003cli\u003e\u003ccode\u003ehasMore\u003c/code\u003e — признак наличия продолжения; \u003ccode\u003enextCursor\u003c/code\u003e отсутствует, если данных больше нет.\u003c/li\u003e\u003cli\u003eКурсор непрозрачный для клиента (не парсить, не собирать самому) — это даёт нам свободу менять стратегию сортировки.\u003c/li\u003e\u003cli\u003eСортировка фиксирована: по \u003ccode\u003eoccurredAt\u003c/code\u003e desc. Параметры сортировки не даём: каждый вариант сортировки = отдельный индекс и отдельная нагрузка.\u003c/li\u003e\u003cli\u003eДля веба с постраничным просмотром — отдельный режим \u003ccode\u003epage\u003c/code\u003e/\u003ccode\u003etotal\u003c/code\u003e на том же эндпоинте, но только для веб-клиента (фиксируем как исключение с обоснованием).\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e3. Единый формат ошибок\u003c/h3\u003e\u003cpre\u003e\u003ccode\u003e{\n  \"error\": {\n    \"code\": \"validation_failed\",        // машиночитаемый, стабилен, из справочника\n    \"message\": \"Проверьте введённые данные\",  // для пользователя, локализовано\n    \"details\": [                        // только для ошибок валидации\n      { \"field\": \"from\", \"issue\": \"date_out_of_range\", \"message\": \"Период не может превышать год\" }\n    ],\n    \"traceId\": \"tr_9f2a...\",            // для разбора инцидента\n    \"docUrl\": \"https://api.example.com/errors/validation_failed\"\n  }\n}\u003c/code\u003e\u003c/pre\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eHTTP\u003c/th\u003e\u003cth\u003ecode\u003c/th\u003e\u003cth\u003eЧто делает клиент\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e400\u003c/td\u003e\u003ctd\u003e\u003ccode\u003evalidation_failed\u003c/code\u003e, \u003ccode\u003einvalid_limit\u003c/code\u003e, \u003ccode\u003einvalid_cursor\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eПоказывает сообщение, не ретраит\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e401\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eunauthorized\u003c/code\u003e, \u003ccode\u003etoken_expired\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eОбновляет токен, повторяет один раз, иначе — на экран входа\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e403\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eforbidden\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eПоказывает «нет доступа», не ретраит\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e404\u003c/td\u003e\u003ctd\u003e\u003ccode\u003enot_found\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eПоказывает пустое состояние\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e429\u003c/td\u003e\u003ctd\u003e\u003ccode\u003erate_limited\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eПауза по \u003ccode\u003eRetry-After\u003c/code\u003e, затем повтор\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e500/503\u003c/td\u003e\u003ctd\u003e\u003ccode\u003einternal_error\u003c/code\u003e, \u003ccode\u003eservice_unavailable\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eРетрай с backoff, показывает кэш и «данные могли обновиться»\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003cp\u003eПравило для всех: \u003ccode\u003emessage\u003c/code\u003e не содержит технических деталей (стеков, имён таблиц), локализован; \u003ccode\u003ecode\u003c/code\u003e никогда не меняется для той же ситуации — на нём строится логика клиента.\u003c/p\u003e\u003ch3\u003e4. Версионирование и совместимость\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eГде версия:\u003c/strong\u003e в пути — \u003ccode\u003e/v1/...\u003c/code\u003e. Обоснование: проще для gateway, аналитики, логов и поддержки; заголовочная версия усложняет кэширование и отладку. Версия мажорная, меняется только при ломающих изменениях.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЧто считается ломающим:\u003c/strong\u003e удаление или переименование поля, смена типа поля, изменение семантики значения, добавление обязательного параметра запроса, сужение допустимых значений, изменение формата ошибки, удаление эндпоинта.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЧто НЕ ломающее (можно в рамках v1):\u003c/strong\u003e добавление необязательного поля ответа, добавление нового значения в справочник (при соблюдении правила unknown), добавление нового эндпоинта, добавление необязательного параметра запроса, исправление бага в пределах documented поведения.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eОбязательство клиента (фиксируем в требованиях к мобильной команде):\u003c/strong\u003e tolerant reader — парсить только известные поля, игнорировать неизвестные; значения справочников маппить на «Другое» при неизвестном значении; не завязываться на порядок полей и на отсутствие полей, помеченных необязательными. Это условие обратной совместимости с нашей стороны.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eСрок поддержки:\u003c/strong\u003e версия API поддерживается минимум 18 месяцев с момента выхода следующей версии или пока доля клиентов на версии \u0026gt; 1% (что наступит позже). Депrecation: заголовок \u003ccode\u003eDeprecation\u003c/code\u003e + \u003ccode\u003eSunset\u003c/code\u003e в ответах, уведомление в консоли разработчика, сообщение в приложении для старых версий, принудительное обновление только при критической уязвимости.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eКак живём со старыми версиями:\u003c/strong\u003e статистика по версиям приложения и API в аналитике gateway; дашборд «доля трафика по версиям»; решение о выводе версии принимает продуктовая команда на основе доли и стоимости поддержки.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e5. Безопасность данных\u003c/h3\u003e\u003cul\u003e\u003cli\u003eПолные номера карт и счетов не передаются никогда: только \u003ccode\u003ecardMask\u003c/code\u003e (последние 4) и \u003ccode\u003eaccountMask\u003c/code\u003e. В логах gateway маскирование на уровне доступа.\u003c/li\u003e\u003cli\u003eДоступ строго к своим операциям: \u003ccode\u003euserId\u003c/code\u003e берётся из токена, а не из параметра запроса; проверка владения — в сервисе, а не только в gateway.\u003c/li\u003e\u003cli\u003eПередача — только TLS 1.2+, сертификат-пиннинг в мобильном приложении; токены — короткие (15 мин) + refresh.\u003c/li\u003e\u003cli\u003eЧувствительные поля (сумма, merchant) не кэшируются в общий кэш устройства без защиты; локальный кэш приложения — в защищённом хранилище.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e6. Кэш, офлайн и НФТ\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003ccode\u003eETag\u003c/code\u003e на списках и деталях + поддержка \u003ccode\u003eIf-None-Match\u003c/code\u003e → \u003ccode\u003e304\u003c/code\u003e без тела: экономия трафика на медленных сетях.\u003c/li\u003e\u003cli\u003e\u003ccode\u003eCache-Control: private, max-age=60\u003c/code\u003e для списков (статусы операций меняются), \u003ccode\u003eno-store\u003c/code\u003e для чувствительных деталей по требованию безопасности.\u003c/li\u003e\u003cli\u003eОфлайн: приложение показывает кэш с пометкой «данные на [время]», операции из кэша помечены как «статус может быть неактуален»; при появлении сети — фоновое обновление.\u003c/li\u003e\u003cli\u003eРетраи: только на 5xx и сетевых ошибках, 3 попытки с backoff 1/3/9 сек + джиттер; GET идемпотентен, поэтому ретраи безопасны.\u003c/li\u003e\u003cli\u003eНФТ: p95 ≤ 250 мс для списка (30 элементов), p95 ≤ 150 мс для деталей; размер ответа списка ≤ 30 КБ; лимит 60 запросов в минуту на пользователя → 429 с \u003ccode\u003eRetry-After\u003c/code\u003e; деградация: при недоступности источника деталей отдаём список без расширенных полей и признак \u003ccode\u003epartial = true\u003c/code\u003e, а не ошибку.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e7. Процесс и тестирование совместимости\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eИсточник истины:\u003c/strong\u003e OpenAPI 3.1 в отдельном репозитории. Изменение контракта = pull request с ревью аналитика, мобильной команды и бэкенда. Генерация клиентских моделей и моков из спецификации.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eContract tests:\u003c/strong\u003e провайдерские (бэкенд отвечает согласно спецификации) и консьюмерские (мобильный клиент корректно обрабатывает ответы, включая неизвестные поля и новые значения справочников). Прогон в CI на каждый PR.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eПроверка ломающих изменений:\u003c/strong\u003e инструмент сравнения версий OpenAPI (oasdiff / аналог) блокирует слияние при breaking change без bumps версии.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eСогласование:\u003c/strong\u003e изменения справочников и полей — еженедельный слот «API-ревью» (30 минут) с участием обеих команд; срочные изменения — через канал с явным уведомлением и фиксацией решения.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eДо релиза:\u003c/strong\u003e прогон старых версий приложения (из архива сборок) против нового бэкенда на staging — минимум две предыдущие версии. Это закрывает риск «22% пользователей на старых версиях».\u003c/li\u003e\u003c/ul\u003e"}'::jsonb, updated_at = now() WHERE id = 'req-api-contract';
UPDATE tasks SET statement = '{"brief":"Коммерческий директор требует упростить скоринг, риск-менеджер запрещает. Релиз через три недели. Что делает аналитик?","context":["Онлайн-банк выдаёт кредиты физлицам. Сейчас при заявке клиент заполняет 14 полей, скоринг проверяет доходы через два внешних источника и запрашивает дополнительные документы у 30% заявителей. Конверсия в выдачу — 41%, среднее время решения — 22 минуты.","Коммерческий директор: «Конкуренты выдают за 5 минут по трём полям. Мы теряем рынок. Уберите лишние поля и документы, решение — мгновенно».","Директор по рискам: «Любое ослабление скоринга = рост NPL. Мы не подпишем изменения без данных о влиянии на портфель. И требования регулятора по оценке платёжеспособности никто не отменял».","Оба руководителя настаивают, оба подчиняются председателю правления. Релиз маркетинговой кампании «Быстрый кредит» запланирован через три недели, бюджет на рекламу уже согласован."],"goal":"Как аналитик: разобрать конфликт, собрать данные, найти варианты решения, которые удовлетворяют обе стороны (или честно показать компромисс), и подготовить решение для правления с оценкой эффекта и рисков.","inputs":["Данные за 6 месяцев: конверсия по шагам воронки, время заполнения заявки, доля отказов на каждом шаге, статистика запроса документов, NPL по сегментам и по источникам данных.","Регуляторные требования: обязательная оценка платёжеспособности, требования к хранению данных и к идентификации, лимиты по суммам.","Возможности: есть данные из бюро кредитных историй, есть доступ к данным о зарплатных клиентах, есть поведенческая аналитика в форме заявки.","Ограничения: 3 недели до кампании, команда разработки занята на 60% другими задачами."],"deliverables":["Карта стейкхолдеров: кто участвует, какие у них цели и метрики, где конфликт интересов, кто принимает решение.","Разбор требований обеих сторон: что стоит за «уберите поля» и «нельзя ослаблять» (задачи, а не позиции).","Данные, которые нужны для решения: какие гипотезы проверяем, откуда берём цифры, как считаем эффект.","Варианты решения (минимум три) с оценкой влияния на конверсию, риски, сроки и стоимость; рекомендация с обоснованием.","План проверки решения: пилот/A-B, метрики, критерии остановки, как масштабируем.","Решение для регуляторных ограничений: что нельзя менять ни при каких условиях и как это объяснить коммерческому директору.","План коммуникации: как и кому презентуем, что делаем при несогласии одной из сторон."],"constraints":["Нарушать регуляторные требования нельзя: это риск отзыва лицензии.","Релиз кампании через три недели: нужно решение, которое можно внедрить хотя бы частично.","Аналитик не принимает бизнес-решение сам, но обязан подготовить его так, чтобы решение было обоснованным."],"interview":"«Два директора требуют взаимоисключающего. Ваши действия как аналитика? Что вы принесёте на правление?»"}'::jsonb, starter_tabs = '[{"type":"doc","title":"Разбор и варианты","content":"\u003ch3\u003eКарта стейкхолдеров\u003c/h3\u003e\u003ch3\u003eЧто за требованиями\u003c/h3\u003e\u003ch3\u003eВарианты решения\u003c/h3\u003e\u003ch3\u003eПлан пилота\u003c/h3\u003e"},{"type":"mermaid","title":"Воронка заявки","content":"flowchart LR\n  A[Начал заявку 100%] --\u003e B[Заполнил поля 72%]\n  B --\u003e C[Прошёл скоринг 58%]\n  C --\u003e D[Предоставил документы 44%]\n  D --\u003e E[Одобрено 41%]\n  E --\u003e F[Взял кредит 33%]\n"}]'::jsonb, rubric = '[{"id":"stakeholder-map","title":"Карта стейкхолдеров: цели, метрики, влияние, кто принимает решение; конфликт интересов назван явно","weight":"high","weightValue":null,"focus":"sa","keywords":["стейкхолдер","карта","цел","метри","влиян","принимает решен","конфликт","правлен","интерес","rACI"],"why":"Без понимания, чьи KPI конфликтуют, аналитик будет «мирить позиции», а не решать задачу.","critical":false},{"id":"interests-not-positions","title":"Отделение позиции от интереса: что на самом деле нужно продажам (конверсия, время) и рискам (NPL, соответствие)","weight":"high","weightValue":null,"focus":"sa","keywords":["позиц","интерес","за задач","потребн","на самом деле","kpi","зачем"," underlying","мотив"],"why":"«Уберите поля» — позиция. Интерес — повысить конверсию и сократить время. Под интерес есть несколько решений, не только ослабление скоринга.","critical":false},{"id":"data-driven","title":"Данные для решения: анализ воронки, где реально теряем, влияние каждого поля и каждого документа на конверсию и на риск","weight":"high","weightValue":null,"focus":"sa","keywords":["воронк","данны","конверс","анализ","отток","шаг","статистик","влиян","отказ","метри"],"why":"Спор мнений решается цифрами. Если 60% оттока на шаге документов — убирать надо документы, а не поля.","critical":false},{"id":"options","title":"Минимум три варианта решения с оценкой эффекта, рисков, сроков и стоимости; рекомендация с обоснованием","weight":"high","weightValue":null,"focus":"sa","keywords":["вариант","опци","оценк","эффект","стоимост","срок","рекомендац","альтернатив","компромисс"],"why":"Аналитик приносит варианты, а не одно «правильное» решение. Правлению нужен выбор с цифрами.","critical":false},{"id":"regulatory","title":"Регуляторные границы: что нельзя менять, как это проверить и как объяснить бизнесу на их языке","weight":"high","weightValue":null,"focus":"sa","keywords":["регулятор","закон","лиценз","обязательн","нельзя","соответств","compliance","требован","оценка платёжеспособ"],"why":"Ограничение прямо говорит про риск отзыва лицензии. Игнорирование = провал задачи.","critical":false},{"id":"risk-metrics","title":"Рисковые метрики и как их считаем: NPL, approval rate, доля дефолтов по сегментам, влияние изменений на портфель","weight":"high","weightValue":null,"focus":"sa","keywords":["npl","дефолт","approval","одобрен","портфел","риск","сегмент","скоринг","влиян","просрочк"],"why":"Риск-менеджер требует данных о влиянии на портфель. Без этих метрик разговор не состоится.","critical":false},{"id":"pilot","title":"План проверки: пилот/A-B на сегменте, метрики, срок, критерии остановки и масштабирования","weight":"high","weightValue":null,"focus":"sa","keywords":["пилот","a/b","эксперимент","сегмент","критер","остановк","масштаб","тест","контрольн"],"why":"Три недели и конфликт: пилот — единственный способ принять решение без ставки на всё портфель.","critical":false},{"id":"quick-wins","title":"Что можно сделать за три недели без изменения скоринга: UX-правки, предзаполнение, сокращение документов по данным","weight":"mid","weightValue":null,"focus":"sa","keywords":["ux","предзаполн","быстр","три недел","без скоринг","интерфейс","автозаполн","документ","упрост"],"why":"Ограничение по срокам требует частичного решения к кампании. Аналитик должен найти его.","critical":false},{"id":"segmentation","title":"Сегментация: разные правила для разных клиентов (зарплатные, повторные, низкие суммы) вместо одного правила для всех","weight":"mid","weightValue":null,"focus":"sa","keywords":["сегмент","зарплатн","повторн","сумм","категор","разные правил","дифференц","скоринг по сегмент"],"why":"Классическое решение конфликта: ослабить там, где риск объективно низкий, и оставить строгость там, где он высокий.","critical":false},{"id":"communication","title":"План коммуникации и эскалации: как презентуем, что при несогласии, кто арбитр, как фиксируем решение","weight":"mid","weightValue":null,"focus":"sa","keywords":["коммуникац","презентац","эскалац","арбитр","протокол","согласован","встреч","решен","фиксиру"],"why":"Конфликт двух директоров без процесса эскалации = проект стоит. Аналитик обязан предложить механику решения.","critical":false},{"id":"monitoring","title":"Мониторинг после внедрения: метрики, пороги, откат, ответственность за результат","weight":"low","weightValue":null,"focus":"sa","keywords":["мониторинг","порог","откат","контроль","дашборд","ответств","после внедрен","регулярн"],"why":"Риск-менеджер согласится только с механизмом контроля и возможностью откатить изменения.","critical":false}]'::jsonb, hints = '["Посмотрите на воронку: где теряется больше всего? 72% доходит до конца заполнения полей, но только 44% предоставляют документы.","«Мгновенное решение» и «оценка платёжеспособности» совместимы, если данные берутся из источников, а не из полей формы. Какие источники у нас есть?","Что можно запустить за три недели без изменения скоринговых правил?"]'::jsonb, interview_questions = '["Кто в этой истории принимает решение и что нужно ему показать?","Как вы проверите, что сокращение полей не ухудшит портфель?","Риск-менеджер говорит «нет» любому ослаблению. Что вы ему предложите?","Кампания через три недели. Что успеваем?","Правление спросило: «сколько мы заработаем и сколько рискуем потерять?» Ваш ответ?"]'::jsonb, author_solution = '{"doc":"\u003ch3\u003e1. Карта стейкхолдеров\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eКто\u003c/th\u003e\u003cth\u003eЦель / KPI\u003c/th\u003e\u003cth\u003eПозиция\u003c/th\u003e\u003cth\u003eИнтерес (что за позицией)\u003c/th\u003e\u003cth\u003eВлияние\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eКоммерческий директор\u003c/td\u003e\u003ctd\u003eВыдачи, конверсия, доля рынка, срок кампании\u003c/td\u003e\u003ctd\u003e«Убрать поля и документы, мгновенное решение»\u003c/td\u003e\u003ctd\u003eРост выдач при том же рекламном бюджете; не потерять кампанию\u003c/td\u003e\u003ctd\u003eВысокое, инициатор кампании\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eДиректор по рискам\u003c/td\u003e\u003ctd\u003eNPL, стоимость риска, соответствие требованиям\u003c/td\u003e\u003ctd\u003e«Никаких ослаблений без данных»\u003c/td\u003e\u003ctd\u003eНе получить рост дефолтов и предписание регулятора; сохранить управляемость портфеля\u003c/td\u003e\u003ctd\u003eВысокое, право вето\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eCompliance / юрист\u003c/td\u003e\u003ctd\u003eСоответствие регуляторным требованиям\u003c/td\u003e\u003ctd\u003eНе участвует активно, но блокирует\u003c/td\u003e\u003ctd\u003eИзбежать нарушения оценки платёжеспособности и идентификации\u003c/td\u003e\u003ctd\u003eВето по вопросам права\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eПредседатель правления\u003c/td\u003e\u003ctd\u003eФинансовый результат и репутация\u003c/td\u003e\u003ctd\u003eАрбитр\u003c/td\u003e\u003ctd\u003eРешение с понятным соотношением дохода и риска\u003c/td\u003e\u003ctd\u003eФинальное решение\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eРуководитель разработки\u003c/td\u003e\u003ctd\u003eСроки, загрузка команды\u003c/td\u003e\u003ctd\u003e«60% команды занято»\u003c/td\u003e\u003ctd\u003eНе сорвать другие релизы\u003c/td\u003e\u003ctd\u003eСреднее, влияет на сроки\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eПоддержка / операционный отдел\u003c/td\u003e\u003ctd\u003eЧисло обращений, ручные проверки\u003c/td\u003e\u003ctd\u003eНе участвует\u003c/td\u003e\u003ctd\u003eНе получить волну ручных разборов при упрощении\u003c/td\u003e\u003ctd\u003eНизкое, но влияет на экономику\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003cp\u003e\u003cstrong\u003eКто принимает решение:\u003c/strong\u003e председатель правления по представлению аналитика при обязательном заключении рисков и compliance. Задача аналитика — не «помирить», а подготовить обоснованное решение и процесс его проверки.\u003c/p\u003e\u003ch3\u003e2. Разбор требований: позиция → интерес\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eПродажи:\u003c/strong\u003e позиция «убрать поля». Интерес — (а) сократить время заявки, (б) уменьшить отток на шагах, (в) сохранить кампанию в срок. Ни один интерес не требует именно ослабления скоринга: он требует меньше ручных шагов для клиента.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eРиски:\u003c/strong\u003e позиция «нельзя ослаблять». Интерес — (а) не потерять качество портфеля, (б) иметь данные для оценки влияния, (в) сохранить соответствие требованиям и возможность откатить изменение. Это означает не «ничего не менять», а «менять только с измеряемым эффектом и контролем».\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eТочка совпадения:\u003c/strong\u003e обе стороны согласны на изменения, эффект которых измерим и обратим. Значит, решение — не выбор «упростить vs запретить», а \u003cstrong\u003eсегментация + автоматизация данных + пилот\u003c/strong\u003e.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e3. Что говорят данные (анализ воронки)\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003eШаг\u003c/th\u003e\u003cth\u003eДоходимость\u003c/th\u003e\u003cth\u003eПотеря\u003c/th\u003e\u003cth\u003eЧто проверяем\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eНачал заявку\u003c/td\u003e\u003ctd\u003e100%\u003c/td\u003e\u003ctd\u003e—\u003c/td\u003e\u003ctd\u003e—\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eЗаполнил 14 полей\u003c/td\u003e\u003ctd\u003e72%\u003c/td\u003e\u003ctd\u003e28 п.п.\u003c/td\u003e\u003ctd\u003eНа каких полях отвал (поведенческая аналитика формы), время заполнения, доля ошибок валидации\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eПрошёл скоринг\u003c/td\u003e\u003ctd\u003e58%\u003c/td\u003e\u003ctd\u003e14 п.п.\u003c/td\u003e\u003ctd\u003eПричины отказов: скоринговый балл, отсутствие данных в БКИ, ошибки в полях\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eПредоставил документы\u003c/td\u003e\u003ctd\u003e44%\u003c/td\u003e\u003ctd\u003e14 п.п.\u003c/td\u003e\u003ctd\u003eКакие документы запрашиваем, у кого, сколько ждём, сколько не доносят\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eОдобрено\u003c/td\u003e\u003ctd\u003e41%\u003c/td\u003e\u003ctd\u003e3 п.п.\u003c/td\u003e\u003ctd\u003e—\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eВзял кредит\u003c/td\u003e\u003ctd\u003e33%\u003c/td\u003e\u003ctd\u003e8 п.п.\u003c/td\u003e\u003ctd\u003eОтказ после одобрения: условия, срок, конкуренция\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003cp\u003e\u003cstrong\u003eВыводы для решения:\u003c/strong\u003e наибольшие потери — заполнение полей (28 п.п.) и документы (14 п.п.), при этом скоринговый отказ даёт 14 п.п. Это значит: упрощение ввода и сокращение запроса документов дадут больший эффект, чем ослабление скоринговых правил. А ослабление скоринга бьёт ровно по тому, за что отвечает риск-функция, при сравнительно небольшом выигрыше в конверсии.\u003c/p\u003e\u003ch3\u003e4. Варианты решения\u003c/h3\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e№\u003c/th\u003e\u003cth\u003eВариант\u003c/th\u003e\u003cth\u003eЭффект на конверсию (оценка)\u003c/th\u003e\u003cth\u003eРиск для портфеля\u003c/th\u003e\u003cth\u003eСрок\u003c/th\u003e\u003cth\u003eСтоимость\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eA\u003c/td\u003e\u003ctd\u003e\u003cstrong\u003eСокращение формы до 6 полей + автозаполнение из данных\u003c/strong\u003e: берём ФИО, телефон, сумму, срок; остальное — из БКИ, данных работодателя (для зарплатных клиентов), Госуслуг/профиля с согласия клиента. Оставшиеся поля запрашиваем после предварительного одобрения\u003c/td\u003e\u003ctd\u003e+8–12 п.п. на шаге заполнения (28 → 16–20 п.п. потерь)\u003c/td\u003e\u003ctd\u003eНе меняется: данные те же, меняется источник\u003c/td\u003e\u003ctd\u003e2–3 недели (интеграции частично готовы)\u003c/td\u003e\u003ctd\u003eСредняя: 2 разработчика, интеграция с источником данных\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eB\u003c/td\u003e\u003ctd\u003e\u003cstrong\u003eОтмена документов для сегментов низкого риска\u003c/strong\u003e: зарплатные клиенты, повторные заёмщики с хорошей историей, суммы до N — решение по данным, без справок. Для остальных — как сейчас\u003c/td\u003e\u003ctd\u003e+6–10 п.п. на шаге документов в сегменте (сегмент ≈ 45% заявок)\u003c/td\u003e\u003ctd\u003eУправляемый: сегмент уже имеет подтверждённый доход/историю; ожидаемый рост NPL \u0026lt; 0,1 п.п.\u003c/td\u003e\u003ctd\u003e2 недели (изменение правил в скоринговой модели — настройка, не релиз)\u003c/td\u003e\u003ctd\u003eНизкая\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eC\u003c/td\u003e\u003ctd\u003e\u003cstrong\u003eПредодобренный лимит\u003c/strong\u003e: для клиентов с известным доходом считаем лимит заранее, заявка = подтверждение желания в 2 клика\u003c/td\u003e\u003ctd\u003eДо +15 п.п. в сегменте, плюс сокращение времени до \u0026lt; 5 минут\u003c/td\u003e\u003ctd\u003eНизкий (решение принято до заявки, по полным данным)\u003c/td\u003e\u003ctd\u003e6–8 недель (нужен расчёт лимитов и хранилище предложений)\u003c/td\u003e\u003ctd\u003eВысокая\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eD\u003c/td\u003e\u003ctd\u003e\u003cstrong\u003eОслабление скоринговых порогов для всех\u003c/strong\u003e (то, что просил коммерческий директор в исходной формулировке)\u003c/td\u003e\u003ctd\u003e+3–5 п.п. конверсии\u003c/td\u003e\u003ctd\u003e\u003cstrong\u003eВысокий:\u003c/strong\u003e рост одобрений на 12–18% при неизменном качестве заявителей → ожидаемый рост NPL +0,4–0,8 п.п. за 12 мес; по нашей оценке это убыток, превышающий дополнительную маржу\u003c/td\u003e\u003ctd\u003e1 неделя\u003c/td\u003e\u003ctd\u003eНизкая по разработке, высокая по потерям\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eE\u003c/td\u003e\u003ctd\u003e\u003cstrong\u003eНичего не менять\u003c/strong\u003e, кампания идёт на текущей воронке\u003c/td\u003e\u003ctd\u003e0\u003c/td\u003e\u003ctd\u003e0\u003c/td\u003e\u003ctd\u003e—\u003c/td\u003e\u003ctd\u003eПотеря маркетингового бюджета и доли рынка\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003cp\u003e\u003cstrong\u003eРекомендация:\u003c/strong\u003e A + B к кампании (обе укладываются в три недели, не ослабляют скоринг, дают наибольший измеримый прирост), C — как второй квартал, D — не рекомендовать и показать правлению расчёт потерь (это ключевой аргумент в разговоре с коммерческим директором: мы не «запрещаем», а показываем экономику).\u003c/p\u003e\u003ch3\u003e5. Регуляторные границы (что нельзя)\u003c/h3\u003e\u003cul\u003e\u003cli\u003eОценка платёжеспособности обязательна: нельзя выдавать кредит без подтверждения дохода из допустимого источника. Поэтому вариант «3 поля и мгновенное решение без проверки» невозможен в принципе — но возможен, если данные приходят автоматически из источников (вариант A).\u003c/li\u003e\u003cli\u003eИдентификация клиента и требования к хранению данных — без изменений.\u003c/li\u003e\u003cli\u003eИзменение скоринговых правил требует уведомления/согласования по внутреннему регламенту и фиксации методики: вариант D не только рискованный, но и долгий по согласованию.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eКак объясняем коммерческому директору:\u003c/strong\u003e не «риски запрещают», а «конкурент выдаёт за 5 минут не потому, что не проверяет, а потому что данные приходят автоматически. Наш путь — то же самое, но без риска получить предписание и рост дефолтов. Вот расчёт: вариант D даёт +4 п.п. конверсии и +0,6 п.п. NPL, это минус N млн рублей за год. Варианты A+B дают +10 п.п. без роста риска».\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e6. Пилот и проверка\u003c/h3\u003e\u003cul\u003e\u003cli\u003e\u003cstrong\u003eДизайн:\u003c/strong\u003e A/B на 20% трафика новых заявок в течение 4 недель (сегмент случайный, стратифицированный по сумме и региону, чтобы не получить смещение). Контроль — текущая воронка.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eМетрики:\u003c/strong\u003e конверсия по шагам (заполнение, документы, одобрение, выдача), время до решения, доля заявок с ручным разбором, стоимость привлечения выдачи, approval rate, а для риска — ранние индикаторы: FPD30 (первая просрочка через 30 дней), доля одобрений с низким баллом, структура выдач по сегментам. NPL как финальная метрика наблюдаем 6–12 месяцев.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eКритерии остановки:\u003c/strong\u003e рост доли одобрений в низкоскоринговом сегменте более чем на 3 п.п.; FPD30 выше контроля на 20% относительно; рост ручных разборов более чем на 15% (удар по операционным расходам); любые замечания compliance.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eМасштабирование:\u003c/strong\u003e при успехе — на 100% трафика с сохранением мониторинга и ежеквартальным пересмотром правил; решение о расширении сегментов B — по данным пилота.\u003c/li\u003e\u003c/ul\u003e\u003ch3\u003e7. Коммуникация и процесс решения\u003c/h3\u003e\u003col\u003e\u003cli\u003e\u003cstrong\u003eДень 1–2:\u003c/strong\u003e отдельные встречи с коммерческим директором и директором по рискам (не вместе!). На каждой — одна задача: превратить позицию в интерес и получить критерии приемлемого решения. Риск-менеджеру: «какие данные вам нужны, чтобы рассмотреть изменение?» Продажам: «какая конверсия и какое время до решения считаются успехом кампании?»\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eДень 3–5:\u003c/strong\u003e сбор данных (воронка, причины отказов, статистика документов, NPL по сегментам), экспресс-оценка эффекта вариантов, черновик расчёта D.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eДень 6–7:\u003c/strong\u003e совместная встреча на 60 минут: показываем данные (не мнения), четыре варианта с цифрами, рекомендацию A+B, границы регуляторики. Фиксируем протоколом: что согласовано, что проверяем пилотом, кто за что отвечает.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eДень 8:\u003c/strong\u003e представление правлению: один слайд с воронкой, один — с вариантами и экономикой, один — с планом пилота и критериями остановки. Решение правления фиксируем, включая согласие рисков на пилот.\u003c/li\u003e\u003cli\u003e\u003cstrong\u003eЕсли согласия нет:\u003c/strong\u003e эскалация председателю с явным описанием цены каждого варианта (в деньгах), а не «кто прав». Аналитик не принимает решение, но обязан сделать цену каждого варианта видимой.\u003c/li\u003e\u003c/ol\u003e\u003ch3\u003e8. Мониторинг после внедрения\u003c/h3\u003e\u003cul\u003e\u003cli\u003eДашборд: конверсия по шагам в разрезе варианта, approval rate, FPD30/FPD90, доля ручных разборов, обращения в поддержку по теме заявки.\u003c/li\u003e\u003cli\u003eПороги и алерты: отклонение FPD30 от контроля более 20% — автоматическое уведомление рисков и приостановка масштабирования (право вето риск-менеджера закрепляем в регламенте заранее — это снимает его сопротивление).\u003c/li\u003e\u003cli\u003eРегулярность: еженедельный статус первые 8 недель, затем ежемесячный; ежеквартальный пересмотр правил сегментации.\u003c/li\u003e\u003cli\u003eОтветственность: владелец метрики конверсии — коммерческий директор, владелец метрики риска — директор по рискам, аналитик ведёт дашборд и пересчёт эффектов. Это фиксируем в решении правления, чтобы через полгода не оказалось, что «никто не следил».\u003c/li\u003e\u003c/ul\u003e"}'::jsonb, updated_at = now() WHERE id = 'req-stakeholder-conflict';
